(window.HANMAP_TRIVIA_BODY = window.HANMAP_TRIVIA_BODY || {})["hi"] = {"kanbun-yomi-invention":"<h3>उधार से परिवर्तन तक</h3><p>चीनी लिपि शायद कोरियाई प्रायद्वीप के रास्ते लगभग 4वीं-5वीं शताब्दी ई. में जापान पहुँची। शुरू में जापान में लिखने का मतलब था चीनी लिखना। अक्षर सिर्फ़ अपनी ध्वनि के लिए उधार लिए जाते थे, ज़्यादातर जापानी नाम लिखने में, जैसे इनारियामा तलवार के लेख में (आम तौर पर 471 ई. का माना जाता है, हालाँकि 531 के पक्ष में भी तर्क दिए गए हैं)। ध्वनि वाला यही प्रयोग, जिसके आगे विकसित रूप को विद्वान <em>मान्योगाना</em> (万葉仮名) कहते हैं, जल्द ही पूरे शब्दों और कविताओं तक फैल गया। उदाहरण के लिए 「あめ」 (वर्षा) को 「阿米」 लिखा जाता था — अर्थ छोड़कर सिर्फ़ ध्वनि ली जाती थी।</p><h3>अर्थ से पढ़ना</h3><p>लगभग 700 ई. के आसपास — कोजिकि (712) और निहोन शोकि (720) के युग में — एक और चलन पूरी तरह सामने आ चुका था। लिपिक अक्षर को उसकी चीनी ध्वनि से नहीं, बल्कि उसके <em>अर्थ</em> से पढ़ते थे, और उसकी जगह मूल यामातो शब्द बोलते थे। 山 (चीनी: shān) को <em>yama</em> पढ़ा जाने लगा; 水 (shuǐ) को <em>mizu</em>। यही है <strong>कुन-योमि (訓読み)</strong>, यानी \"अर्थ से पढ़ना\"। शुरू में यह कतई सुव्यवस्थित नहीं था। एक अक्षर पर कई अलग-अलग देशी अर्थ-शब्द लद सकते थे, और 12वीं सदी का शब्दकोश <em>रुइजू म्योगिशो</em> कुछ अक्षरों के लिए 30 से ज़्यादा गिनाता है। मुरोमाची काल (14वीं–16वीं सदी) तक जाकर ही ज़्यादातर अक्षर कुछ तय कुन-पाठों पर टिक पाए।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='山'>नक्शे पर 山 दिखाएँ</button><button type='button' class='trivia-action' data-action='focus' data-code='ja_kun'>कुन-योमि (जापानी देशी पाठ) की परत दिखाएँ</button></div><h3>अन्य सिनोस्फेयर परंपराओं से तुलना</h3><p>कोरिया और वियतनाम ने भी चीनी अक्षर अपनाए — और अक्षर को देशी शब्द से पढ़ने का विचार वहाँ भी उठा। कोरियाई लिपिकार शास्त्रीय चीनी पाठ पर सोकतोक गुग्योल (석독구결, 釋讀口訣) के चिह्न लगाते थे, ताकि उसे देशी कोरियाई शब्दों में और कोरियाई वाक्य-क्रम में पढ़ा जा सके; आज भी कोरियाई हांजा का <em>नाम</em> अर्थ और ध्वनि की जोड़ी से बनता है — 水 को 물 수 (<em>mul su</em>) कहते हैं, अर्थात् पानी और उसकी चीनी-कोरियाई ध्वनि। वियतनाम की <em>chữ Nôm</em> लिपि तो और आगे गई: अर्थ के आधार पर अक्षर चुनकर लिखना इतना आम हो गया कि देशी पाठ दर्शाने के लिए एक चिह्न (<em>nháy</em>, 𖿱) ही गढ़ा गया — 本 का चीनी-वियतनामी पाठ <em>bản</em> है, पर 本𖿱 का पाठ <em>vốn</em>। जापान में देशी पाठ रोज़मर्रा के लेखन का हिस्सा बन गए और आज भी चलन में हैं; दूसरी जगहों पर ऐसे चलन ज़्यादातर शास्त्रीय विद्वत्ता तक, या बाद में छूट चुकी लिपियों तक, सीमित रहे। जापान ने इस दोहरी व्यवस्था को बाक़ायदा संस्थागत रूप दे दिया: आधुनिक कांजी शब्दकोश हर अक्षर का <em>ओन-योमि</em> (音読み, चीनी-व्युत्पन्न ध्वनि) और, अगर हो, तो उसका <em>कुन-योमि</em> (訓読み, देशी शब्द) साथ-साथ देता है। कुछ अक्षरों को देशी पाठ कभी मिला ही नहीं, क्योंकि वह चीज़ ख़ुद चीन से आई थी: 菊 \"गुलदाउदी\" है <em>kiku</em>, जो सुनने में देसी लगता है पर असल में उसका चीनी पाठ है। जापान ने पूरे पाठों के लिए भी यही तकनीक बचाए रखी: <em>कानबुन कुनदोकु</em>, यानी शास्त्रीय चीनी को पन्ने से सीधे जापानी के रूप में पढ़ना, जिसमें レ और 一・二 जैसे छोटे चिह्न पाठक को बताते हैं कि किस शब्द पर पीछे लौटना है।</p><h3>मान्योगाना से काना तक</h3><p>ध्वनि के लिए अक्षर उधार लेने की सबसे अच्छी मिसाल मान्योशू संकलन (लगभग 759 ई.) है: 安=あ, 以=い, 宇=う। अगली सदियों में ये ध्वन्यात्मक प्रयोग सरल होकर दो काना शब्दांश-लिपियाँ बने: <em>हिरागाना</em>, पूरे अक्षरों के बहते घसीट रूपों से, और <em>कातागाना</em>, अक्षरों के उन टुकड़ों से जिन्हें भिक्षु पढ़ने में मदद के लिए चीनी पाठों की पंक्तियों के बीच ठूँस देते थे। पर कुन-योमि परत इनके साथ-साथ बनी रही।</p><h3>आधुनिक शब्दकोशों में दिए गए पाठ</h3><p>अकेले 生 अक्षर के कम-से-कम एक दर्जन मान्य पाठ हैं: ओन-योमि セイ, ショウ; कुन-योमि いきる, うまれる, はえる, なま, आदि। ओन-योमि उधार की अलग-अलग लहरों से आते हैं (<em>shō</em> पुराना गो-ऑन है, <em>sei</em> तांग-कालीन कान-ऑन, और शब्दकोश बाद का एक दुर्लभ तो-ऑन, <em>san</em>, भी दर्ज करते हैं); कुन-योमि में देशी यामातो शब्दावली बची है। इसलिए आधुनिक मिश्रित-लिपि जापानी पाठ एक साथ कई ऐतिहासिक परतों को दिखा सकता है।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"34.69\" data-lng=\"135.50\" data-zoom=\"6\">🗺 नारा / ओसाका की ओर जाएँ</button></div>\n","kanbun-kaeriten-system":"<h3>समस्या: दो भाषाएँ, विपरीत शब्द-क्रम</h3><p>शास्त्रीय चीनी (漢文, कानबुन) में कर्ता–क्रिया–कर्म (SVO) क्रम है: 「我愛汝」 का अर्थ उसी क्रम में 'मैं तुमसे प्रेम करता हूँ' है। शास्त्रीय जापानी SOV है — वही विचार 「我汝ヲ愛ス」 होगा। जापानी विद्वानों को एक ऐसी विधि चाहिए थी जिससे वे चीनी पाठ को अलग जापानी अनुवाद बनाए बिना उसी मूल पाठ से जापानी में ज़ोर से पढ़ सकें। उनका हल था चिह्नों का एक पूरा तंत्र, जो जापानी पाठ भी बताता था और पढ़ने का बदला हुआ क्रम भी।</p><h3>レ点: सबसे सरल चिह्न</h3><p><strong>レ点 (रे-तेन)</strong> काताकाना 'レ' जैसा दिखता है और अक्षर के नीचे-बाईं ओर लगाया जाता है। इसका अर्थ है: 'अगले अक्षर को पहले पढ़ो, फिर यहाँ वापस आओ।' यदि 読書 में 読 पर レ चिह्न है, तो पहले 書 पढ़ें फिर 読 — SOV क्रम 書ヲ読ム ('पुस्तक पढ़ना') मिलता है। एक छोटा-सा चिह्न पास-पास के दो अक्षरों का क्रम उलट देता है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='見'>नक्शे पर 見 दिखाएँ</button><button type='button' class='trivia-action' data-action='focus' data-code='ja'>ओन-योमि परत दिखाएँ</button></div><h3>一二点 और 上下点: बहु-स्तरीय क्रम-बदलाव</h3><p>जब लौटती छलाँग बीच के एक या अधिक अक्षरों को लाँघकर पीछे जाती है, तब <strong>一二点 (इची-नि-तेन)</strong> का उपयोग होता है: लौटने का क्रम बताने के लिए अक्षरों के बगल में 一, 二, 三 लिखे जाते हैं। पंक्ति को ऊपर से नीचे सीधे पढ़ते जाइए और '二' चिह्नित अक्षर को छोड़ दीजिए; '一' चिह्नित अक्षर पढ़ लेने के बाद ही '二' चिह्नित अक्षर पर लौटिए। 「登二泰山一」 में क्रम 泰, फिर 山, फिर 登 होगा — 'ताई पर्वत पर चढ़ना' 泰山に登る बनकर निकलता है। गहरे उत्क्रमण के लिए <strong>上下点</strong> और <strong>甲乙点</strong> जोड़े जाते हैं। सिद्धांततः कोई भी SVO वाक्यांश, चाहे कितना ही गुँथा हुआ हो, मूल पाठ को छुए बिना केवल इन चिह्नों से SOV क्रम में मोड़ा जा सकता है।</p><h3>क्षेत्रीय तुलना और निरंतर उपयोग</h3><p>चीनी ग्रंथ पूरे सिनोस्फेयर में पढ़े जाते थे — कोरिया में (한문, हानमुन), वियतनाम में (Hán văn), और रयूक्यू में। वियतनामी में, चीनी की तरह, क्रिया कर्म से पहले आती है, इसलिए वियतनामी पाठक पाठ को सीधे चीनी-वियतनामी उच्चारण में पढ़ सकते थे। पर कोरियाई, जापानी की तरह, क्रिया को अंत में रखती है; उसे भी शब्द-क्रम का वही बेमेल झेलना पड़ा, और कोरिया ने भी पन्ने पर ठीक यही किया। कोरयो काल का <strong>석독구결</strong> (釋讀口訣, सोकतोक कुग्योल; इसे 역독구결 यानी 'उलटकर पढ़ने वाला कुग्योल' भी कहते हैं) ग्यारहवीं सदी से प्रमाणित है — यह या तो स्याही से लिखा जाता था या बिना स्याही की नुकीली कलम (角筆) से कागज़ पर दबाकर खोदा जाता था — और इसमें बदले जाने वाला कोरियाई शब्द तथा पंक्ति में पीछे लौटने का क्रम, दोनों अंकित होते थे। लौटकर पढ़ने के ऐसे ही प्रयोग खितान और उइगुर के लिए भी मिलते हैं। जापान की विशेषता आविष्कार नहीं, निरंतरता है। कोरिया में इसकी जगह 순독구결 (順讀口訣) ने ले ली, जो पाठ को चीनी क्रम में सीधे पढ़ता है; जबकि जापान के 返り点 मानकीकृत हुए, मूल पाठ के साथ ही छपे और आधुनिक युग तक लगातार पढ़ाए गए — इसीलिए आज भी 漢文訓読 प्रणाली विद्वानों को <em>मूल अपरिवर्तित चीनी पाठ</em> से सीधे स्वाभाविक जापानी में ज़ोर से पढ़ने देती है।</p><h3>शैक्षणिक विरासत</h3><p>मेइजी युग (1868+) और 20वीं सदी तक कानबुन ज्ञान जापानी शिक्षित व्यक्ति की पहचान था। समुराई, भिक्षु, विद्वान और अधिकारी सभी बचपन से 返り点 के सहारे पाठ पढ़ने का अभ्यास करते थे। मेइजी युग के कुछ सुधारकों ने कांजी को ही पूरी तरह ख़त्म करने का प्रस्ताव रखा (मोरी आरिनोरी ने तो अंग्रेज़ी अपना लेने की बात तक छेड़ दी), पर ये प्रस्ताव कभी जीत नहीं पाए। आज भी कानबुन जापानी हाई स्कूल के पाठ्यक्रम में है, और 「不亦楽乎」 जैसे वाक्यांश को 一二点 की मदद से पढ़ना (पहले 亦 और 楽, फिर उछलकर वापस 不) ठीक वही कौशल है जिसे राष्ट्रीय विश्वविद्यालय प्रवेश परीक्षा का कानबुन खंड परखता है।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.69\" data-zoom=\"5\">🗺 जापान की ओर जाएँ</button></div>\n\n<h3>लिखित जापानी पर प्रभाव</h3><p>कानबुन आज भी आधुनिक जापानी की औपचारिक लिखित शैली में दिखाई देता है। विधिक जापानी और समाचारपत्रों के संपादकीय आज भी ऐसे शब्द और बँधे-बँधाए मुहावरे बरतते हैं जो 漢文訓読 से निकले हैं: 〜ごとし (\"जैसा, के समान\") कानबुन-पठन शैली की पहचान है, और 〜に於いて (\"में, पर\") चीनी पूर्वसर्ग 於 का अनुवाद है। जब कोई औपचारिक भाषण या संपादकीय 「努力せざるべからず」 (“प्रयास न करना नहीं चलेगा”) का सहारा लेता है, तो ざる…べからず वाला वह परत-दर-परत दोहरा निषेध 21वीं शताब्दी में जीवित कानबुन-पठन शैली ही है। 返り点 से जुड़ी परिपाटियों ने आधुनिक लिखित जापानी की वाक्यरचना को भी प्रभावित किया।</p>","tangut-3000-syllables":"<h3>राज्य-प्रायोजित लिपि</h3><p>पश्चिमी शिया राज्य (1038–1227 ई.) ने लेखन को अपने राज्य-प्रशासन और सांस्कृतिक नीति का हिस्सा बनाया। 1036 में तंगुत शासक <strong>ली युआनहाओ</strong> (元昊, बाद में शिया के पहले सम्राट, जिंगज़ोंग) ने तंगुत भाषा के लिए एक राष्ट्रीय लेखन प्रणाली चलाई। आधिकारिक <em>सोंग इतिहास</em> कहता है कि युआनहाओ ने \"स्वयं तंगुत लिपि रची\" और अधिकारी <strong>येली रेनरोंग</strong> (野利仁榮) से उसे बारह खंडों में पूरा विस्तार दिलवाया; दूसरे वृत्तांत येली रेनरोंग को ही इसका रचयिता मानते हैं। विद्वान आज लगभग <strong>5,900 वर्ण</strong> गिनते हैं (2004 की एक गिनती में, रूपांतरों को छोड़कर, 5,863)। ये चीनी वर्णों की तरह सघन, वर्गाकार और बहु-घटक हैं, पर वर्ण ख़ुद तंगुत के लिए नए सिरे से रचे गए थे।</p><p><em>सोंग इतिहास</em> नए वर्णों को \"वर्गाकार और सुडौल, लिपिक-शैली जैसे, पर रेखाओं में काफ़ी दोहराव वाले\" बताता है, और राज्य ने जल्द ही कन्फ़्यूशियाई <em>पितृभक्ति ग्रंथ</em> (孝經) और <em>अर्या</em> (爾雅) शब्दकोश का तंगुत में अनुवाद करवाया। चीनी से दृश्य समानता बहुत संभवतः जानबूझकर थी। सोंग चीन और लियाओ खितान राज्य के बीच स्थित तंगुत राज्य ने अपनी लिपि से प्रशासन भी चलाया और यह भी जताया कि संस्कृति में वह पड़ोसियों से कम नहीं। फिर भी इसके घटकों के ध्वन्यात्मक और अर्थगत मान तंगुत के अपने हैं, इसलिए चीनी अक्षरों के ज्ञान से तंगुत पाठ पढ़ा नहीं जा सकता।</p><h3>चीनी संरचना, चीनी अर्थ नहीं</h3><p>चीनी की तरह तंगुत वर्ण भी बार-बार आने वाले ग्राफ़िक घटकों से बने हैं, और ज़्यादातर में ऐसे दो घटक मिलते हैं। पर चीनी के उलट, एक भी तंगुत वर्ण किसी चीज़ का चित्र नहीं है। हिस्सों का तर्क भी अलग है। चीनी में कोई घटक जहाँ भी आए, आम तौर पर वही अर्थ या ध्वनि लाता है। तंगुत में ऐसा नहीं: 12वीं सदी का तंगुत शब्दकोश <em>अक्षरों का सागर</em> हर वर्ण को दूसरे पूरे वर्णों के हिस्से उधार लेकर बना बताता है: \"जंगली हंस\" बना है \"पक्षी\" के एक हिस्से और \"दीर्घायु\" के एक हिस्से से (जो ध्वनि <em>dze</em> देता है)। वही छोटा घटक एक वर्ण में \"पक्षी\" के लिए हो सकता है और दूसरों में हड्डी, धुएँ, भोजन या समय के लिए। एक जैसे हिस्सों वाले पर उलटे क्रम (AB और BA) के वर्ण-जोड़ों के अर्थ अक्सर जुड़े होते हैं, जैसे \"हाथ की उँगली\" और \"पैर की उँगली\"। सोफ़्रोनोव के अनुसार केवल लगभग दस में से एक वर्ण में ध्वनि-घटक है, जबकि चीनी में दस में से नौ से भी ज़्यादा में। जिस भाषा को यह लिखती थी, वह चीनी-तिब्बती थी, चीनी से केवल बहुत दूर का नाता रखने वाली; 2010 के दशक से विशेषज्ञ इसे ग्यालरोंगिक (क्यांगिक) शाखा में रखते हैं, जिसकी जीवित रिश्तेदार भाषाएँ पश्चिमी सिचुआन में बोली जाती हैं। यानी लिपि दिखती चीनी जैसी है, पर लिखती एक बिल्कुल अलग बनावट वाली भाषा है — जिसमें क्रियाएँ अपने कर्ता और कर्म के अनुरूप बदलती हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"38.5\" data-lng=\"106.27\" data-zoom=\"5\">📍 यिनचुआन (पश्चिमी शिया की राजधानी) जाएं</button></div><h3>द्विभाषी शब्दावली: फानहान हेशी झांगझोंगझू</h3><p>तंगुत शब्द-भंडार की सबसे अच्छी खिड़की 12वीं सदी का द्विभाषी शब्दकोश <strong><em>番漢合時掌中珠</em></strong> (1190, गुले माओत्साई 骨勒茂才 द्वारा संकलित) है। यह तंगुत शब्दों को विषयवार चीनी समकक्षों के साथ सजाता है। हर प्रविष्टि के चार हिस्से हैं: तंगुत शब्द, उसका चीनी समकक्ष, चीनी अक्षरों में लिखा तंगुत उच्चारण, और तंगुत अक्षरों में लिखा चीनी उच्चारण। इसी दोहरी वर्तनी ने इसे वह कुंजी बनाया जिससे अलेक्सेई इवानोव (1909) और बर्थोल्ड लॉफ़र (1916) तंगुत के उच्चारण का पहला अनुमान लगा सके। प्रस्तावना उद्देश्य साफ़ बताती है: तंगुत और चीनी एक-दूसरे के शब्द सीखे बिना आपस में व्यवहार नहीं कर सकते।</p><h3>दफ़न हुई, फिर मिली, फिर पढ़ी गई</h3><p>1227 में मंगोलों ने पश्चिमी शिया की राजधानी को नष्ट कर दिया और तंगुत राज्य मिट गया — पर लिपि नहीं मिटी। तंगुत समुदाय युआन काल से लेकर मिंग काल तक इसे लिखते और छापते रहे; ज्ञात अंतिम उदाहरण <strong>1502</strong> में आज के हेबेई प्रांत के बाओदिंग में खड़े किए गए तंगुत लिपि वाले धारणी-स्तंभों की एक जोड़ी है। इसके बाद ही लिपि विस्मृति में डूबी, और लगभग चार सदियों तक वहीं पड़ी रही। <strong>1908–1909</strong> में रूसी खोजकर्ता <strong>प्योत्र कोज़्लोव</strong> ने गोबी रेगिस्तान के खंडहर शहर खारा-खोतो की खुदाई की और हजारों तंगुत पांडुलिपियाँ निकालीं। इसे व्यवस्थित ढंग से पढ़ने का काम 20वीं सदी में शुरू हुआ, और इसके अगुआ को इसकी भयानक क़ीमत चुकानी पड़ी। <strong>निकोलाई नेव्स्की</strong> ने पहला तंगुत शब्दकोश तैयार किया और कई व्याकरणिक निपातों के अर्थ सुलझाए, जिससे तंगुत पाठ सचमुच पढ़ना संभव हुआ — पर 1937 में NKVD ने उन्हें गिरफ़्तार करके गोली मार दी; उनकी <em>तंगुत भाषाशास्त्र</em> 1960 में जाकर छपी और 1962 में उसे मरणोपरांत लेनिन पुरस्कार मिला, और गिरफ़्तारी के समय उनके पास रही कुछ पांडुलिपियाँ 1991 में जाकर सेंट पीटर्सबर्ग के संस्थान में फिर प्रकट हुईं। भाषा को पढ़ने के पहले व्यापक ढाँचे जापानी विद्वान <strong>निशिदा तात्सुओ</strong> (西田龍雄) के ग्रंथ <em>सेइकागो नो केंक्यू</em> (1964–1966) से आए, जिसमें ध्वनि-व्यवस्था के पुनर्निर्माण के साथ लिपि का वाचन भी था, और रूसी विद्वान <strong>मिखाइल सोफ़्रोनोव</strong> की <em>तंगुत भाषा का व्याकरण</em> (1968) से, जिसमें पुनर्निर्माण के साथ पूरा व्याकरण भी दिया गया। <strong>गोंग ह्वांग-चेर्ंग</strong> (龔煌城) ने बाद में कई अध्ययनों में इस ध्वनि-व्यवस्था को परिष्कृत किया, और उनका पुनर्निर्माण ली फ़ानवेन के तंगुत–चीनी शब्दकोश (夏漢字典, 1997) में अपनाया गया। आज पाँच पूरे तंगुत शब्दकोश मौजूद हैं (नेव्स्की, निशिदा, ली फ़ानवेन, किचानोव और हान श्याओमांग के), और मार्क मियाके और गोंग शुन जैसे विद्वानों का नया काम जीवित ग्यालरोंगिक भाषाओं की मदद से तंगुत के उच्चारण को और निखार रहा है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"txg\">🔍 नक्शे पर तंगुत भाषा देखें</button></div>\n\n<h3>डिजिटल एन्कोडिंग और ऐतिहासिक महत्व</h3><p>राजकीय संरक्षण में बड़े पैमाने पर लिपि गढ़ने का तंगुत एक अच्छी तरह दर्ज उदाहरण है। चीनी लेखन से उसकी दिखावटी समानता उस राजनीतिक माहौल की भी गवाही देती है जिसमें वह रची गई। यूनिकोड ने अंततः 2016 में तंगुत को एन्कोड किया (संस्करण 9.0 में U+17000-U+187FF पर 6,125 वर्ण, साथ में 755 घटक), और इस तरह, उसे रचने वाले राज्य के मिटने के लगभग 800 साल बाद, इस लिपि को अपना पहला डिजिटल घर मिला।</p>","khitan-large-small-scripts":"<h3>एक भाषा के लिए दो लिपियाँ: क्यों?</h3><p>खितान लोगों ने 907 ई. में लियाओ राजवंश की स्थापना की और दो शताब्दियों से अधिक समय तक मंगोलिया की घास के मैदानों से पीले सागर तक फैले एक विशाल साम्राज्य पर शासन किया। उन्हें लिपि चाहिए थी, और उन्होंने एक नहीं, <em>दो</em> लिपियाँ बनाईं, बस पाँच साल के अंतर पर, और पहली को छोड़ा भी नहीं।</p><p><strong>खितान बड़ी लिपि</strong> (契丹大字) 920 ई. में प्रकट हुई, चीनी वर्णों के नमूने पर गढ़ी हुई। इसके अब तक लगभग 830 अलग-अलग वर्ण पहचाने गए हैं (एक विवादित समाधिलेख को भी गिनें तो लगभग 1,000) — ज़्यादातर लोगोग्राम, और शायद व्याकरणिक प्रत्ययों के लिए कुछ ध्वन्यात्मक चिह्न भी। इसे सम्राट अबाओजी (耶律阿保機) ने बनवाया था। कुछ ही वर्ष बाद, लगभग 924–925 ई. में, अबाओजी के छोटे भाई <strong>येलू दिएला</strong> ने — जिन्होंने एक आए हुए उइगुर दूत से उइगुर वर्णमाला सीखी थी — <strong>खितान छोटी लिपि</strong> (契丹小字) का आविष्कार किया। इसकी बनावट बिल्कुल नई थी: इसमें केवल कुछ सौ वर्ण हैं, जिनमें से कई ध्वन्यात्मक हैं, और दो से सात वर्णों को एक वर्गाकार खंड में जमाकर पूरा एक शब्द लिखा जाता है — जोड़ियों में, बाएँ से दाएँ।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"43.8\" data-lng=\"120.5\" data-zoom=\"4\">📍 लियाओ की हृदयभूमि (आंतरिक मंगोलिया) जाएं</button></div><h3>योगात्मक भाषा, वर्गाकार खंडों में</h3><p>खितान को पैरा-मंगोलिक भाषा माना जाता है — आदि-मंगोलिक की वंशज नहीं, बल्कि मंगोलिक भाषाओं की एक विलुप्त बहन-शाखा (यानहुनेन)। यह भाषा योगात्मक (agglutinative) है — जटिल अर्थ बनाने के लिए जड़ों पर प्रत्यय जोड़ती है। बड़ी लिपि जैसी शब्द-चिह्नों (लोगोग्राम) वाली प्रणाली इस तरह की शब्द-रचना के लिए ठीक नहीं बैठती थी। छोटी लिपि के ध्वन्यात्मक खंड इसके लिए कहीं बेहतर थे, क्योंकि प्रत्यय खंड में बस एक और वर्ण बनकर जुड़ जाता है।</p><p>फिर भी बड़ी लिपि कभी छोड़ी नहीं गई (उसके दिनांकित शिलालेख 986 से 1176 तक मिलते हैं), और विद्वान पूरी तरह निश्चित नहीं हैं कि दोनों लिपियाँ दो शताब्दियों तक साथ-साथ <em>क्यों</em> चलती रहीं। एक सिद्धांत के अनुसार बड़ी लिपि स्मारकीय और स्मृति-शिलालेखों के लिए प्रतिष्ठित थी, जबकि छोटी लिपि रोज़मर्रा के प्रशासन का काम चलाती थी। दूसरा सिद्धांत यह है कि दोनों खितान की अलग-अलग बोलियों या शैलियों से जुड़ी थीं। ईमानदार जवाब यह है कि हम ठीक-ठीक नहीं जानते, क्योंकि दोनों में से कोई भी लिपि हम पूरी तरह पढ़ नहीं पाते।</p><h3>पढ़ने की बड़ी पहेली</h3><p>1125 में जुरचेन जिन राजवंश ने लियाओ को पराजित किया, पर जिन शासक दशकों तक खितान लेखन का इस्तेमाल करते रहे, जब तक 1191 में एक शाही आदेश ने उस पर रोक नहीं लगा दी। अंतिम दिनांकित खितान शिलालेख 1176 का है। मंगोल काल तक भाषा मर चुकी थी और लिपियाँ भुला दी गई थीं। केवल लगभग पचास स्मारकीय शिलालेख ही बचे हैं (लगभग सत्रह बड़ी लिपि में और लगभग तैंतीस छोटी लिपि में), जिनमें से लगभग सभी पूर्वोत्तर चीन में हैं, दो मंगोलिया में, और एक खितान लेख वाला काँसे का दर्पण कोरिया के केसोंग से मिला है। व्यवस्थित विद्वत्तापूर्ण विश्लेषण 20वीं शताब्दी में ही शुरू हुआ, जब 1922 में भीतरी मंगोलिया के बारिन दायाँ बैनर स्थित लियाओ शाही समाधि छिंगलिंग (慶陵) में सम्राट शिंगजोंग और महारानी रेनयी की छोटी लिपि वाली स्मारक-पट्टिकाएँ मिलीं, जिनकी ख़बर बेल्जियाई मिशनरी लुई केर्विन ने दुनिया को दी। इन्हें पढ़ने की रणनीति समानांतर पाठों पर टिकी है। सच्चा खितान–चीनी द्विभाषी शिलालेख केवल एक ही ज्ञात है — <em>Langjun xingji</em>, जिसे लंबे समय तक जुरचेन समझा जाता रहा — लेकिन कई खितान समाधिलेख ऐसे लोगों के सम्मान में हैं जिनका जीवन चीनी अभिलेखों में भी दर्ज है, इसलिए दोनों को आमने-सामने रखकर मिलाया जा सकता है। चीनी पाठ को खितान खंडों के साथ मिलाकर विद्वान खितान अंशों का सामान्य अर्थ निकाल सकते हैं, और चीनी अभिलेखों से ज्ञात खितान व्यक्ति-नाम और स्थान-नाम छोटी लिपि के ध्वन्यात्मक मान तय करने में ख़ास मदद करते हैं।</p><h3>ऐसिन गिओरो और हालिया प्रगति</h3><p>एक मील का पत्थर 1985 में आई चीन के चिंगेल्तेई के खितान लिपि शोध-दल की पुस्तक थी, जिसने पूरा ज्ञात संग्रह एक जगह जुटाया और तब तक प्रस्तावित पाठों का सार दिया। 1990 के दशक से <strong>ऐसिन गिओरो उल्हिचुन</strong> (愛新覚羅烏拉熙春) — बीजिंग में जन्मी, जापान में कार्यरत मांचू विद्वान (च्यानलोंग सम्राट की वंशज, और जुरचेन विशेषज्ञ जिन छिज़ोंग की बेटी) — ने दोनों लिपियों पर व्यापक रूप से प्रकाशित किया है। अपने पति, इतिहासकार योशिमोतो मिचिमासा, के साथ मिलकर उन्होंने सैकड़ों छोटी लिपि खंडों के पाठ प्रस्तावित किए और व्याकरणिक प्रत्ययों, व्यक्तिगत नाम पैटर्न और सम्माननीय शब्दावली की पहचान की।</p><p>फिर भी प्रगति अधूरी ही है: एक पुरानी गणना (कारा, 1986) के अनुसार छोटी लिपि के 378 ज्ञात वर्णों में से लगभग 125 का अर्थ और 115 का ध्वन्यात्मक मान स्थापित था, जबकि बाक़ी तब भी अपठित थे। बड़ी लिपि की समझ इससे कहीं कम है: अंकों, बारह राशि-पशुओं और कुछ और शब्दों को छोड़कर उसके अधिकांश वर्ण अब भी पढ़े नहीं जा सके हैं। खितान लिपि पूर्वी एशियाई ऐतिहासिक भाषाविज्ञान की बड़ी अनसुलझी पहेलियों में से एक बनी हुई है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"zh\">🔍 नक्शे पर सिनोस्फेयर क्षेत्र देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"41.5\" data-lng=\"119.0\" data-zoom=\"5\">🗺 छिंगलोंग शिलालेख क्षेत्र की ओर जाएँ</button></div>","phagspa-universal-script":"<h3>एक लिपि, सभी भाषाओं के लिए</h3>\n<p><strong>युआन राजवंश</strong> (1271–1368) मंगोल साम्राज्य का पूर्वी केंद्र था — यही साम्राज्य इतिहास का सबसे बड़ा अखंड भू-साम्राज्य रहा, पर तब तक फारस से रूस तक फैली पश्चिमी ख़ानतें अलग-अलग शासित हो चुकी थीं। युआन दरबार में ही मंगोलियाई, चीनी, तिब्बती, उइगुर और फारसी भाषाएँ साथ-साथ चलती थीं। 1269 ई. में <strong>कुबलई ख़ान</strong> ने अपने शाही गुरु, तिब्बती भिक्षु <strong>द्रोगों च्योग्याल फागपा</strong> (1235–1280) को एक ऐसी लिपि बनाने का आदेश दिया जो इन सभी भाषाओं को लिख सके। परिणाम था <strong>फग्स-पा लिपि (八思巴字)</strong>।</p>\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"zh_phagspa\">📍 नक्शे पर फग्स-पा देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"40.4\" data-lng=\"116.4\" data-zoom=\"4\">🏯 युआन-काल दाडू (बीजिंग) जाएँ</button>\n</div>\n<h3>लिपि की रचना</h3>\n<p>फागपा ने तिब्बती लिपि (जो भारतीय ब्राह्मी से व्युत्पन्न है) को ऊपर से नीचे लिखे जाने वाले रूप में ढाला। 41 मूल अक्षरों (तिब्बती और संस्कृत के लिए अतिरिक्त अक्षर जोड़ने पर लगभग 48) की यह <em>अबुगिदा</em> प्रणाली मंगोलियाई, चीनी, तिब्बती, उइगुर, संस्कृत और शायद फारसी की ध्वनियों को समेटने के लिए बनाई गई थी। इसका आधिकारिक उपयोग राजमुहरों, कागज़ी मुद्रा और शाही फरमानों पर, और पूरे युआन चीन के शिलालेखों पर मिलता है — इनमें से एक है बंदरगाह-नगर च्वानझोउ में 1314 में खुदी एक ईसाई समाधि-शिला।</p>\n<h3>विफलता के कारण</h3>\n<p>चीनी विद्वान हान अक्षर नहीं छोड़ना चाहते थे; मंगोलों के पास उइगुर से निकली अपनी लिपि पहले से थी। फग्स-पा सरकारी दस्तावेज़ों के लिए अनिवार्य थी, पर रोज़मर्रा के जीवन में शायद ही बरती गई। 1350 के दशक की शुरुआत से उसकी सरकारी भूमिका भी फीकी पड़ गई, और उसके बाद वह ज़्यादातर चीनी अक्षर सीखते मंगोलों के लिए उच्चारण-गाइड का काम करती रही; 1368 में मिंग के सत्ता सँभालते ही उसका चलन ख़त्म हो गया। तिब्बत में इसी नाम से जानी जाने वाली एक मुहर-लिपि 20वीं सदी तक मुहरों पर खोदी जाती रही, हालाँकि कुछ विद्वान उस बाद की लिपि को असली फग्स-पा के बजाय एक अलग तिब्बती मुहर-लिपि मानते हैं।</p>\n<h3>हांगुल से संबंध का अनुमान</h3>\n<p>1443 में जोसियोन के <strong>राजा सेजोंग</strong> ने <strong>हुनमिनजियोंगुम (訓民正音)</strong> बनाया। कुछ विद्वानों ने — सबसे प्रमुखता से <strong>गैरी लेड्यार्ड</strong> ने अपने 1966 के शोध-प्रबंध में — तर्क दिया है कि हांगुल के कुछ मूल व्यंजन, जैसे ㄱ, ㄷ, ㄹ और ㅂ, फग्स-पा अक्षरों के नमूने पर बने। वे 1443 के राजकीय इतिहास की एक ललचाने वाली पंक्ति की ओर इशारा करते हैं: राजा के नए अक्षर \"प्राचीन मुहर-लिपि की नक़ल करते हैं\" (其字倣古篆)। लेड्यार्ड ने \"प्राचीन मुहर\" को मंगोल मुहर-लिपि की ओर एक छिपा इशारा पढ़ा। उन्होंने कभी दावा नहीं किया कि हांगुल नक़ल है; उनकी नज़र में सेजोंग ने मौलिक रचना को कई नमूनों के साथ मिलाया, जिनमें फग्स-पा भी एक था।</p><p>दूसरे पक्ष का कहना है कि लिपि पर 1446 की टीका, <em>हेरये</em>, मूल व्यंजनों को वाक्-अंगों के चित्र बताती है, जो पाँच उच्चारण-स्थानों (牙舌脣齒喉: दाढ़, जीभ, होंठ, दाँत, गला) के हिसाब से छाँटे गए हैं। उदाहरण के लिए ㄱ गले को रोकती जीभ की जड़ दिखाता है, और ㅁ मुँह। इस नज़रिए से फग्स-पा से समानताएँ संयोग हैं। ज़्यादातर विद्वान आज भी हांगुल को बड़े पैमाने पर मौलिक आविष्कार मानते हैं, और फग्स-पा वाला संबंध अल्पमत की राय बना हुआ है — पर गंभीर राय।</p>\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko\">📍 नक्शे पर कोरियाई देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🔢 「人」 को सभी भाषाओं में देखें</button>\n</div>\n<h3>अप्रत्याशित विरासत</h3>\n<p>फग्स-पा का एक स्थायी अप्रत्यक्ष असर रहा: यह किसी बाहरी वर्णमाला में लिखे गए चीनी के सबसे समृद्ध ध्वन्यात्मक अभिलेखों में से एक है। दुनहुआंग से मिले, तिब्बती लिपि में लिखे चीनी लिप्यंतरण कोई चार सदी पुराने हैं, पर फग्स-पा शब्दावली को कहीं अधिक व्यवस्थित ढंग से समेटती है, और वह जो दर्ज करती है वह पुरानी मंदारिन है, मध्यकालीन चीनी नहीं। चूँकि यह लिपि पूरे शब्दों के बजाय ध्वनियाँ लिखती है, भाषाविद् युआन-कालीन फग्स-पा वर्तनियों से <strong>वे व्यंजन और स्वर</strong> निकाल सकते हैं जिन्हें हान अक्षर अकेले कभी नहीं दिखाते। वे यह सावधानी से करते हैं: फग्स-पा चीनी एक रूढ़िवादी पठन-मानक पर चलती थी, जो उदाहरण के लिए वे घोष आद्य व्यंजन बनाए रखती थी जिन्हें दादू की बोलचाल वाली मंदारिन शायद पहले ही खो चुकी थी। केवल स्वर-तान इसका अपवाद है: फग्स-पा में तान के चिह्न हैं ही नहीं, इसलिए जिन शब्दांशों में अंतर सिर्फ़ तान का है, उनकी वर्तनी एक जैसी होती है; चारों तानें युआन-कालीन तुकांत कोश मंगगू ज़ीयुन (蒙古字韻) में हर वर्तनी के नीचे दिए हान अक्षरों के क्रम से ही पढ़ी जा सकती हैं। कुबलई ख़ान की यह विफल लिपि चीनी भाषा के ध्वनिशास्त्र इतिहास का अनजाने में बना टाइम कैप्सूल साबित हुई।</p>","hangul-sinosphere-context":"<h3>शास्त्रीय चीनी और साक्षरता तक पहुँच</h3>\n<p>15वीं सदी के जोसियोन में शास्त्रीय चीनी (<em>हानमुन</em>, 漢文) एकमात्र प्रतिष्ठित लिपि थी। इसे सीखने में कई वर्ष लगते थे — जो किसान, कारीगर और महिलाएँ नहीं दे सकते थे। नतीजा साक्षरता की ऐसी खाई थी जिसने समाज को बाँट दिया: लेखन पर एकाधिकार रखने वाले पुरुष <em>यांगबान</em> अभिजात विद्वानों की एक पतली परत, और वे अधिकांश कोरियाई जिनकी लिखित ग्रंथों तक पहुँच सीमित थी।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko\">📍 नक्शे पर कोरियाई देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko_mid\">📍 मध्यकालीन कोरियाई उच्चारण देखें</button>\n</div>\n\n<h3>रचना और प्रकाशन</h3>\n<p><strong>राजा सेजोंग</strong> (शासनकाल 1418–1450) ने खगोल विज्ञान, संगीत सिद्धांत और सैन्य तकनीक में सुधार किए। 1440 के दशक की शुरुआत में वे शून्य से एक नई वर्णमाला रचने में जुट गए। उनके हॉल ऑफ़ वर्थीज़ के विद्वानों ने मदद की, पर 1443 के आख़िरी महीने के दरबारी इतिहास में श्रेय ख़ुद राजा को दिया गया है: \"इस महीने महामहिम ने स्वयं <em>ओनमुन</em> के 28 अक्षर रचे … सरल और संक्षिप्त, फिर भी अनंत रूप से बहुमुखी।\" यह वर्णमाला 1443 में पूरी हुई, और 1446 में <strong>हुनमिनजियोंगुम</strong> (訓民正音) के प्रकाशन के साथ आधिकारिक रूप से लागू की गई: 28 अक्षर (17 व्यंजन + 11 स्वर), जिनमें से 24 आज भी प्रयोग में हैं।</p>\n<p>व्यंजन अक्षर उच्चारण के समय <em>मुँह और गले की स्थिति</em> का चित्र बनाते हैं; स्वर अक्षर तीन दार्शनिक तत्वों — आकाश (·), भूमि (ㅡ) और मनुष्य (ㅣ) — से बने हैं। ये अक्षर मिलकर शब्दांश-खंड बनाते हैं, इसलिए यह लिपि वर्णमाला भी है और देखने में शब्दांश-लिपि भी।</p>\n\n<h3>विद्वानों का विद्रोह: चोए मानरि का ज्ञापन</h3>\n<p>1444 की शुरुआत में हॉल ऑफ़ वर्थीज़ के उप-प्रमुख <strong>चोए मानरि</strong> (崔萬理) ने वहीं के विद्वानों के एक समूह की अगुवाई करते हुए सेजोंग को औपचारिक विरोध-पत्र सौंपा। आपत्तियाँ मिंग चीन से रिश्तों, विद्वत्ता और शासन पर टिकी थीं। पहली, सांस्कृतिक अधीनता: कोरिया चीनी सभ्यता का हिस्सा है, और ख़ुद चीन में भी, क्षेत्रीय बोलियाँ कितनी भी अलग हों, किसी बोली को कभी अपनी लिपि नहीं दी गई। ऐसा केवल \"बर्बर\" करते थे — ज्ञापन मंगोलों, तंगुतों, जुरचेनों, जापानियों और तिब्बतियों के नाम गिनाता है; अलग लिपि बनाना चीन को छोड़कर उन जैसा बन जाना था। दूसरी, व्यावहारिक आपत्ति: <em>इदू</em> — उधार लिए चीनी अक्षरों में कोरियाई लिखने की पुरानी प्रणाली — सदियों से अधिकारियों का काम बिना दिक़्क़त चलाती आई है; और साफ़ लेखन से अन्यायपूर्ण फ़ैसले ख़त्म नहीं होंगे, वह तो मुक़दमा सँभालने वाले अधिकारियों पर निर्भर है, लिपि पर नहीं। तीसरी, विद्या के लिए डर: अगर कोई लिपिक केवल 27 अक्षरों (ज्ञापन की गिनती में) वाली लिपि से आगे बढ़ सके, तो कन्फ़्यूशियाई ग्रंथों पर कौन पसीना बहाएगा? उन्होंने चेताया कि कुछ ही दशकों में शायद ही कोई चीनी अक्षर जानेगा।</p><p>सेजोंग ने ख़ुद जवाब दिया। उन्होंने याद दिलाया कि इदू भी अक्षरों को उनकी ध्वनि के लिए बरतता है, और वह जनता की मदद के लिए बना था। \"अगर वह जनता की मदद के लिए था, तो मेरा <em>ओनमुन</em> भी जनता की मदद के लिए है।\" फिर उन्होंने चोए और ज्ञापन पर दस्तख़त करने वाले उनके छह साथियों को राजकीय न्यायाधिकरण भेज दिया। अगले ही दिन वे छोड़ दिए गए, और उनमें से केवल एक, जोंग छांग-सोन, का पद गया। काम आगे बढ़ता रहा।</p>\n\n<h3>पहले किसने उपयोग किया</h3>\n<p>हांगुल को सबसे पहले अपनाने वालों में <strong>महिलाएँ</strong> और <strong>बौद्ध</strong> थे। यांगबान पुरुष चीनी में लिखते रहे और हांगुल को अपने से नीचे समझते थे। इसका आम नाम, <em>ओनमुन</em> (諺文, \"बोलचाल की लिपि\"), वही शब्द था जो सेजोंग का अपना दरबार बरतता था, पर उसे चीनी अक्षरों की \"सच्ची लिपि\" <em>जिनमुन</em> (眞文) के सामने रखा जाता था, और इस तुलना से दर्जा साफ़ हो जाता था। लेकिन परीक्षा से वंचित अभिजात महिलाओं ने पत्र, डायरी और घरेलू लेखा-जोखा के लिए हांगुल अपनाया। भिक्षुओं ने इससे सूत्र अनुवाद किए और गृहस्थों के लिए धार्मिक ग्रंथ लिखे।</p>\n<p><strong>देसी भाषा के उपन्यास</strong> हांगुल के सहारे फले-फूले — 18वीं सदी का <em>चुनह्यांगजियोन</em> (春香傳) एक राष्ट्रीय क्लासिक बन गया, क्योंकि उसकी नायिका की कथा वर्ग की सीमाओं के आर-पार निष्ठा निभाने की कथा है। इन कृतियों ने दरबार और सरकारी दायरों के बाहर भी हांगुल का प्रयोग बढ़ाने में योगदान दिया।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko_hun\">📍 प्रशिक्षण-शैली पाठ देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🔢 「人」 को कोरियाई रूपान्तरों में देखें</button>\n</div>\n\n<h3>प्रतिबंध और बाद का मानकीकरण</h3>\n<p>1504 में राजा <strong>यियोनसानगुन</strong> ने अपनी आलोचना वाले गुमनाम लेख इस लिपि में फैलने के बाद हांगुल को पढ़ाने और बरतने पर रोक लगा दी। 1506 में उसके पतन के बाद प्रतिबंध हटा, पर हांगुल की प्रतिष्ठा सदियों तक निम्न रही। 19वीं सदी के अंत के राष्ट्रवादी आंदोलन ने इसे चीनी सांस्कृतिक दबदबे से अलग कोरियाई पहचान के प्रतीक के रूप में फिर से खड़ा किया — गाबो सुधारों के दौरान नवंबर 1894 के एक फ़रमान ने इसे <em>गुंगमुन</em> (국문, राष्ट्र की लिपि) नाम से सरकारी दस्तावेज़ों की पसंदीदा लिपि बना दिया, हालाँकि मिश्रित लिपि की भी छूट रही। 1896 में अख़बार <em>द इंडिपेंडेंट</em> (<em>तोंगनिप सिनमुन</em>) ने अपने कोरियाई पन्ने पूरी तरह हांगुल में छापे। <strong>हांगुल</strong> नाम एक पीढ़ी बाद आया: 1910 के दशक की शुरुआत में <strong>जू सिग्योंग</strong> और उनके भाषा-सुधारक साथियों ने अपमानजनक <em>ओनमुन</em> की जगह यह नाम गढ़ा, और यह आम प्रचलन में तब आया जब 1927 में <em>हांगुल</em> पत्रिका छपने लगी। 1945 में स्वतंत्रता के बाद यह दोनों कोरिया की आधिकारिक लिपि बन गई।</p>","chu-nom-vietnam-script":"<h3>आवश्यकता से जन्मी लिपि</h3>\n<p>उत्तरी वियतनाम पर लगभग एक हज़ार साल तक — 111 ईसा पूर्व से 938 में स्वतंत्रता तक — एक के बाद एक चीनी राजवंशों का शासन रहा, और शास्त्रीय चीनी (<em>chữ Hán</em>) उसके बहुत बाद तक प्रशासन, कानून और साहित्य की लिखित भाषा बनी रही। लेकिन वियतनामी भाषा चीनी नहीं है। यह ऑस्ट्रोएशियाटिक परिवार की है (ख्मेर इसकी दूर की रिश्तेदार है), और इसका अपना व्याकरण और अपनी देशज शब्दावली है। बोली जाने वाली भाषा को उधार के चीनी अक्षरों में लिखना उतना ही अटपटा था जितना अंग्रेज़ी को जापानी कांजी में लिखना।</p>\n<p>शायद 10वीं शताब्दी में स्वतंत्रता के बाद वियतनामी लेखकों ने एक हल निकाला (सबसे पुराना पक्के तौर पर तिथियुक्त नमूना — बाओ आन पगोडा के एक शिलालेख पर नामों की सूची — <strong>1209</strong> का है): <strong>चु नोम (Chữ Nôm, 字喃)</strong> — शाब्दिक अर्थ \"दक्षिणी लिपि\" या \"देसी लिपि\"। बिल्कुल नई वर्णमाला बनाने की बजाय, उन्होंने दो मुख्य रणनीतियों से चीनी अक्षरों को वियतनामी के अनुरूप ढाला।</p><ul><li><strong>ध्वन्यात्मक उधार:</strong> किसी चीनी अक्षर को उसकी ध्वनि के लिए चुना जाता था, अर्थ चाहे जो हो। 沒 का चीनी में अर्थ है \"न होना\", पर इसका चीनी-वियतनामी पाठ <em>một</em> है, इसलिए नोम ने इसे देशज शब्द <em>một</em>, \"एक\", लिखने में बरता।</li><li><strong>अर्थ + ध्वनि यौगिक:</strong> दो अक्षरों को जोड़ा जाता था — एक अर्थ देता, एक ध्वनि — और ऐसा नया अक्षर बनता जो किसी चीनी शब्दकोश में नहीं मिलता। 𠀧 <em>ba</em> \"तीन\" में 巴 <em>ba</em> (ध्वनि के लिए) और 三 \"तीन\" (अर्थ के लिए) मिले हैं; 媄 <em>mẹ</em> \"माँ\" में 女 \"स्त्री\" और 美 <em>mỹ</em>।</li></ul>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"16.0\" data-lng=\"108.0\" data-zoom=\"5\">📍 वियतनाम की ओर उड़ें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"南\">🔢 南 को विभिन्न भाषाओं में देखें</button>\n</div>\n\n<h3>पैमाना: लगभग 20,000 अक्षरों का भंडार</h3>\n<p>चीनी मानक भंडार (GB 18030) में लगभग 87,000 अक्षर हैं, लेकिन नोम ना समूह की 2005 की चु नोम सूची लगभग <strong>20,000 अक्षरों</strong> तक जाती है, जिनमें कई हज़ार वियतनामी आविष्कार हैं। वियतनाम का राष्ट्रीय मानक TCVN 6909:2001 नोम के 9,299 अक्षर तय करता है, जिनमें लगभग आधे वियतनाम-विशिष्ट हैं।</p><p>लिपि का कभी मानकीकरण नहीं हुआ। अलग-अलग लेखक एक ही शब्द को अलग-अलग अक्षरों से लिख सकते थे, और घटकों का मतलब समझने के लिए पाठक को शास्त्रीय चीनी भी आनी चाहिए थी — इसलिए नोम सीखना कठिन था। फिर भी इसका फैलाव नहीं रुका: <em>ट्रुयेन किएउ</em> समेत लोकप्रिय नोम कृतियाँ नक़्क़ाशीदार लकड़ी के ठप्पों से छपीं और 19वीं सदी में ख़ूब बिकीं। दो बार — हो राजवंश (1400–1407) और ताई सोन (1778–1802) के समय — शासकों ने नोम को आधिकारिक लिपि तक बना दिया, पर हर बार नीति शासन के साथ ही ख़त्म हो गई।</p>\n\n<h3>उत्कृष्ट कृति: ट्रुयेन किएउ</h3>\n<p><strong>ट्रुयेन किएउ (Truyện Kiều)</strong> — <strong>गुयेन दु (1765–1820)</strong> की 3,254 पंक्तियों की महाकाव्य कविता — चु नोम साहित्य का शिखर है। चीनी उपन्यास <em>जिन युन छ्याओ ज़ुआन</em> से रूपांतरित यह कथा किएउ नाम की एक युवती के पंद्रह बरसों के दुर्भाग्य, वेश्यावृत्ति, युद्ध और आख़िर में पुनर्मिलन की कहानी कहती है। यह <em>lục bát</em> में लिखी है — वियतनाम का देसी \"छह-आठ\" छंद, जिसमें छह और आठ अक्षरों की पंक्तियाँ बारी-बारी आती हैं — और इसे व्यापक रूप से वियतनाम की राष्ट्रीय कविता माना जाता है; बहुत-से वियतनामी इसकी पंक्तियाँ उद्धृत कर सकते हैं। वियतनाम की सबसे महान रचना एक ऐसी लिपि में लिखी गई जिसे आज लगभग कोई नहीं पढ़ सकता। आधुनिक संस्करण में ट्रुयेन किएउ पढ़ते समय आप लैटिन-आधारित <em>क्वोक न्गू</em> में किया गया लिप्यंतरण पढ़ रहे होते हैं, गुयेन दु के लिखे मूल अक्षर नहीं।</p>\n\n<h3>उन्मूलन</h3>\n<p>फ़्रांसीसी उपनिवेश 1858 से धीरे-धीरे पाँव पसारता गया। कैथोलिक मिशनरी 17वीं शताब्दी से ही लैटिन-आधारित क्वोक न्गू को बढ़ावा दे रहे थे (आलेक्सांद्र दे रोद वाला लेख देखें)। फ़्रांसीसी अधिकारियों ने इसे बढ़ावा दिया, आंशिक रूप से चीनी विद्या और उसके पीछे खड़े विद्वान वर्ग की पकड़ ढीली करने के लिए; आलोचक तब भी और आज भी कहते हैं कि केवल नई लिपि पढ़ने वाली जनता उपनिवेश-पूर्व ग्रंथों और सांस्कृतिक स्मृति से कट गई। शास्त्रीय चीनी को परखने वाली कन्फ्यूशियसी परीक्षाएँ 1915 में तोंकिन में समाप्त कर दी गईं और ह्वे में 4 जनवरी <strong>1919</strong> को अंतिम बार हुईं। नोम पढ़ना हमेशा उसी शास्त्रीय शिक्षा पर टिका था, और अब वह शिक्षा ही जाती रही। एक ही पीढ़ी में इस लिपि को सचमुच पढ़ पाने वाले लोग बहुत घट गए।</p>\n\n<h3>वह पुनरुद्धार जो शायद समय पर न पहुँचे</h3>\n<p>1970 में हनोई में स्थापित <strong>हान नोम शोध संस्थान</strong> (Viện Nghiên cứu Hán Nôm) पांडुलिपियों के क्षय से पहले उन्हें डिजिटाइज़ करने की दौड़ में है। वियतनाम के अपने राष्ट्रीय मानकों (TCVN 5773:1993 और TCVN 6909:2001) के बाद यूनिकोड ने हज़ारों चु नोम अक्षर शामिल किए — वियतनाम-विशिष्ट अक्षरों में से ज़्यादातर CJK एकीकृत विचारलिपि विस्तार B और बाद के विस्तार खंडों में — इसलिए अब यह लिपि किसी भी डिवाइस पर मानक फ़ॉन्ट से टाइप की जा सकती है। विद्वानों और शौक़ीनों का एक छोटा पर उत्साही समुदाय इसे फिर से सीख रहा है। पर वियतनामी नोम संरक्षण फ़ाउंडेशन का अनुमान है कि दुनिया भर में 100 से भी कम विद्वान इसे पढ़ सकते हैं, इसलिए समय तेज़ी से हाथ से निकल रहा है।</p>","quoc-ngu-rhodes":"<h3>शुरुआत किसी और ने की, पूरा इन्होंने किया</h3>\n<p><strong>अलेक्ज़ेंडर डी रोड्स</strong> (1593–1660; कुछ स्रोत जन्म 1591 बताते हैं) अविग्नों के जेसुइट मिशनरी थे — जो तब आज के फ़्रांस के भीतर पोप का एक अंतःक्षेत्र था। वे 1624 में वियतनाम पहुंचे। आम तौर पर, और कुछ हद तक ग़लत ढंग से, <strong>क्वोक न्गू (quốc ngữ, 國語)</strong> के अकेले आविष्कारक का श्रेय उन्हीं को दिया जाता है। असल में यह कई लोगों का साझा काम था।</p>\n<p>असली अगुआ <strong>फ्रांसिस्को डी पीना</strong> थे, एक पुर्तगाली जेसुइट जो 1617 के आसपास वियतनाम पहुंचे और बोली जाने वाली वियतनामी में महारत हासिल करने वाले पहले ज्ञात यूरोपीय थे। पीना ने रोमनीकरण प्रणाली विकसित करना शुरू किया, लेकिन 1625 में एक जहाज दुर्घटना में डूब गए। डी रोड्स ने वियतनामी डी पीना से ही सीखी थी। उन्होंने दो और पुर्तगाली जेसुइटों, गास्पर दो अमारल और आंतोनियो बारबोसा, के बनाए शब्दकोशों का भी सहारा लिया, और इस सारे पुराने काम को एक प्रणाली में पिरोने वाले डी रोड्स ही थे।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"16.0\" data-lng=\"108.0\" data-zoom=\"5\">📍 वियतनाम की ओर उड़ें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"口\">🔢 口 को विभिन्न भाषाओं में देखें</button>\n</div>\n\n<h3>1651 का शब्दकोश</h3>\n<p>वियतनामी (उत्तरी) में <strong>छह स्वराघात</strong> हैं। डी रोड्स को केवल लैटिन अक्षरों और विशेष चिह्नों से सभी छह स्वराघात दिखाने थे। डी पीना और उनके साथी स्वराघात चिह्नित करना शुरू कर चुके थे, पर पूरी प्रणाली छपे रूप में 1651 के शब्दकोश ने ही सामने रखी। उन्होंने एक्यूट (´), ग्रेव (`), हुक (̉), टिल्ड (~) और नीचे बिंदु (.) के चिह्न बरते। समतल स्वराघात बिना चिह्न के रहता है। उन्होंने द्विवर्ण (nh, ng, kh, gh, ph, th, tr, ch) और परिवर्तित स्वर (ă, â, ê, ô, ơ, ư) भी बनाए, ताकि वे वियतनामी ध्वनियाँ लिखी जा सकें जिनके लिए लैटिन में अक्षर नहीं थे। <em>ma, mà, má, mả, mã, mạ</em> — एक अक्षर, छह शब्द, पूरी तरह अलग अर्थ।</p><p>नतीजा एक ऐसी लिपि थी जो <em>चु नोम से कहीं जल्दी सीखी जा सकती थी</em>: हज़ारों अक्षरों के बजाय कुछ दर्जन अक्षर और चिह्न।</p><p>पर यह अभी आधुनिक वियतनामी नहीं थी। डी रोड्स ने ऐसे व्यंजन-गुच्छ लिखे जिन्हें भाषा तब से खो चुकी है — शब्दों की शुरुआत में <em>bl-</em>, <em>ml-</em> और <em>tl-</em>। जो शब्द <em>tl-</em> से लिखे जाते थे, आज <em>tr-</em> से लिखे जाते हैं, और शुरुआती क्वोक न्गू दस्तावेज़ 'बड़ा' (आधुनिक <em>lớn</em>) को <em>mlớn</em> या <em>blớn</em> लिखते हैं। वर्तनियाँ दिखाती हैं कि <em>tl-</em> से <em>tr-</em> का बदलाव 18वीं सदी के अंत तक पूरा हो चुका था।</p>\n\n<h3>वियतनाम ही क्यों, जापान या कोरिया क्यों नहीं?</h3>\n<p>ईसाई मिशनरियों ने जापान में भी रोमनीकरण की कोशिश की: पुर्तगाली जेसुइट जोआओ रोड्रिगेस ने <em>Arte da Lingoa de Iapam</em> (1604) और रोमन लिपि के शब्दकोश तैयार किए। पर जापान ने 1614 में ईसाई धर्म पर प्रतिबंध लगाकर मिशनरियों को निष्कासित किया और 1639 में पुर्तगाली जहाजों का आना भी बंद कर दिया, और रोमनीकरण भी उन्हीं के साथ ख़त्म हो गया। कोरिया में उस समय ऐसा कोई प्रयास हुआ ही नहीं — कैथोलिक धर्म प्रायद्वीप में 1780 के दशक में पहुंचा, और कोरियाई भाषा का पहला पश्चिमी रोमन लिप्यंतरण उन्नीसवीं सदी में हुआ। तब तक कोरिया के पास अपनी बनाई लिपि हांगुल थी, इसलिए मिशनरियों ने नई रोमन लिपि गढ़ने के बजाय उसी को अपना लिया। वियतनाम के पास हांगुल जैसा कुछ नहीं था। चु नोम शानदार थी पर कभी सचमुच लोकप्रिय नहीं बनी: वह मानकीकृत नहीं थी, कठिन थी और वियतनामी अभिजात वर्ग से जुड़ी थी। जब फ्रांसीसी उपनिवेशकों ने ज़ोर-शोर से क्वोक न्गू को बढ़ावा दिया — पहले 1882 में दक्षिण के सरकारी दस्तावेज़ों के लिए इसे अनिवार्य लिपि बनाया, फिर 1919 में कन्फ्यूशियसी परीक्षाएँ ख़त्म कीं — तो लोगों के पास एकजुट होने के लिए कोई दूसरा आधार नहीं था। लैटिन लिपि ने वह ख़ाली जगह भर दी।</p>\n\n<h3>स्वराघात-चिह्न: वह प्रणाली जो बची रही</h3><p>डी रोड्स ने जो स्वराघात-चिह्न छापे, वे आज भी लगभग अपरिवर्तित प्रयोग में हैं:</p>\n<ul>\n  <li>स्वराघात 1 (ngang — सम): अचिह्नित — <em>ma</em> (भूत)</li>\n  <li>स्वराघात 2 (huyền — अवरोही): ग्रेव — <em>mà</em> (किंतु)</li>\n  <li>स्वराघात 3 (sắc — आरोही): एक्यूट — <em>má</em> (माँ)</li>\n  <li>स्वराघात 4 (hỏi — अवरोही-आरोही): हुक — <em>mả</em> (समाधि)</li>\n  <li>स्वराघात 5 (ngã — खंडित): टिल्ड — <em>mã</em> (घोड़ा)</li>\n  <li>स्वराघात 6 (nặng — भारी): नीचे बिंदु — <em>mạ</em> (धान का पौध)</li>\n</ul>\n<p>छह शब्द, सब एक ही शब्दांश के, अर्थ पूरी तरह अलग — भेद सिर्फ़ एक ही स्वर पर लगे विशेषकों का। प्रणाली सुघड़ है, पर छपाई के लिहाज़ से कठिन: वियतनामी का एक स्वर एक साथ दो चिह्न ढो सकता है (जैसे <em>ộ</em> = सर्कमफ़्लेक्स + नीचे बिंदु), जिससे शुरुआती वियतनामी छापेख़ानों और कीबोर्ड बनाने वालों, दोनों को ख़ूब परेशानी हुई।</p>\n\n<h3>विरासत की विडंबना</h3>\n<p>1645 में वियतनामी अधिकारियों ने धर्म-प्रचार के कारण डी रोड्स को देश से निकाल दिया। 1649 तक वे रोम लौट आए और अगले पाँच साल इटली और फ़्रांस में वियतनाम मिशन के लिए बिशपों और धन की पैरवी करते रहे — यही उनके जाने के बाद स्थापित पेरिस फ़ॉरेन मिशन्स सोसाइटी की ज़मीन बनी। नवंबर 1654 में उनके वरिष्ठों ने उन्हें वियतनाम नहीं, फ़ारस भेजा, जहाँ 1660 में इस्फ़हान में उनका निधन हुआ। 1651 का शब्दकोश रोम में चर्च की मिशनरी संस्था, प्रोपगैंडा फ़ीदे, के छापेखाने से छपा — लगभग 8,000 वियतनामी प्रविष्टियों के साथ — और आज पूरे देश में चलने वाली लिपि का एक अहम शुरुआती आधार बना। मिशनरियों ने क्वोक न्गू ईसाई ग्रंथों के लिए विकसित किया; बाद में इसे धर्मनिरपेक्ष प्रकाशन, राष्ट्रवादी लेखन, शिक्षा और राज्य-प्रशासन में अपनाया गया।</p>","go-on-kan-on-to-on":"<h3>एक सहस्राब्दी में तीन लहरें</h3>\n<p>जापानी शब्दकोश में <strong>行</strong> (जाना, यात्रा करना) जैसा कोई आम अक्षर देखने पर तीन चीनी-जापानी (音読み) पाठ मिलते हैं: <em>gyō</em>, <em>kō</em>, और <em>an</em>। ये एक ही उच्चारण के विकल्प नहीं, बल्कि तीन अलग दौर के उधार हैं, जिनमें सैकड़ों साल के फ़ासले पर चीनी ध्वनियों की अलग-अलग अवस्थाएँ दर्ज हैं।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"行:1\">📖 行 दिखाएं</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"日\">☀️ 日 दिखाएं</button>\n</div>\n\n<h3>परत 1: गो-ऑन 呉音 (5वीं–6वीं सदी)</h3>\n<p>सबसे पुरानी परत जापान के तांग दरबार से औपचारिक संपर्क से पहले आई। <strong>कोरियाई प्रायद्वीप</strong> के माध्यम से — परंपरा के अनुसार बैक्जे से — चीन के दक्षिणी राजवंशों की राजधानी जियानकांग (आधुनिक नानजिंग, प्राचीन वू भूमि) से जुड़े पाठ बौद्ध भिक्षु लेकर आए। लेकिन \"गो-ऑन\" (अर्थात् \"वू ध्वनि\") नाम इस मार्ग का प्रमाण नहीं है: यह नाम हेइआन काल के मध्य में ही सामने आता है, जिसे कान-ऑन के समर्थकों ने बाद में गढ़ा। उससे पहले इन पाठों को केवल \"वा-ऑन\" (和音) कहा जाता था, और 百済音 (कुदारा-ऑन) तथा 対馬音 (त्सुशिमा-ऑन) जैसे पुराने नाम कोरिया की ओर संकेत करते हैं। उस समय का कोई दस्तावेज़ इन्हें सीधे दक्षिणी चीनी से नहीं जोड़ता।</p><p>गो-ऑन में मध्यकालीन चीनी की वे विशेषताएँ बची हैं जिन्हें तांग राजधानी की बोली तब तक खोने लगी थी: घोष व्यंजन घोष ही रहते हैं, और अनुनासिक व्यंजन अनुनासिक ही — <strong>経</strong> <em>kyō</em>, <strong>男</strong> <em>nan</em>, <strong>行</strong> <em>gyō</em>। <em>gyō</em> का घोष <em>g-</em> 行 के मध्यकालीन चीनी 匣 आदि व्यंजन को दर्शाता है, यानी *<em>ɦˠæŋ</em> की घोष संघर्षी ध्वनि को। प्राचीन जापानी में अपनी कोई घोष संघर्षी ध्वनि नहीं थी, इसलिए उसने इसे <em>g-</em> के रूप में लिया। कान-ऑन के पीछे वाले छांगआन मानक में यह आदि व्यंजन तब तक अपना घोषत्व खो चुका था, इसलिए वहाँ <em>kō</em> बना।</p>\n\n<h3>परत 2: कान-ऑन 漢音 (7वीं–9वीं सदी)</h3>\n<p>7वीं सदी से जापानी सरकारी दल (<em>kentōshi</em> 遣唐使) सीधे तांग छांगआन गए और राजधानी का प्रतिष्ठित उच्चारण लाए। इस परत को, जिसे <em>कान-ऑन</em> (\"हान ध्वनि\") कहते हैं, सही, विद्वत् मानक के रूप में ज़ोर-शोर से आगे बढ़ाया गया। 792 में सम्राट कानमु ने कन्फ़्यूशियाई ग्रंथों के विद्यार्थियों को इसे सीखने का आदेश दिया, और जो भिक्षु कान-ऑन पढ़ने से इनकार करते, उन्हें चीन जाने की अनुमति नहीं मिलती थी। फिर भी यह गो-ऑन को न रोज़मर्रा के शब्दों से हटा पाया, न मंदिरों से। ज़्यादातर सूत्र आज भी गो-ऑन में ही पढ़े जाते हैं: 如是我聞 \"ऐसा मैंने सुना\" है <em>nyoze gamon</em>, और केवल वे गिने-चुने सूत्र जिन्हें परंपरा से कान-ऑन में पढ़ा जाता है, इसे <em>josi gabun</em> बनाते हैं।</p><p>कान-ऑन 8वीं सदी के छांगआन की बोली का आईना है, जहाँ दो बदलाव चल रहे थे। घोष व्यंजन अपना घोषत्व खो रहे थे, इसलिए 行 <em>gyō</em> बन गया <em>kō</em>। और अनुनासिक व्यंजन घोष स्पर्शों में बदल रहे थे (<em>m</em> से <em>mb</em>, <em>n</em> से <em>nd</em>), इसलिए 男 <em>nan</em> बना <em>dan</em> और 馬 \"घोड़ा\" बना <em>ba</em>। स्वर भी खिसके: 経 <em>kyō</em> बना <em>kei</em>। यही कारण है कि कान-ऑन में <em>m-</em> या <em>n-</em> से शुरू होने वाले पाठ इतने कम हैं।</p>\n\n\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"34.26\" data-lng=\"108.95\" data-zoom=\"5\">🗺 तांग कालीन छांगआन (शीआन) की ओर जाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja\">📍 मानचित्र पर जापानी देखें</button></div>\n<h3>परत 3: तो-ऑन 唐音 (12वीं सदी से)</h3>\n<p>नाम से भ्रम होता है: तो-ऑन (\"तांग ध्वनि\") तांग राजवंश को बिल्कुल नहीं दर्शाता। यह नाम काल के हिसाब से ग़लत है: राजवंश के पतन के बहुत बाद तक भी जापानी में 唐 चीन के लिए एक आम शब्द बना रहा। यह बाद की परत है, जो सोंग, युआन और मिंग काल में ज़्यादातर ज़ेन बौद्ध धर्म, चाय-समारोह और खान-पान के रास्ते आई।</p><p>तो-ऑन से आए शब्द कम हैं, पर रोज़मर्रा की चीज़ों में पहचान में आ जाते हैं: <strong>行灯</strong> <em>andon</em> (काग़ज़ की लालटेन), <strong>蒲団</strong> <em>futon</em>, <strong>椅子</strong> <em>isu</em> (कुर्सी), <strong>饅頭</strong> <em>manjū</em>। <em>andon</em> का <em>an-</em> बाद के चीनी उच्चारण को दर्शाता है: तब तक 行 का मध्यकालीन चीनी 匣 आदि व्यंजन — घोष संघर्षी *<em>ɦ-</em>, जो कभी अनुनासिक नहीं था — पूरी तरह लुप्त हो चुका था (*<em>ɦaŋ</em> → <em>aŋ</em>), और जापानी ने बचे हुए अंत्य -ŋ को -n के रूप में लिया, जिसे न गो-ऑन पकड़ पाया था, न कान-ऑन।</p>\n\n<h3>यह क्यों महत्वपूर्ण है</h3>\n<p>ये तीन परतें चीनी ध्वन्यात्मक इतिहास के अलग-अलग कालों के साक्ष्य सँजोए हुए हैं। गो-ऑन, कान-ऑन और मध्यकालीन चीनी पुनर्निर्माणों की तुलना करके, भाषाविद् कई शताब्दियों में फैली चीनी की ध्वनियों का अंदाज़ा कई दिशाओं से मिलाकर लगा सकते हैं। चीनी छंद-कोश अक्षरों को ध्वनि-वर्गों में छाँटते हैं, पर चूँकि वे किसी अक्षर का उच्चारण केवल दूसरे अक्षरों के सहारे बताते हैं, इसलिए सीधे यह नहीं दिखा सकते कि कोई चीज़ सुनाई कैसी देती थी; <em>dan</em> जैसी काना वर्तनी बाहर से एक सुराग़ देती है, भले ही मोटा-मोटा। इसलिए ऐतिहासिक पुनर्निर्माण में जापानी कांजी पाठ चीनी छंद-कोशों, आधुनिक बोलियों और अन्य सिनो-ज़ेनिक परंपराओं के पूरक हैं।</p><ul><li><strong>गो-ऑन</strong>: बौद्ध शब्दावली और मंदिरों के पुराने पाठ, जैसे 経 <em>kyō</em>, 行 <em>gyō</em>, 男 <em>nan</em></li><li><strong>कान-ऑन</strong>: विद्वत् और राजकीय शब्दावली, जैसे 経 <em>kei</em>, 行 <em>kō</em>, 男 <em>dan</em></li><li><strong>तो-ऑन</strong>: ज़ेन, खान-पान और रोज़मर्रा की चीज़ें, जैसे 行灯 <em>andon</em>, 蒲団 <em>futon</em></li></ul><p>तो 行 के तीन चीनी-जापानी पाठ इसलिए हैं कि चीन से लगभग हज़ार साल के संपर्क में हर पाठ अलग दौर में उधार लिया गया।</p><ul><li><strong>गो-ऑन</strong>: बौद्ध शब्दावली और मंदिरों के पुराने पाठ, जैसे 経 <em>kyō</em>, 行 <em>gyō</em>, 男 <em>nan</em></li><li><strong>कान-ऑन</strong>: विद्वत् और राजकीय शब्दावली, जैसे 経 <em>kei</em>, 行 <em>kō</em>, 男 <em>dan</em></li><li><strong>तो-ऑन</strong>: ज़ेन, खान-पान और रोज़मर्रा की चीज़ें, जैसे 行灯 <em>andon</em>, 蒲団 <em>futon</em></li></ul><p>तो 行 के तीन चीनी-जापानी पाठ इसलिए हैं कि चीन से लगभग हज़ार साल के संपर्क में हर पाठ अलग दौर में उधार लिया गया।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"南\">🔢 मानचित्र पर 南 देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"東\">🔢 मानचित्र पर 東 देखें (Go-on tsū vs Kan-on tō)</button></div>\n","min-nan-wenbai":"<h3>एक अक्षर, दो बिल्कुल अलग शब्द</h3>\n<p>मिन नान (होक्किएन/ताइवानी) — फ़ुजियान, ताइवान, दक्षिण-पूर्व एशिया और दुनिया भर के प्रवासी समुदायों में लगभग 3.4 करोड़ लोगों (2025 का अनुमान) की मातृभाषा — में कई आम अक्षरों के <em>दो</em> उच्चारण होते हैं, जो ध्वनि-व्यवस्था की दो अलग परतों से आते हैं: <strong>बोलचाल पठन (白讀 pe̍h-tho̍k)</strong> और <strong>साहित्यिक पठन (文讀 bûn-tho̍k)</strong>।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"一\">🔢 一 दिखाएं</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"日\">☀️ 日 दिखाएं</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"二\">🔢 二 दिखाएं</button>\n</div>\n\n<h3>प्रसिद्ध जोड़े: 一, 兩, 十</h3>\n<ul>\n  <li><strong>一</strong>: बोलचाल <em>tsi̍t</em> vs. साहित्यिक <em>it</em> — ये एक ही शब्द की दो परतें नहीं, बल्कि दो अलग शब्द हैं: <em>it</em> अक्षर 一 का पठन है, जबकि <em>tsi̍t</em> \"एक\" के लिए मिन भाषा का एक अलग शब्द है, जिसका मूल अक्षर 蜀 है (<em>फ़ांगयान</em>, पहली सदी ई.पू.: \"दक्षिणी चू में एक को 蜀 कहते हैं\")। इसे उधार लेकर 一 से लिखा जाता है, इसलिए यह 訓讀 है, 白讀 नहीं</li>\n  <li><strong>兩</strong>: बोलचाल <em>nn̄g</em> vs. साहित्यिक <em>lióng</em> — अक्षर <strong>二</strong> का अपना कोई बोलचाल पठन है ही नहीं, केवल <em>jī</em> (झांगझोउ शैली, दक्षिणी ताइवान) या <em>lī</em> (क्वानझोउ/शियामेन शैली, उत्तरी ताइवान), और यह क्षेत्रीय भेद है, साहित्यिक-बोलचाल का नहीं; इसीलिए रोज़मर्रा में दो वस्तुओं की गिनती 兩 से लिखी जाती है</li>\n  <li><strong>十</strong>: बोलचाल <em>tsa̍p</em> (जैसे <em>tsa̍p ê</em>, \"उनमें से दस\") vs. साहित्यिक <em>si̍p</em> (जैसे <em>si̍p-jī-kè</em>, \"क्रॉस\", शाब्दिक अर्थ \"दस-अक्षर का ढाँचा\") — यहाँ आदि व्यंजन और स्वर, दोनों अलग हैं</li>\n</ul>\n\n\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"nan\">📍 मानचित्र पर ताइवानी देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"25.0\" data-lng=\"121.5\" data-zoom=\"6\">🗺 ताइवान की ओर जाएँ</button></div>\n<h3>दो प्रणालियां क्यों हैं?</h3>\n<p>बोलचाल परत <strong>पुरानी</strong> है, और वह ख़ुद भी परतदार है। उत्तर से आए बसने वाले चीनी को लहर-दर-लहर फ़ुजियान लाए: सबसे पुरानी शब्दावली आम तौर पर हान राजवंश (206 ई.पू. – 220 ई.) तक ले जाई जाती है, और दूसरी परत उत्तरी और दक्षिणी राजवंशों (420–589) तक। फ़ुजियान के पहाड़ों ने उसे उत्तर-दक्षिण के मुख्य प्रवास-मार्गों से अलग रखा — वे मार्ग और पश्चिम में गान और शियांग नदी-घाटियों से होकर गुज़रते थे — इसलिए वहाँ की बोली सदियों तक अपनी राह चली। साहित्यिक परत बाद में आई, तांग राजवंश (618–907) में, राजधानी छांगआन की प्रतिष्ठित बोली के नमूने पर। कन्फ़्यूशियाई ग्रंथ ज़ोर से पढ़ने वाले विद्वानों को राजधानी के \"सही\" उच्चारण चाहिए थे, जो तब तक उन्हीं अक्षरों के स्थानीय विकास से <em>बहुत अलग</em> हो चुके थे। यह परत बोलचाल को हटाने के बजाय उसके ऊपर चढ़ गई।</p>\n\n<h3>भाषाई समय-कैप्सूल के रूप में मिन नान</h3>\n<p>मिन नान — और सबसे बढ़कर उसकी बोलचाल परत — पुरानी चीनी और शुरुआती मध्यकालीन चीनी की वे विशेषताएँ सँजोए हुए है जिन्हें मंदारिन और अधिकांश उत्तरी बोलियाँ खो चुकी हैं या घिस चुकी हैं: अंतिम स्पर्श व्यंजन (-p, -t, -k), जिन्हें मानक मंदारिन ने पूरी तरह खो दिया है जबकि मिन नान उन्हें कैंटोनीज़ और हक्का की तरह मज़बूती से बनाए रखता है; और 日母 वर्ग का आदि व्यंजन, क्योंकि 二 <em>jī</em> में मध्यकालीन चीनी से विरासत में मिला व्यंजन आज भी जीवित है (बैक्सटर और सगार का पुनर्निर्मित पुरानी चीनी रूप *<em>ni[j]-s</em>), जबकि मंदारिन में यह आदि व्यंजन पूरी तरह घिस गया और केवल <em>èr</em> का स्वर बचा है। इसके अलावा दो और निशान: <strong>पुराने दंत्य स्पर्श</strong> — जहाँ मंदारिन में <em>zh-</em> या <em>ch-</em> है, वहाँ मिन नान अक्सर पुरानी चीनी का सादा <em>t-</em> रखता है: 豬 <em>ti</em> \"सूअर\" (मंदारिन <em>zhū</em>), 茶 <em>tê</em> \"चाय\" (मंदारिन <em>chá</em>) — और अमोय का यही <em>tê</em>, जिसे डच व्यापारी यूरोप ले गए, अंग्रेज़ी शब्द <em>tea</em> का स्रोत है। और <strong>अभी <em>f</em> नहीं</strong> — पुरानी चीनी में <em>f</em> ध्वनि थी ही नहीं, और बोलचाल परत अक्सर पुराना <em>p-</em> रखती है: 飛 \"उड़ना\" बोलचाल में <em>pue</em> (या <em>pe</em>) है, साहित्यिक में <em>hui</em>, और मंदारिन में <em>fēi</em>। जेरी नॉर्मन दोनों पलड़े बराबर रखते हैं: मिन में ऐसे बहुत-से पुरातन रूप बचे हैं जो सिनिटिक में और कहीं नहीं मिलते, पर उसमें ऐसे नए बदलावों की भी लंबी सूची है जो सिर्फ़ मिन में हुए। ऐतिहासिक भाषाविज्ञान के लिए उसका मूल्य यह नहीं कि वह अपने पड़ोसियों से बस \"पुराना\" है, बल्कि यह कि, जैसा नॉर्मन तर्क देते हैं, मिन अकेला बड़ा बोली-समूह है जिसे छंद-कोशों की मध्यकालीन चीनी से पूरी तरह व्युत्पन्न नहीं किया जा सकता, इसलिए वह ऐसे सबूत सँजोए हुए है जो कोई और बोली नहीं दे सकती।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🔢 मानचित्र पर 人 देखें (lâng vs. jîn)</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"水\">🔢 मानचित्र पर 水 देखें (chúi vs. súi)</button></div>\n\n<h3>कौन-सी परत चुनें</h3><p>धाराप्रवाह मिन नान बोलने वाला लगभग अनजाने ही स्तर बदलता रहता है:</p><ul><li>बाज़ार में वस्तुएँ गिनना: <em>tsi̍t, nn̄g, sann…</em> (बोलचाल की परत)</li><li>कविता पढ़ना या कोई सरकारी पदनाम बोलना: <em>it, jī, sam…</em> (साहित्यिक परत)</li><li>ग्यारह तक गिनना: <em>tsa̍p-it</em> — 十 के लिए बोलचाल का <em>tsa̍p</em>, 一 के लिए साहित्यिक <em>it</em></li><li>“सोमवार”: <em>pài-it</em>, जो <em>lé-pài-it</em> (禮拜一, “सप्ताह-एक”) का छोटा रूप है — संख्या के लिए साहित्यिक <em>it</em>। 拜 <em>pài</em> का एक ही पठन है, इसलिए उसके लिए बोलचाल/साहित्यिक में चुनने का सवाल ही नहीं उठता।</li></ul><p>यह अदला-बदली सोच-समझकर किया गया व्याकरणिक हिसाब नहीं है; यह घर के माहौल से अपने-आप आती है, और इसमें चूक उतनी ही जल्दी बता देती है कि बोलने वाला मातृभाषी नहीं, जितना कोई ग़लत स्वराघात।</p><div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">👤 人 आज़माएँ (lâng बनाम jîn)</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"水\">💧 水 आज़माएँ (chúi बनाम súi)</button>\n</div><p>文白異讀 प्रणाली कोई विचित्रता या दोष नहीं है — और न ही यह केवल मिन नान की विशेषता है, क्योंकि वू, हक्का और कैंटोनीज़ सभी बोलचाल की परत पर साहित्यिक पाठ की परत चढ़ाते हैं। मिन नान को अलग करती है उसकी बोलचाल-परत की गहराई। यह चीनी भाषा के इतिहास की एक जीती-जागती आड़ी काट है, जिसमें चीनी के अलग-अलग युग हर वक्ता के मुँह में साथ-साथ बैठे हैं: नीचे हान राजवंश और उसके बाद की जनभाषा, ऊपर तांग-कालीन पठन-मानक। परतों की इसी गहराई के कारण ऐतिहासिक भाषाविद् मिन नान को ऐसा सबूत मानते हैं जिसके बिना काम नहीं चलता।</p>","korean-toumeop-rule":"<h3>एक अक्षर, दो उच्चारण</h3><p>HanMap में 六 टाइप करें और आपको दक्षिण कोरियाई <strong>육 (yuk)</strong> और उत्तर कोरियाई <strong>륙 (ryuk)</strong> साथ-साथ दिखेंगे। यह बोलियों का अपने-आप हुआ फ़र्क़ नहीं, बल्कि दोनों सरकारों की आधिकारिक वर्तनी में दर्ज सोची-समझी नीति है।</p><h3>नियम क्या कहता है</h3><p>दक्षिण कोरिया का 두음법칙 (頭音法則) शब्द के आरंभ में आने वाले चीनी-कोरियाई अक्षरों के /l/ और /n/ को दो अलग-अलग तरीकों से बदलता है। /i/ या /y/ से पहले व्यंजन पूरी तरह लुप्त हो जाता है: 龍 → <strong>용</strong> yong, 룡 ryong नहीं। अन्य स्वरों से पहले आरंभिक /l/ बदलकर /n/ हो जाता है: 來 (आना) शब्द के आरंभ में <strong>내</strong> nae (내일 來日, आने वाला कल) होता है, किंतु शब्द के भीतर 래 rae (미래 未來, भविष्य)। आरंभिक /n/ भी <em>i</em> या <em>y</em> से पहले यही करता है: 女 (स्त्री) 여자 'स्त्री' में 여 yeo है, पर 소녀 'लड़की' में 녀 nyeo। यहाँ तक कि उपनाम भी बँट जाते हैं: आम उपनाम 李 दक्षिण में 이 Yi है और उत्तर में 리 Ri। यह नियम 1933 में लिखित रूप में तय हुआ और 1988 का संशोधन आज भी मानक है।</p><h3>उत्तर कोरिया ने इसे क्यों नहीं माना</h3><p>1945 के विभाजन के बाद उत्तर कोरिया ने 1948 की नई जोसियन वर्तनी में ही इस नियम को नहीं अपनाया, और 1954 में विज्ञान अकादमी द्वारा जारी जोसियन वर्तनी संहिता ने इसे मूल रूप की कृत्रिम विकृति बताते हुए औपचारिक रूप से खारिज किया और शब्दारंभिक /l-/ तथा /n-/ को बनाए रखा, यानी वहाँ 룡, 래, 립 ही पढ़ा जाता है, जो मध्यकालीन चीनी स्रोत-उच्चारणों के ज़्यादा क़रीब है।</p><h3>राजनीतिक आयाम</h3><p>यह विभाजन सीमा के आर-पार रोज़मर्रा के पढ़ने पर असर डालता है: उत्तर कोरियाई पाठ पढ़ते समय दक्षिण कोरियाइयों को दर्जनों आम शब्द मन ही मन बदलकर पढ़ने पड़ते हैं, और दोनों वर्तनियों का मेल एक असली काम माना जाता है, सजावटी नहीं। 2005 से दोनों पक्षों के भाषाविद् एक संयुक्त शब्दकोश, 《겨레말 큰사전》, तैयार करने के लिए मिलने लगे; पर उत्तर के चौथे परमाणु परीक्षण और केसोंग औद्योगिक क्षेत्र के बंद होने के बाद 2016 से संयुक्त बैठकें स्थगित हैं, और दक्षिणी दल अकेले काम जारी रखे हुए है।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"六\">🔢 मानचित्र पर 六 देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko\">📍 मानचित्र पर कोरियाई देखें</button></div>\n","japanese-go-on-bias":"<h3>एक कांजी, दो ओन-योमि पाठ</h3><p>बहुत-से कांजी के दो अलग-अलग ओन-योमि होते हैं: गो-ऑन (呉音) और कान-ऑन (漢音)। बहुत-से दूसरों में दोनों परतें संयोग से एक जैसी ही सुनाई देती हैं। 経 को गो-ऑन में <strong>kyō</strong> और कान-ऑन में <strong>kei</strong> पढ़ा जाता है। व्यवहार में お経 (सूत्र) में kyō आता है और 経済 (अर्थव्यवस्था) में kei।</p><h3>पहली लहर: कोरिया के रास्ते</h3><p>5वीं–6वीं सदी में बेकजे और गोगुरियो के विद्वानों ने जापान में चीनी लिपि पहुँचाई। उन्होंने जो पाठ पहुँचाए, उन्हीं को आज गो-ऑन कहा जाता है — यांग्त्से के दक्षिण में वू क्षेत्र के नाम पर, हालाँकि यह नाम सदियों बाद जुड़ा, और शायद कान-ऑन के पैरोकारों ने ही जोड़ा। आमतौर पर माना जाता है कि गो-ऑन दक्षिणी राजवंशों की राजधानी जियानकांग (आज का नानजिंग) के आसपास की चीनी भाषा को दर्शाता है, पर किसी समकालीन स्रोत से इसकी पुष्टि नहीं होती, और कोरियाई मार्ग ने इन पाठों को कितना बदला, यह भी स्पष्ट नहीं है। 607 में जापान के चीन में नियमित दूतमंडल भेजना शुरू करने से पहले ही बौद्ध सूत्र, जप और मंदिर के अनुष्ठान इसी उच्चारण में ढल चुके थे।</p><h3>तांग की प्रतिष्ठित परत: कान-ऑन</h3><p>7वीं–8वीं सदी में जापानी दूत (केंतोशी) छांगआन का उच्चारण वापस लाए — कान-ऑन (\"हान ध्वनियाँ\"), जो विद्वानों का पाठ बन गया: 文化 bunka (संस्कृति) पूरी तरह कान-ऑन है। दरबार ने इसके लिए ख़ूब ज़ोर लगाया। 792 में सम्राट कानमु ने कान-ऑन को बढ़ावा देने का फ़रमान जारी किया, राजकीय अकादमी के छात्रों के लिए इसे सीखना अनिवार्य था, और जिन भिक्षुओं ने इसे नहीं सीखा, उन्हें चीन जाने की इजाज़त नहीं मिलती थी। फिर भी मंदिरों का पाठ काफ़ी हद तक विरासत वाले गो-ऑन पर ही टिका रहा, और रोज़मर्रा के शब्दों में दोनों परतें घुल-मिल गईं। 政治 seiji (राजनीति) में कान-ऑन <em>sei</em> के साथ गो-ऑन <em>ji</em> है, और 経済 keizai (अर्थव्यवस्था) में कान-ऑन <em>kei</em> के साथ गो-ऑन <em>zai</em>।</p><h3>व्यावहारिक उदाहरण</h3><p>業 गो-ऑन में <strong>gō</strong> (कर्म), कान-ऑन में <strong>gyō</strong>; 極楽 gokuraku (परम सुख) में गो-ऑन <em>goku</em> है, जहाँ कान-ऑन <em>kyoku</em> देता; 道路 dōro (सड़क) में 道 गो-ऑन dō है, पर 神道 Shintō में कान-ऑन tō — गो-ऑन रोज़मर्रा के कई शब्दों में भी बना रहा। मंदिरों के नाम भी इसी झुकाव पर चलते हैं: 法隆寺 Hōryū-ji, 東大寺 Tōdai-ji — 寺 हमेशा गो-ऑन <em>ji</em> है, कान-ऑन <em>shi</em> कभी नहीं।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"心\">🔢 मानचित्र पर 心 देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja\">📍 मानचित्र पर जापानी देखें</button></div>\n","kokuji-japan-made-chars":"<h3>कोकुजि: जापान द्वारा बनाए गए हान अक्षर</h3><p>जब जापान ने 5वीं–6वीं शताब्दी में हान लिपि अपनाई, तो चीनी अक्षर चीन की चीज़ें और विचार लिखते थे, जापान के नहीं। इसलिए जापानी विद्वानों ने <strong>कोकुजि (国字)</strong> गढ़े, जो या तो <em>काई-इ (会意)</em> थे, यानी अर्थ वाले घटकों का मेल, या <em>केइसेइ (形声)</em>, यानी अर्थ वाले मूलांश के साथ ध्वनि का संकेत।</p><h3>प्रमुख उदाहरण</h3><ul><li><strong>峠 (tōge, पहाड़ी दर्रा)</strong>: 山 (पहाड़) + 上 (ऊपर) + 下 (नीचे) — वह बिंदु जहाँ रास्ता चढ़ना छोड़कर उतरने लगता है। शुद्ध 会意।</li><li><strong>凧 (tako, पतंग)</strong>: आम तौर पर 几 'हवा' + 巾 'कपड़ा' पढ़ा जाता है, हालाँकि शायद इसकी शुरुआत 鳳巾 के मेल से हुई हो, जो 'पतंग' का एक पुराना लिखित रूप था। पतंगें ख़ुद चीन से आई थीं, जहाँ उन्हें 紙鳶 'काग़ज़ी चील' लिखा जाता था; जापान ने बस इसे एक अक्षर वाली वर्तनी दे दी।</li><li><strong>働 (hataraku, काम करना)</strong>: व्यक्ति + गति। सबसे ज़्यादा इस्तेमाल होने वाला कोकुजि, और उन गिने-चुनों में से एक जिनका ओन-योमि भी है (<em>dō</em>, 動 से लिया गया)। यह जोयो सूची के लगभग नौ कोकुजि में से एक है।</li><li><strong>雫 (shizuku, पानी की बूंद)</strong>: वर्षा + नीचे। देखने में ही एक छोटी-सी कविता।</li><li><strong>笹 (sasa, बौना बांस)</strong>: बांस + 世 (उच्चारण <em>yo</em>, जो बांस की गांठ के अर्थ वाले <em>yo</em> से मेल खाता है; कुछ विद्वान निचले भाग को 葉 यानी 'पत्ता' का लघु रूप मानते हैं)। तानाबाता पर्व का अनिवार्य पौधा।</li></ul><h3>जापान को इनकी ज़रूरत क्यों पड़ी</h3><p>ज़्यादातर कोकुजि किसी ऐसे देशज जापानी शब्द को एक अक्षर देते हैं जिसका कोई सटीक चीनी जोड़ नहीं था। मछलियाँ इनका ख़ास तौर पर बड़ा समूह हैं: 鰯 <em>iwashi</em> (सार्डीन, 8वीं सदी में भी यूँ ही लिखी जाती थी), 鱚 <em>kisu</em> (सिलागो) और 鱈 <em>tara</em> (कॉड)। दूसरे शिंतो और रोज़मर्रा के जीवन से जुड़े हैं: 榊 <em>sakaki</em>, पवित्र वृक्ष, बस 木 'पेड़' + 神 'देवता' है; 辻 <em>tsuji</em>, चौराहा, है 辶 'रास्ता' + 十 'क्रॉस'; 畑 <em>hatake</em> फ़सलों का सूखा खेत है।</p><h3>आश्चर्यजनक वापसी</h3><p>कुछ कोकुजि <em>पश्चिम</em> की ओर भी गए। सबसे साफ़ उदाहरण है <strong>腺 (sen, ग्रंथि)</strong>: 'मांस' 月 + 泉 'झरना' — शरीर का वह अंग जिससे द्रव उमड़ता है। इसे लगभग 1800 में एदो-कालीन डच-विद्या के विद्वान उदागावा गेनशिन ने डच <em>klier</em> के अनुवाद के लिए गढ़ा, और यह चीनी — जहाँ 腺 <em>xiàn</em> आज ग्रंथि के लिए मानक शब्द है — और कोरियाई, दोनों में पहुँच गया। <strong>鱈</strong> (xuě) 'कॉड' भी आज इस मछली के लिए चीनी का साधारण अक्षर है (<em>xuě</em>, सरलीकृत 鳕)।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja_kun\">📍 मानचित्र पर कुन-योमि (जापानी मूल पठन) देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"36.2\" data-lng=\"138.0\" data-zoom=\"5\">🗺 जापान की ओर जाएँ</button></div>\n","korea-kuk-ja":"<h3>कोरिया के हान अक्षरों की छोटी सूची</h3><p>जापान के घर में बने अक्षर, कोकुजि, सैकड़ों में हैं। कोरिया का समकक्ष — आम तौर पर <strong>गुकजा (國字)</strong>, यानी \"राष्ट्रीय अक्षर\", या <em>गोयू हांजा</em> (固有漢字), यानी \"देशज हान अक्षर\", कहलाने वाला — एक छोटा और कम जाना-पहचाना समूह है: अब तक लगभग 200 पहचाने गए हैं, हालाँकि और भी मिल सकते हैं। और इसके कारण बहुत कुछ बताते हैं।</p><h3>प्रमुख अक्षर</h3><ul><li><strong>畓 (dap, धान का खेत)</strong>: जल + खेत। सबसे महत्वपूर्ण गुकजा, और सबसे पुराने में से एक: यह सिल्ला काल के अभिलेखों में ही दिख जाता है, जिनमें जापान के शोसोइन में सुरक्षित 8वीं सदी का एक सिल्ला दस्तावेज़ भी है। प्रायद्वीप में धान की खेती केंद्रीय थी, इसलिए धान के खेत के लिए एक अक्षर वाला शब्द काम का था; चीनी में दो अक्षरों वाला 水田 लिखा जाता है।</li><li><strong>乭 (Dol)</strong>: लगभग केवल व्यक्तिगत नामों में प्रयुक्त। आज इसके सबसे मशहूर धारक हैं गो चैंपियन ली से-दोल (李世乭), जिन्होंने 2016 में AlphaGo से मुक़ाबला किया। इसकी बनावट साफ़ समझ आती है और ठेठ कोरियाई है: 石 से अर्थ और देशज पाठ <em>दोल</em> (पत्थर) दोनों मिलते हैं, जबकि अंत्य व्यंजन <em>-ल</em> लिखने के लिए 乙 जोड़ा जाता है — यह <em>इदू</em> की वह पद्धति है जिसमें देशज शब्द का अंतिम व्यंजन एक अतिरिक्त अक्षर से लिखा जाता है।</li><li><strong>媤 (si)</strong>: स्त्री (女) + 思, अर्थ \"पति का परिवार\"। यह रोज़मर्रा के शब्दों में आज भी ज़िंदा है, जैसे 시댁 <em>sidaek</em> (媤宅, \"ससुराल\") और 시어머니 <em>si-eomeoni</em> (\"सास\")।</li><li><strong>स्थान-नाम अक्षर</strong>: ऐतिहासिक अभिलेखों के जिला व ग्राम नामों में ऐसे अक्षर हैं जो किसी भी चीनी शब्दकोश में नहीं मिलते।</li></ul><h3>जापान से कम क्यों?</h3><p>दो कारण सबसे अलग दिखते हैं। पहला, जोसियन विद्वान शास्त्रीय चीनी (<em>हानमुन</em>, 漢文) को प्रतिष्ठित लेखन भाषा मानते थे और जिन अक्षरों को चीन इस्तेमाल नहीं करता था, उन्हें गँवारू रूप (俗字) कहकर हेय समझते थे। इसलिए ज़्यादातर गुकजा विद्वान अभिजात वर्ग ने नहीं, बल्कि उन लिपिकों ने गढ़े जो <em>इदू</em> दस्तावेज़ — चीनी अक्षरों में लिखी कोरियाई — तैयार करते थे, जहाँ ऐसी वैचारिक बंदिशें ढीली थीं। दूसरा, कई गुकजा का काम बस देशज कोरियाई शब्दांश लिखना है, जैसे <em>dol</em> के लिए 乭; 1443 में सेजोंग महाराज के <strong>हांगुल</strong> के बाद यह काम वर्णमाला से कहीं आसानी से हो सकता था। इसके उलट जापानी 8वीं से 19वीं सदी तक कोकुजि गढ़ती रही, जिनमें से कई मछलियों और पौधों के नाम हैं।</p><h3>आज की विरासत</h3><p>अधिकांश गुकजा केवल प्राचीन साहित्य, प्रशासनिक अभिलेखों और नामों में जीवित हैं। <strong>畓</strong> इसका चौंकाने वाला अपवाद है, और उसके साथ 垈 (<em>dae</em>, \"भवन-भूखंड\") भी: दक्षिण कोरिया की आधिकारिक भूमि-श्रेणियों — भू-अभिलेख के 28 <em>जिमोक</em> (地目) — में आज भी 답 (畓, धान का खेत) और 대 (垈, भवन-भूमि) शामिल हैं, यानी कोरिया में बने अक्षर आज तक ज़मीन के रजिस्टरों में बैठे हैं।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"37.5\" data-lng=\"127.0\" data-zoom=\"5\">🗺 कोरिया की ओर जाएँ</button></div>\n","naxi-dongba-living-pictograms":"<h3>युगों को पार करने वाली लिपि</h3><p>अधिकांश चित्रलिपि प्रणालियाँ हजारों साल पहले लुप्त हो गईं। मिस्र के हिरोग्लिफ लगभग 400 ईस्वी में मूक हो गए; माया लिपि स्पेनिश विजय के बाद ज़्यादा दिन नहीं टिकी। लेकिन <strong>डोंगबा लिपि (東巴文字)</strong> इस ढर्रे को तोड़ती है — चीन के युन्नान प्रांत में नाशी जनजाति के डोंगबा पुजारी आज भी लगभग एक हज़ार से दो हज़ार के बीच चित्र-चिह्न (गिनती इस पर निर्भर है कि रूपांतरों को कैसे गिना जाए) याद रखते, जपते और हाथ से खींचते हैं।</p><p>नाशी लोगों की संख्या लगभग 3,20,000 है, जो लिजियांग के आसपास केंद्रित हैं। डोंगबा वंशानुगत अनुष्ठान विशेषज्ञ हैं जिनके नाम का अर्थ है \"बुद्धिमान व्यक्ति\" या \"गुरु\" (तिब्बती ston pa \"गुरु\" से)। यह लिपि रोज़ की पढ़ाई-लिखाई के लिए नहीं, बल्कि गाए जाने वाले अनुष्ठान-पाठों को याद रखने के सहारे के रूप में बरती जाती है। लिखे चिह्न हर शब्द दर्ज नहीं करते: पन्ने पर बने कुछ चित्र छंद के एक लंबे अंश की याद दिलाते हैं, जो डोंगबा को कंठस्थ होता है।</p><h3>पहले चित्र, फिर ध्वनि</h3><p>डोंगबा चिह्न मुख्यतः चित्रात्मक हैं: मछली का चित्र 'मछली' का अर्थ देता है; उठी हुई भुजाओं वाली मानव आकृति 'नृत्य' बताती है; और जटिल विचार कई चित्रों को जोड़कर व्यक्त किए जाते हैं। पर वे <em>पूर्णतः</em> चित्रात्मक नहीं हैं। किसी भी चिह्न को केवल उसकी ध्वनि के लिए उधार लिया जा सकता है — यही <strong>ध्वनि-उधार (रीबस) सिद्धांत</strong> है — इसलिए दो आँखों का चित्र (<em>myə</em>) समध्वनि शब्द 'भाग्य' लिखता है, चावल के कटोरे का चिह्न 'भोजन' और 'नींद' (<em>xa</em>) दोनों के लिए चलता है, और गोरल नामक पहाड़ी बकरी-मृग (<em>se</em>) का चिह्न एक व्याकरणिक परसर्ग का काम करता है। नाशी लोगों ने एक दूसरी लिपि भी सँभाले रखी है — <em>गेबा</em> (哥巴) शब्दांश लिपि — जो दुर्लभ है, कभी मानकीकृत नहीं हुई और अपेक्षाकृत कम पांडुलिपियों में ही बची है; वह चित्रचिह्नों के साथ उनका उच्चारण दर्ज करने तथा मंत्र, अनुबंध और पत्र लिखने के लिए प्रयुक्त होती है। डोंगबा लेखन किसी भी आधुनिक लिपि की तुलना में कीलाक्षर लिपि के आरंभिक चरण (लगभग 3200–2900 ईसा पूर्व) के अधिक निकट है, फिर भी वह आज जीवित है।</p><h3>यूनेस्को और समय के साथ दौड़</h3><p>2003 में यूनेस्को ने प्राचीन नाशी डोंगबा पांडुलिपियों को अपने 'विश्व स्मृति रजिस्टर' में शामिल किया। सांस्कृतिक क्रांति के दौरान हज़ारों पांडुलिपियाँ नष्ट कर दी गईं, और जो बचीं उनमें से लगभग आधी पहले ही विदेश — अमेरिका, जर्मनी और स्पेन के संग्रहों में — पहुँच चुकी थीं। यूनेस्को के अनुसार ग्रंथ पढ़ सकने वाले गिने-चुने उस्ताद ही बचे हैं। युन्नान प्रांतीय अधिकारियों ने प्रशिक्षण कार्यक्रमों के लिए धन दिया है, लिजियांग में एक डोंगबा संस्कृति शोध संस्थान है, और ये चित्रचिह्न अब लिजियांग के पुराने शहर में बसों और दुकानों के बोर्डों पर चीनी और अंग्रेज़ी के साथ दिखते हैं। यह लिपि संग्रहालय की वस्तु बनने के बजाय जीवित परंपरा के रूप में बच पाएगी या नहीं, यह सवाल अभी खुला है।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"26.87\" data-lng=\"100.23\" data-zoom=\"6\">🗺 लीच्यांग, युन्नान की ओर जाएँ</button></div>\n","yi-syllabary":"<h3>आठ हज़ार चिह्नों वाली लिपि</h3><p>यी जनजाति (彝族, Yízú) के 2020 की जनगणना के अनुसार 98 लाख लोग सिचुआन, युन्नान, गुइझोउ और गुआंगशी में फैले हैं। उनकी पारंपरिक लिपि — <strong>यी लिपि (彝文, Yí wén)</strong> — चीनी की तरह एक लोगोग्राफ़िक व्यवस्था है: हर चिह्न एक ऐसे शब्दांश के लिए है जो साथ ही एक शब्द या रूपिम भी है, और हर क्षेत्रीय रूप को गिनें तो सूचियों में हज़ारों चिह्न दर्ज हैं। किंवदंती इसका आविष्कार तांग राजवंश के एक नुओसु नायक, आकी, के नाम करती है, पर सबसे पुराना तिथियुक्त नमूना कहीं नया है: 1485 की एक काँसे की घंटी पर खुदा लेख। लिपिक और पुरोहित चिह्नों को केवल उनकी ध्वनि के लिए भी बरतते थे, इसलिए यह लिपि चीनी वर्णों और शब्दांश-लिपि के बीच कहीं बैठती थी — और दोनों में से किसी से भी कहीं कम एकरूप थी। प्रत्येक कुल या क्षेत्र अपना चिह्न-समूह बनाए रखता था, इसलिए लियांगशान (涼山) का कोई अनुष्ठान-ग्रंथ गुइझोउ के पाठक की समझ से बाहर हो सकता था, भले ही दोनों यी बोलते हों। इससे लिपि समृद्ध तो हुई, पर बिखरी हुई भी रही।</p><h3>1980 का मानकीकरण</h3><p>पीपल्स रिपब्लिक की स्थापना के बाद सरकार ने अल्पसंख्यक लिपियों का अध्ययन शुरू किया, और इस काम में दशकों लगे। 1974 में सिचुआन के जातीय मामलों के आयोग ने पारंपरिक चिह्नों से एक शब्दांश-लिपि तैयार की, और 1980 में राज्य परिषद ने उसे <strong>लियांगशान मानक यी लिपि (涼山規範彝文)</strong> के रूप में मंज़ूरी दी: 756 मूल चिह्न, नुओसु की लियांगशान बोली के हर शब्दांश के लिए एक, और 63 ऐसे शब्दांशों के लिए जो केवल चीनी उधार-शब्दों में आते हैं — कुल 819। चार में से तीन स्वराघातों के अपने चिह्न हैं; चौथा मध्य-स्वराघात वाले चिह्न पर एक छोटा चाप लगाकर लिखा जाता है। 1956 के सरलीकृत चीनी सुधार की तरह यह भी ऊपर से लागू हुआ, पर इसकी कटौती कहीं गहरी थी: लगभग 8,000 चिह्नों से 819 तक।</p><p>यह 819-चिह्न प्रणाली आज लियांगशान यी स्वायत्त प्रान्त में द्विभाषी सड़क संकेतों, प्राथमिक विद्यालय पाठ्यपुस्तकों और स्थानीय प्रसारण में दिखाई देती है। यूनिकोड मानक यी शब्दांश-लिपि को Yi Syllables ब्लॉक (U+A000–U+A48F) में रखता है और U+A490–U+A4CF पर अलग Yi Radicals ब्लॉक है, इसलिए डिजिटल पाठ लिखना आसान है। पर यह मानक सिचुआन का है: युन्नान ने अपनी अलग राह पकड़ी और 1987 में 2,608 चिह्नों वाली युन्नान मानक यी को मंज़ूरी दी, जिनमें से ज़्यादातर लोगोग्राम हैं — उन्हें इसलिए रखा गया ताकि अलग-अलग यी भाषाएँ बोलने वाले एक-दूसरे का लिखा पढ़ सकें।</p><h3>मानकीकरण की राजनीति</h3><p>सभी ने सुधार का स्वागत नहीं किया। लगभग 8,000 चिह्नों वाला पारंपरिक संग्रह पढ़ने वाले विद्वान और बड़े-बुज़ुर्ग तर्क देते हैं कि नया मानक बोलीगत बारीकियों को मिटा देता है और केवल 819 मानक पर प्रशिक्षित युवा पीढ़ी के लिए हज़ारों ऐतिहासिक पांडुलिपियों को अपठनीय बना देता है। सरलीकृत और पारंपरिक चीनी से इसकी तुलना अक्सर की जाती है, और वह तुलना भी उतनी ही विवादित है। सरलीकृत और पारंपरिक चीनी से इसकी तुलना अक्सर की जाती है, और वह तुलना भी उतनी ही विवादित है। आज पारंपरिक लिपि पढ़ना ज़्यादातर <em>बिमो</em> का काम है — वे नुओसु पुरोहित जो आज भी पुरानी पांडुलिपियाँ नक़ल करते और उनका पाठ करते हैं — और गिने-चुने अकादमिक शोधकर्ताओं का; ऐसी दसियों हज़ार पांडुलिपियाँ बची हुई हैं।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"28.01\" data-lng=\"102.26\" data-zoom=\"6\">🗺 ल्यांगशान, सिचुआन की ओर जाएँ</button></div>\n","zhuang-sawndip-script":"<h3>साउनदिप क्या है?</h3><p><strong>साउनदिप</strong> (ज़ुआंग <em>saw</em> 'अक्षर' + <em>ndip</em> 'कच्चा, अपरिपक्व' — शाब्दिक अर्थ 'कच्चे अक्षर', जो <em>sawgun</em> यानी 'हान के अक्षरों' के विपरीत है; चीनी में 古壯字 'प्राचीन ज़ुआंग अक्षर' या <em>फांगकुआई झ्वांगज़ी</em> 方塊壯字 'वर्गाकार ज़ुआंग अक्षर') चीन की सबसे बड़ी अल्पसंख्यक जाति — ज़ुआंग लोग, जिनकी संख्या 2020 की जनगणना में 1.96 करोड़ थी — की पारंपरिक लिपि है। इसका उपयोग ताई-कादाई भाषा लिखने के लिए किया जाता था। इसकी शुरुआत अनिश्चित है। ज़ुआंग क्षेत्र के तांग-कालीन दो शिलालेख (682 और 697 ई.) चीनी में लिखे हैं, पर बाद वाले में ही कुछ ग़ैर-मानक स्थानीय अक्षर मिल जाते हैं, जैसे <em>naz</em> 'धान का खेत' के लिए एक; और आम तौर पर माना जाता है कि यह लिपि हज़ार वर्ष से अधिक समय से प्रयोग में रही है, यद्यपि बची हुई पांडुलिपियाँ कहीं बाद की हैं — अधिकांशतः छिंग काल की वे प्रतिलिपियाँ जिनकी मूल रचनाएँ मिंग काल या उससे पहले की हैं।</p><h3>हान लिपि उधार लेने की तीन रणनीतियाँ</h3><ul><li><strong>ध्वन्यात्मक उधारी (जिआजिए)</strong> — हान अक्षर को अर्थ छोड़कर सिर्फ़ ध्वनि के लिए बरतना — ठीक जापानी <em>मान्योगाना</em> की तरह। क्रिया <em>miz</em> 'होना, रखना' लिखी जाती है 眉 से, जिसका चीनी अर्थ है 'भौंह' — बस ध्वनि के लिए। यही प्रमुख सिद्धांत है: डेविड होम का अनुमान है कि लगभग 71% साउनदिप अक्षर ध्वन्यात्मक हैं।</li><li><strong>अर्थगत उधारी</strong>: जिस हान अक्षर का अर्थ ज़ुआंग शब्द से मेल खाता हो, उसे उधार लेना, चाहे उच्चारण बिल्कुल अलग हो।</li><li><strong>स्थानीय निर्माण (आकार-ध्वनि यौगिक)</strong> — अर्थ-मूल (बुशू) और ध्वनि-घटक को मिलाकर <em>नए अक्षर गढ़ना</em>। <em>Bya</em> 'पहाड़' है 岜 — 山 'पहाड़' और ध्वनि के लिए 巴 <em>ba</em>; <em>vunz</em> 'व्यक्ति' है 伝 — 'व्यक्ति' मूलक 亻 और ध्वनि के लिए 云। ऐसे अक्षर दिखते चीनी जैसे हैं, पर मानक चीनी पढ़ने वाले के लिए इनका कोई अर्थ नहीं।</li></ul><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"za\">📍 मानचित्र पर ज़ुआंग भाषा देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"23.5\" data-lng=\"108.0\" data-zoom=\"6\">🗺 क्वांगशी की ओर जाएँ</button></div><h3>萬葉仮名 से समांतर</h3><p>जापानी मान्योगाना से समानता ध्यान खींचती है, पर एक हद तक ही। दोनों प्रणालियाँ हान अक्षरों का ध्वन्यात्मक प्रयोग करके एक गैर-सिनितिक भाषा लिखती हैं। फिर भी साउनदिप और आगे गया: मान्योगाना अंततः सिमटकर काना अक्षरमालाएँ बन गया, जबकि साउनदिप ने अपने पूरे अक्षर कभी नहीं छोड़े। साउनदिप का हर चिह्न हान अक्षर जितना ही भरा-पूरा दिखता है, इसलिए साउनदिप का पृष्ठ पहली नज़र में चीनी पृष्ठ जैसा दिखता है, फिर भी सिर्फ़ मंदारिन जानने वाला उसे बिल्कुल नहीं पढ़ पाता।</p>\n\n<h3>अनुष्ठानिक और लोकव्यवहार में प्रयोग</h3><p>साउनदिप को किसी शाही सत्ता ने कभी मानकीकृत नहीं किया। वह ज़ुआंग गाँवों के पुरोहितों (<em>mo</em> 摩) के हाथों अपने-आप पनपा; वे उसका प्रयोग अनुष्ठानिक मंत्रों, <em>Buluotuo</em> (布洛陀) जैसे महाकाव्य गीतों और पंचांगों को लिखने में करते थे। अलग-अलग गाँव अक्सर एक ही शब्द के लिए अलग अक्षर बरतते थे। इस स्थानीय विविधता का अर्थ है कि एक ही ज़ुआंग शब्द की अलग-अलग पांडुलिपियों में कई अलग वर्तनियाँ मिल सकती हैं। इस लिपि के पहले और अब तक के एकमात्र शब्दकोश, <em>Sawndip Sawdenj</em> (1989), को अपनी 4,900 प्रविष्टियों के लिए 10,000 से ज़्यादा अक्षरों की ज़रूरत पड़ी।</p>\n\n<h3>1957 और लैटिन लिपि</h3><p>1957 में चीन ने नवनिर्धारित मानक ज़ुआंग भाषा के लिए एक ध्वन्यात्मक लिपि लागू की। आरंभिक वर्णमाला में लैटिन के साथ सिरिलिक और अंतरराष्ट्रीय ध्वन्यात्मक वर्णमाला से लिए गए अक्षर मिले हुए थे, जिनमें सुर के पाँच अक्षर (ƨ ɜ ч ƽ ƅ) भी थे, जो 2 से 6 तक के अंकों जैसे दिखते हैं; 1982 के संशोधन में इनके स्थान पर सामान्य लैटिन अक्षर आ गए और अब सुर शब्द के अंत में आने वाले एक अक्षर — <em>z, j, x, q, h</em> — से लिखा जाता है। यही मानक ज़ुआंग की वर्तनी <strong>Sawcuengh</strong> 壮文 है; <em>Vahcuengh</em> लिपि का नहीं, बल्कि स्वयं भाषा का ज़ुआंग नाम है। आज Sawcuengh आधिकारिक मानक है, फिर भी साउनदिप टिका हुआ है। गाँवों के अनुष्ठान-विशेषज्ञ आज भी हाथ से पाठ नक़ल करते हैं, और लोग इसे गीतों के बोल और निजी नोट्स के लिए भी बरतते हैं; दो बोली-क्षेत्रों के एक सर्वेक्षण में एक-तिहाई से कुछ ज़्यादा उत्तरदाताओं ने कहा कि वे इसे समझ सकते हैं। 2017 से यूनिकोड हज़ारों साउनदिप अक्षर जोड़ चुका है (CJK विस्तार F, G, H और J), इसलिए अब यह पुरानी लिपि टाइप की जा सकती है।</p>","bai-language-script":"<h3>बाई लोग कौन हैं?</h3><p><strong>बाई लोग (白族)</strong> चीन के दक्षिण-पश्चिम युन्नान प्रांत के दाली (大理) के आसपास 2020 की जनगणना के अनुसार 21 लाख की जनसंख्या वाला जातीय समूह है। सभी बाई, बाई भाषा नहीं बोलते: एथनोलॉग का 2003 का अनुमान लगभग 13 लाख वक्ताओं का था। इनका राज्य <strong>नान्झाओ</strong> (738–902) और उसका उत्तराधिकारी <strong>दाली साम्राज्य</strong> (937–1253) प्रमुख क्षेत्रीय शक्तियाँ थीं जिनका तांग चीन, तिब्बत और दक्षिण-पूर्व एशियाई सभ्यताओं से गहरा लेन-देन रहा। इसी राजनीतिक इतिहास से समझ आता है कि बाई भाषा ने चीनी से इतना कुछ क्यों लिया और उससे इतनी गहराई से क्यों ढली।</p><h3>वर्गीकरण की पहेली</h3><ul><li><strong>सिनिटिक शाखा</strong>: कुछ विद्वान (ख़ासकर सेर्गेई स्तारोस्तिन और झेंगझांग शांगफांग) मानते हैं कि सबसे पुरानी चीनी परत एक नगण्य अवशेष को छोड़कर बाई की सारी शब्दावली समझा देती है, इसलिए बाई ख़ुद चीनी से बहुत पहले निकली एक शाखा है; स्तारोस्तिन यह अलगाव लगभग दूसरी सदी ई.पू. में, पश्चिमी हान काल में रखते हैं, यानी आधुनिक सिनिटिक किस्मों के बनने से बहुत पहले।</li><li><strong>तिब्बती-बर्मी</strong>: दूसरे, जैसे ली और सागार्ट, उधार शब्दों के नीचे एक असली ग़ैर-चीनी मूल पाते हैं, जिसे उन्होंने पहले लोलोइश भाषाओं (यी की रिश्तेदार) से जोड़ा और बाद में अधिक सामान्य रूप से चीनी-तिब्बती के ग़ैर-चीनी पक्ष से।</li><li><strong>स्वतंत्र शाखा</strong>: जेम्स मैटिसॉफ़ ने इसे \"बाई को चीनी-तिब्बती की एक स्वतंत्र शाखा मानना ज़्यादा सुरक्षित\" समझा, शायद लोलोइश के क़रीब, और चीनी के साथ सदियों के संपर्क से गहराई तक बदली हुई।</li></ul><p>मुश्किल यह है कि बाई अलग-अलग दौर के चीनी शब्दों से भरी है, जो कोई दो हज़ार वर्षों में फैले हैं। सबसे पुरानी परत, लगभग 250 बुनियादी शब्द, मध्यकालीन चीनी से भी पुरानी है: यह उन तुकांतों को अलग रखती है जिन्हें ख़ुद चीनी चौथी सदी ईस्वी तक मिला चुकी थी। बाद की परतें आधुनिक दक्षिण-पश्चिमी मंदारिन तक आती हैं। जितना गहरा खोदें, उतना ही मुश्किल हो जाता है यह बताना कि कोई शब्द बहुत पुराना उधार है या बाई और चीनी दोनों को विरासत में मिला।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"bfs\">📍 मानचित्र पर बाई भाषा देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"25.6\" data-lng=\"100.3\" data-zoom=\"7\">🗺 ताली, युन्नान की ओर जाएँ</button></div><h3>बाई लिपि (白文) कैसे काम करती है</h3><p>ज़ुआंग की तरह, बाई लोगों ने भी हान अक्षरों से अपनी भाषा लिखने की प्रणाली <strong>बाईवेन</strong> विकसित की। एक ही हान अक्षर को चीनी और बाई दोनों तरीकों से पढ़ा जा सकता है। पर हर अक्षर साफ़ नहीं बँटता: 'घोड़ा' के लिए बाई का अपना शब्द ही <em>ma˧˧</em> (आद्य बाई *<em>mæ</em>) है, जो एक पुराना सिनिटिक रूप है, इसलिए 馬 चीनी की तरह पढ़ें या बाई की तरह, लगभग एक जैसा सुनाई देता है। दोनों प्रणालियाँ वहाँ अलग होती हैं जहाँ परतें अलग होती हैं: 目 बाई में चीनी परत का पाठ <em>mu˨˨</em> रखता है, जबकि 'आँख' के लिए रोज़मर्रा का बाई शब्द <em>ŋui˨˨</em> है। बाई व्याकरण के अपने निपात, पक्ष-चिह्न और स्वराघात वाले प्रत्यय ध्वनि-उधार से लिखे जाते हैं, कभी-कभी दुर्लभ हान अक्षरों को केवल उनके स्थानीय उच्चारण के लिए बरतकर।</p>\n\n<h3>लैटिन वर्णमाला: तीन कोशिशें</h3><p>बाई के तीन मुख्य बोली-समूह हैं: च्येनछ्वान (मध्य), ताली (दक्षिणी) और पीच्यांग (उत्तरी)। कहा जाता है कि पहले दो के वक्ता एक महीने साथ रहने के बाद एक-दूसरे को समझने लगते हैं। उत्तरी रूप, जिन्हें लगभग 15,000 लोग बोलते हैं, कहीं ज़्यादा अलग हैं, और ISO 639-3 तो चार बाई रूपों को अपना-अपना कोड देता है। इन सबको एक वर्णमाला में लिखना कठिन साबित हुआ है। ताली के पास श्याग्वान की बोली पर आधारित 1958 में बनी एक <strong>लैटिन वर्णमाला</strong> बहुत कम बरती गई। च्येनछ्वान पर आधारित 1982 का संस्करण वहाँ चल निकला पर ताली में ठुकरा दिया गया, इसलिए 1993 के संशोधन ने हर क्षेत्र को अपना अलग रूप दे दिया। यह स्वराघात को विशेषकों या अंकों से नहीं, बल्कि हर शब्दांश के अंत में एक अतिरिक्त अक्षर से चिह्नित करता है — वही तरकीब जो ह्मोंग वर्णमाला RPA बरतती है। इस बीच पुरानी अक्षर-आधारित बाईवेन धार्मिक ग्रंथों (विशेषकर बेनजू 本主 देव-पूजा), शास्त्रीय काव्य तथा ताली मैदान के आसपास के शिलालेखों में बचा हुआ है — कुछ तो नानझाओ राज्य के काल के हैं।</p>\n\n<h3>चीनाक्षर-मंडल के संपर्क का दर्पण</h3><p>बाई में वह ढर्रा साफ़ दिखता है जो पूरे चीनाक्षर-मंडल में मिलता है: शास्त्रीय चीनी से सदियों के लगातार साहित्यिक संपर्क ने ऐसी लेखन-परंपराएँ पैदा कीं जो चीनी की ऋणी भी हैं और उससे अलग भी। जहाँ ज़ुआंग ने अपनी ध्वनि-व्यवस्था के लिए नए चीनाक्षर गढ़े, और वियतनामी <em>चु नोम</em> ने एक ऑस्ट्रो-एशियाई भाषा के लिए वही किया, वहीं बाई ने दोहरे पाठ की परिपाटी अपनाई — एक चिह्न, दो दुनियाएँ।</p>","wenzhou-devils-tongue":"<h3>परस्पर बोधगम्यता</h3><p>वेनझोउ वू और मंदारिन बोलने वाले एक-दूसरे को कम ही समझ पाते हैं, और यह शंघाई और सूझोउ जैसी उत्तरी वू बोलियों से भी काफ़ी अलग है। एक मशहूर कहावत है: <em>天不怕，地不怕，就怕溫州人說溫州話</em> — \"आसमान से नहीं डरते, ज़मीन से नहीं डरते, बस वेनझोउ वाले को वेनझोउ बोली बोलते सुनकर डरते हैं।\" एक रूप में आख़िरी शब्द हो जाते हैं <em>講鬼話</em> (jiǎng guǐhuà), \"भूतिया बोली बोलना\"; और <strong>鬼話</strong> (guǐhuà) का अर्थ \"झूठ, बकवास\" भी है, इसलिए यह उपनाम कभी तारीफ़ नहीं था। (इंसाफ़ की बात यह है कि चीनी भाषी यही कहावत उन दूसरी बोलियों पर भी चिपका देते हैं जो उन्हें समझ नहीं आतीं।)</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"wuu_wz\">📍 मानचित्र पर वेनझोउ वू देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"28.0\" data-lng=\"120.7\" data-zoom=\"7\">🗺 वेनझोउ जाएं</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🔢 मानचित्र पर 人 देखें</button></div><h3>बिना कोड का कोड: जिसका कोई प्रमाण नहीं</h3><p>वेनझोउ भाषा को लेकर सबसे अधिक दोहराया जाने वाला किस्सा यह है कि चीन-जापान युद्ध के दौरान चीनी कमांडरों ने वेनझोउ के सैनिकों को रेडियो पर बिठाया, और मानक चीनी में पारंगत तथा प्रमुख बोलियों से परिचित जापानी क्रिप्टविश्लेषकों के कुछ पल्ले नहीं पड़ा। अमेरिकी मरीन के नवाहो कोड टॉकर्स अपनी भाषा पर एक कृत्रिम कूट चढ़ाते थे; वेनझोउ भाषियों को किसी कूट की ज़रूरत ही न पड़ती, क्योंकि भाषा ख़ुद ही रहस्य होती। लेकिन आज तक इस किस्से की पुष्टि करने वाला कोई ठोस दस्तावेज़ सामने नहीं आया। चीनविद् विक्टर मेयर ने 2015 में Language Log पर इस दावे की पड़ताल करते हुए लिखा कि भाषा की ज़बरदस्त ख्याति के बावजूद उन्होंने अब तक \"युद्ध में गुप्तचर उद्देश्यों के लिए वेनझोउ भाषा के इस्तेमाल का कोई ठोस दस्तावेज़\" नहीं देखा, और एक व्यावहारिक अड़चन भी गिनाई: वेनझोउ भाषा लिखित भाषा नहीं है, और मिशनरियों का रोमनीकरण आम बोलने वालों के बीच कभी चला ही नहीं। संदर्भ-ग्रंथ इस किस्से को केवल \"कहा जाता है\" कहकर दर्ज करते हैं। वियतनाम के साथ 1979 के सीमा-युद्ध के बारे में ऐसा ही एक दावा शायद असल में वेनझोउ भाषा के बारे में नहीं, बल्कि 蛮话 (मानहुआ) के बारे में है — त्सांगनान काउंटी में छ्येनकू के आसपास बोली जाने वाली एक अलग बोली। यह क़िस्सा कोई तथ्य दर्ज नहीं करता; दर्ज करता है तो बस इस भाषा के दुर्बोध होने की शोहरत।</p><h3>सघोष व्यंजन: मध्यकाल की बची हुई विरासत</h3><p>सुई और तांग राजवंशों (लगभग 600–900 ई.) की, छंद-कोशों में दर्ज चीनी — <strong>मध्यकालीन चीनी (中古漢語)</strong> — में /b/, /d/, /g/ आदि पूर्ण <strong>सघोष अवरोधी व्यंजन</strong> थे। मंदारिन, कैंटोनीज़ और होक्किएन — तीनों ने सदियों के दौरान यह भेद खो दिया और उसकी भरपाई स्वराघातों के विभाजन से की। वू शाखा ने ऐसा नहीं किया: मध्यकालीन चीनी के सघोष व्यंजनों को बनाए रखना ही वू को वू ठहराने वाली शास्त्रीय कसौटी है, और शंघाई तथा सूझोउ की बोलियाँ भी इन्हें उतनी ही मज़बूती से सँजोए हुए हैं जितनी वेनझोउ। वेनझोउ को शंघाई की बोली से भी अधिक दुर्बोध बनाने वाली बात ये सघोष व्यंजन नहीं, बल्कि उनके ऊपर बैठी दो और चीज़ें हैं — आठ स्वराघातों की वह प्रणाली, जो मध्यकालीन चीनी के यिन-यांग विभाजन को दर्शाती है और जिसके आरोह-अवरोह असामान्य हैं, तथा उत्तरी वू से बहुत दूर जा चुकी शब्दावली। वेनझोउ का वक्ता 爬 /bo˧˩/ 'चढ़ना' को 怕 /pʰo˦˨/ 'डरना' और 巴 /po˧˧/, दोनों से उसके सघोष /b/ के बल पर अलग करता है — यह भेद मंदारिन में नहीं है। सघोषता अक्षर को निचले (यांग) स्वराघात-स्तर में भी खींच लेती है, इसीलिए ये तीनों कभी टकराते नहीं।</p><h3>स्वराघात से \"यह\" कहना</h3><p>वेनझोउ व्याकरण में भी अलग पड़ती है, और उसकी सबसे चौंकाने वाली तरकीब है एक ऐसा संकेतवाचक जो सिर्फ़ स्वराघात से बनता है। \"यह\" कहने के लिए वक्ता परिमाण-शब्द (classifier) लेता है और उसे झुकते-उठते <em>रू</em> स्वराघात पर ले जाता है, रास्ते में सघोष आद्य व्यंजन को अघोष करते हुए: /pa˧/ 'समूह' बन जाता है /pa˧˨˧/ 'यह समूह', और /le˧˩/ 'कुछ (लोग)' बन जाता है /l̥e˧˨˧/ 'ये लोग'। \"यह\" के लिए अलग शब्द की ज़रूरत ही नहीं। कुछ बोलीविज्ञानी इसमें प्राचीन ओउ युए (甌越) जनों की भाषा के निशान खोजते हैं, जो चीनी-भाषियों के आने से पहले इस तट पर रहते थे, पर अधःस्तर के ऐसे दावे साबित करना कठिन ही है।</p>\n\n<h3>वेनझोउ इतना भिन्न क्यों है</h3><p>भौगोलिक अलगाव मुख्य कारण है। वेनझोउ झेजियांग के दक्षिणी छोर पर येनतांग पर्वत और समुद्र से घिरा है। ज़मीन के रास्ते सफ़र हैरानी की हद तक लंबे समय तक दुश्वार रहा: वेनझोउ तक पहली रेल लाइन, जिनहुआ–वेनझोउ लाइन, जून 1998 में जाकर खुली। अपने इतिहास के ज़्यादातर हिस्से में यह शहर समुद्र के रास्ते व्यापार करता रहा, और यांग्त्सी डेल्टा के हृदय-प्रदेश के बजाय फ़ुजियान के बंदरगाहों से ज़्यादा आसानी से जुड़ा रहा। अलगाव ने दोनों तरफ़ असर किया। इसने वेनझोउ को वे पुराने भेद बचाए रखने दिए जो उत्तरी वू खो चुकी थी, और साथ ही स्थानीय बोली को अपनी राह चलने की छूट भी दी; शहर का अपना नाम 溫州 लगभग /ʔjy tɕɤu/ जैसा निकलता है।</p>","hakka-diaspora-language":"<h3>अतिथि लोग</h3><p><strong>客家</strong> (हक्का; शाब्दिक अर्थ \"अतिथि परिवार\") के पीछे एक प्रसिद्ध कहानी है। 1933 में इतिहासकार लो शियांग-लिन ने जो क्लासिक वृत्तांत रखा, उसके अनुसार लगभग एक हज़ार वर्षों में युद्ध, अकाल और राजवंशों के पतन से भागे हान चीनी शरणार्थियों की लहरें मध्य मैदान से दक्षिण की ओर बढ़ीं और उस पहाड़ी इलाक़े में देर से आए बाशिंदों की तरह बसीं जहाँ जियांग्शी, फ़ुजियान और ग्वांगडोंग मिलते हैं। सबसे अच्छी खेती की ज़मीन पहले ही ली जा चुकी थी, और पुराने बसे \"मेज़बान\" (主) घरानों ने उन्हें \"अतिथि\" (客) कहना शुरू कर दिया। आधुनिक विद्वान मानते हैं कि असली कहानी ज़्यादा मिली-जुली है: हक्का भाषा सबसे ज़्यादा पड़ोसी जियांग्शी में बोली जाने वाली गान के क़रीब है, और आज के हक्का लोगों के पूर्वजों में शे जैसे दक्षिणी लोग भी हैं, जिनसे नवागंतुकों ने शादियाँ कीं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"hak_cn\">📍 हक्का (मुख्यभूमि) मानचित्र पर</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"hak_tw\">📍 हक्का (ताइवान) मानचित्र पर</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"24.5\" data-lng=\"116.1\" data-zoom=\"6\">🗺 मेईझोउ जाएं</button></div><h3>डायस्पोरा: मॉरिशस से हवाई तक</h3><p>17वीं शताब्दी से हक्का लोग \"नान्यांग\" (南洋) उत्प्रवास की लहर में दक्षिण-पूर्व एशिया गए, और फिर हिंद महासागर में मॉरिशस, दक्षिण अमेरिका के अटलांटिक तट पर सूरीनाम, जमैका और हवाई तक फैल गए। सूरीनाम में पहले चीनी बाशिंदे मेईझोउ (梅州) के हृदय-प्रदेश से नहीं, बल्कि पर्ल नदी डेल्टा के पूरब के फ़ुईतुंगोन क्षेत्र से आए थे — यह नाम उसकी तीन काउंटियों से मिलकर बना है: हुईयांग, दोंगगुआन और बाओआन। उनके वंशजों की हक्का में 19वीं सदी के फ़ुईतुंगोन का वही रंग बचा है, डच और स्रानान टोंगो के उधार शब्दों के साथ।</p><h3>भाषाई विशेषताएं</h3><p>हक्का भाषा मध्यकालीन चीनी (中古漢語) के प्रवेश-स्वर (入聲) के तीनों अंत्य आज भी रखती है: /-p/, /-t/ और /-k/। \"मैं\" के लिए शब्द है <strong>𠊎</strong> /ŋai/, जो केवल हक्का के लिए प्रयुक्त एक अक्षर से लिखा जाता है और अकेला यही शब्द किसी वक्ता को पहचानने के लिए काफी है। ज़्यादातर विद्वान इसे वही प्राचीन सर्वनाम मानते हैं जो मंदारिन का <em>wǒ</em> और कैंटोनीज़ का <em>ngóh</em> (我) है; हक्का में तो उस अक्षर का एक साहित्यिक उच्चारण <em>ngo</em> भी बचा है। रोज़मर्रा वाले रूप को अलग करता है उसका <em>-ai</em>, जहाँ दूसरी भाषाओं में पश्च स्वर आता है। ताइवान में दुकानों के बोर्ड शान से ऐलान करते हैं 𠊎講客 <em>Ngài kóng Hak</em>, \"मैं हक्का बोलता हूँ\"। सबसे जाना-माना चर्च रोमनीकरण, <strong>PFS</strong> (Pha̍k-fa-sṳ, 白話字), 19वीं सदी के बाज़ल मिशन के काम से निकला और आज भी हक्का ईसाई समुदायों में चलता है; ताइवान के स्कूल और सरकार एक अलग आधिकारिक हक्का पिनयिन बरतते हैं।</p><h3>ताइवान का महान हक्का आंदोलन</h3><p>ताइवान में लगभग 46 लाख लोग स्वयं को हक्का मानते हैं, पर वास्तव में यह भाषा बोल सकने वालों की संख्या कहीं कम है — अनुमान लगभग 12 लाख से 24 लाख के बीच हैं। जापानी उपनिवेशवाद और कुओमिन्तांग की मंदारिन-प्रसार नीतियों के तहत दशकों के दमन के बाद, 1980 के दशक से हक्का का ज़मीनी पुनर्जागरण हुआ। उसकी प्रतीकात्मक शुरुआत 28 दिसंबर 1988 को हुई, जब हज़ारों हक्का सन यात-सेन की तस्वीरें लेकर <strong>還我母語運動</strong> (\"हमें हमारी मातृभाषा लौटाओ\" आंदोलन) में ताइपे की सड़कों पर उतरे और हक्का प्रसारण व शिक्षा की माँग की। इसी मुहिम से 2001 में हक्का मामलों की परिषद (आज की 客家委員會) बनी, जो ख़ुद को हक्का मामलों के लिए दुनिया की एकमात्र राष्ट्रीय स्तर की सरकारी संस्था बताती है। हक्का टेलीविज़न अब 24 घंटे प्रसारण करता है।</p><h3>हक्का मूल के प्रसिद्ध व्यक्ति</h3><ul><li><strong>孫中山</strong> (सन यात-सेन) — चीनी गणराज्य के संस्थापक (उनका हक्का वंश परंपरा से माना जाता है, पर इस पर बहस है)</li><li><strong>鄧小平</strong> (देंग शियाओपिंग) — चीन के सुधार और खुलेपन के वास्तुकार, सिचुआन के एक हक्का कुल से</li><li><strong>李光耀</strong> (ली कुआन यू) — सिंगापुर के पहले प्रधानमंत्री</li><li><strong>洪秀全</strong> (होंग शियूक्वान) — ताइपिंग स्वर्गीय साम्राज्य के नेता</li></ul><p>लेखकों ने अक्सर क्रांतिकारी आंदोलनों में इस प्रमुखता को हक्का लोगों की हाशिये पर खड़े \"अतिथि\" समुदाय की स्थिति से जोड़ा है — मज़बूत आपसी एकजुटता और शिक्षा के प्रति गहरा सम्मान — हालाँकि ऐसी व्याख्याओं को परखना मुश्किल है। एक मामले में यह धागा सचमुच दिखता है: सन यात-सेन ने कहा था कि बचपन में वे एक बूढ़े ताइपिंग सैनिक के क़िस्से सुना करते थे, और उन्होंने ऐलान किया था कि वे दूसरे होंग शियूक्वान बनेंगे।</p>","sino-vietnamese-han-viet":"<h3>तांग काल की एक उधार-परत</h3><p>7वीं से 10वीं शताब्दी तक जब तांग अधिकारी अन्नाम — आज के उत्तरी वियतनाम — पर शासन करते थे, वियतनामी ने चीनी शब्दों का बहुत बड़ा भंडार अपना लिया। इतिहास के लिहाज़ से इस परत की क़ीमत उन ध्वनि-भेदों में है जो इसमें बचे हैं। भाषाविद् इस स्तर को <strong>हान-वियत</strong> (漢越, चीनी-वियतनामी) कहते हैं।</p><p>वियतनामी शब्दभंडार में चीनी मूल के हिस्से के अनुमान बहुत अलग-अलग हैं — <strong>लगभग एक-तिहाई से लेकर 70% तक</strong>, रोज़मर्रा की बोली में कम और तकनीकी लेखन में कहीं ज़्यादा — बहुत कुछ अंग्रेज़ी की उस लैटिन और फ़्रांसीसी परत की तरह जो औपचारिक सिरे की ओर घनी होती जाती है। पर अंग्रेज़ी ने अपने फ़्रांसीसी और लैटिन शब्द टुकड़ों-टुकड़ों में लिए, जबकि वियतनामी विद्वानों ने एक पूरी पठन-प्रणाली ही अपना ली: <em>चिएयुन</em> (切韻) जैसे चीनी छंद-कोशों के आधार पर उन्होंने हर अक्षर को एक नियमित वियतनामी उच्चारण दिया, और ऐसे लगभग 3,000 रूपिम भाषा में उतर आए। नतीजा मध्यकालीन चीनी ध्वनि-व्यवस्था का क़रीबी प्रतिबिंब है। इसके नीचे लगभग 400 शब्दों की एक पुरानी परत भी है, जो 111 ई.पू. की हान विजय के बाद एक-एक करके उधार ली गई और अब पूरी तरह देसी लगती है: <em>bạc</em> \"चाँदी\" उस शब्द के एक शुरुआती उधार से आता है जिसे 白 \"सफ़ेद\" लिखा जाता है, और जिसे बाद की पठन-प्रणाली <em>bạch</em> पढ़ती है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='食'>🔡 食 के पाठ दिखाएँ</button><button type='button' class='trivia-action' data-action='focus' data-code='vi_ohan'>📍 पुरानी हान-नोम परत</button></div><h3>अंत्य स्पर्श ध्वनियों का संरक्षण</h3><p>मध्यकालीन चीनी (中古漢語, 7वीं-10वीं शताब्दी) में चार स्वराघात-श्रेणियाँ थीं, और महत्वपूर्ण बात यह कि उसके <em>प्रवेशी</em> स्वराघात (入聲) अनिर्मुक्त स्पर्श ध्वनियों पर समाप्त होते थे: <strong>-p, -t, -k</strong>। आधुनिक मंदारिन ने तीनों खो दीं — 國 <em>guó</em> कभी -k पर समाप्त होता था, 學 <em>xué</em> -k पर, 食 <em>shí</em> -k पर।</p><p>चीनी-वियतनामी पाठों में ये अंत्य ध्वनियाँ बची हैं, हालाँकि वर्णमाला अंत्य <em>-k</em> को <em>-c</em> (या <em>-ch</em>) लिखती है:</p><ul><li>學 → <strong>học</strong> (-k)</li><li>國 → <strong>quốc</strong> (-k)</li><li>食 → <strong>thực</strong> (-k)</li><li>十 → <strong>thập</strong> (-p)</li><li>八 → <strong>bát</strong> (-t)</li></ul><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='食'>🔡 食 के पाठ मिलाएँ</button><button type='button' class='trivia-action' data-action='setchar' data-char='山'>🔡 山 के पाठ मिलाएँ</button></div><h3>चार से आठ श्रेणियाँ</h3><p>मध्यकालीन चीनी में चार स्वराघात थे: 平 (सम), 上 (आरोही), 去 (प्रस्थायी) और 入 (प्रवेशी)। आगे चलकर प्रत्येक इस आधार पर दो में बँटा कि आद्य व्यंजन घोष था या नहीं — इसे स्वराघात-विभाजन (tone split) कहते हैं — और इस प्रकार <strong>आठ स्वराघात-श्रेणियाँ</strong> (四聲八調) बनीं, जिनमें चीनी-वियतनामी पाठ आज भी बैठते हैं। वियतनामी उन्हें केवल <strong>छह स्वराघातों</strong> से लिखती है, क्योंकि दोनों 入 श्रेणियाँ दोनों 去 श्रेणियों में मिल गईं: 平 से ngang और huyền, 上 से hỏi और ngã (हालाँकि पुराने घोष स्पर्श, स्पर्श-संघर्षी या संघर्षी से शुरू होने वाले कई अक्षर इसके बजाय nặng में चले गए), 去 से sắc और nặng, तथा -p, -t, -c, -ch पर समाप्त होने वाले पुराने 入 अक्षर भी sắc और nặng लेते हैं। इस तरह क्वोक न्गू के छह चिह्न पुनर्निर्मित मध्यकालीन चीनी ग्रिड पर ठीक-ठीक बैठ जाते हैं। आधुनिक मंदारिन ने उसी ग्रिड को चार स्वराघातों में समेट दिया और बहुत बड़ी मात्रा में स्वराघात-सूचना खो दी।</p><h3>बीजिंग ने वह क्यों खोया जो हनोई ने बचाए रखा</h3><p>इस अंतर के पीछे भूगोल और राजनीति का इतिहास है। मंदारिन (普通話) मुख्यतः उत्तरी बोलियों से उतरी है, जो मानक तय होने से बहुत पहले सदियों के आंतरिक पुनर्गठन से गुज़र चुकी थीं — अंत्य स्पर्श ध्वनियों का लोप, स्वराघातों का विलय। वियतनाम ने 938 में स्वतंत्रता पा ली, पर शासन और विद्वत्ता के लिए 20वीं सदी की शुरुआत तक साहित्यिक चीनी ही बरतता रहा — और पूरे समय उसे अपने तांग-आधारित ढंग से पढ़ता रहा। ये पाठ जमे हुए नहीं थे: वियतनामी ध्वनि-परिवर्तन इन पर भी चले। लेकिन ये बदलाव चीन से स्वतंत्र रूप से हुए, इसलिए जिन क्षरणों ने उत्तरी चीनी का नक्शा बदला, वे इन तक कभी नहीं पहुँचे।</p><p>इसीलिए चीनी-वियतनामी पाठ मध्यकालीन चीनी के पुनर्निर्माण के लिए तुलनात्मक साक्ष्य का एक स्रोत हैं। कैंटोनीज़, होक्किएन और चीनी-कोरियाई पाठों के साथ मिलकर वे उन भेदों को सुरक्षित रखते हैं जिन्हें अकेली मंदारिन नहीं दिखाती।</p><blockquote>文化 <em>văn hóa</em> (vi) — 文化 <em>wénhuà</em> (zh): वही अक्षर, और यहाँ दोनों सहमत हैं — वियतनामी <em>v-</em> और मंदारिन <em>w-</em> दोनों मध्यकालीन चीनी 微 आद्य ध्वनि (Baxter <em>mjun</em>) के नियमित प्रतिफल हैं, जिसका मूल *m- इसके बदले कैंटोनीज़ <em>man4</em> और होक्किएन <em>bûn</em> में बचा है।</blockquote><p>यानी <em>quốc</em>, <em>học</em> और <em>văn</em> जैसे आम शब्दों में एक ऐसी उधार-परत बची है जो आधुनिक मानक चीनी से कई सदियाँ पहले जम चुकी थी।</p>","sino-korean-versus-sino-japanese":"<h3>हान अक्षर जगत का रोज़ेटा पत्थर</h3><p>हर देश जिसने हान अक्षर अपनाए, उसने चीनी उच्चारण भी अपनाया — लेकिन अलग-अलग युगों और बोलियों से। परिणाम चार आधुनिक लेखन प्रणालियों में छिपा एक भाषाई रोज़ेटा पत्थर है। जापानी, कोरियाई और वियतनामी में उधार ली गई इन पठन-परतों को सामूहिक रूप से <strong>Sino-Xenic</strong> कहा जाता है (यह शब्द सैमुअल ई. मार्टिन ने 1953 में गढ़ा था)। उत्तरी चीनी बोलियों से विकसित हुई आधुनिक मानक भाषा, मंदारिन, के साथ रखने पर ये एक ही चीनी स्रोत के चार सजातीय प्रतिबिंब बन जाते हैं, जो उधार लेने के बाद एक-दूसरे से अलग हो गए।</p><h3>अक्षर-दर-अक्षर तुलना</h3><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='山'>🔡 山 (पर्वत) की तुलना करें</button><button type='button' class='trivia-action' data-action='setchar' data-char='水'>🔡 水 (जल) की तुलना करें</button></div><p><strong>山</strong> (पर्वत) को लीजिए। मध्यकालीन चीनी में इसका पुनर्निर्माण *ʂan के रूप में होता है। आज:</p><ul><li>मंदारिन: <strong>shān</strong> (स्वराघात सुरक्षित, अंत्य अनुनासिक सुरक्षित)</li><li>कोरियाई (漢字音): <strong>san</strong> (अंत्य अनुनासिक सुरक्षित, कोई स्वराघात नहीं)</li><li>जापानी (漢音 कान-ऑन): <strong>san</strong> (कोरियाई वाली ही परत)</li><li>वियतनामी: <strong>sơn</strong> (स्वर बदला, अंत्य अनुनासिक सुरक्षित)</li></ul><p>अब <strong>國</strong> (देश), मध्यकालीन चीनी *kwok:</p><ul><li>मंदारिन: <strong>guó</strong> — अंत्य -k लुप्त, स्वराघात बदला</li><li>कोरियाई: <strong>guk</strong> — अंत्य -k सुरक्षित</li><li>जापानी (漢音): <strong>koku</strong> — -k, -ku के रूप में (स्वर जोड़कर)</li><li>वियतनामी: <strong>quốc</strong> — अंत्य -k पूरी तरह सुरक्षित</li></ul><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='食'>🔡 食 (खाना) की तुलना करें</button></div><h3>अंत्य स्पर्श व्यंजनों का श्रेणीक्रम</h3><p>यही ढर्रा हर उस अक्षर में दिखता है जिसका अंत मध्यकालीन चीनी के प्रवेशी स्वराघात (入聲) से आता है। कौन कितना बचाता है, इसका क्रम हर बार एक-सा रहता है:</p><ol><li><strong>कैंटोनीज़/होक्किएन</strong>: -p, -t, -k को अविमुक्त स्पर्श व्यंजन के रूप में ज्यों का त्यों रखते हैं (सबसे पूर्ण रूप से कैंटोनीज़ में; होक्किएन में एक बोलचाल की कंठ्य-स्पर्श परत भी है)</li><li><strong>वियतनामी</strong>: तीनों को बनाए रखती है (-p, -t, -c/-ch)</li><li><strong>कोरियाई</strong>: -p और -k रखती है, पर मध्यकालीन चीनी -t यहाँ -l बनकर आता है (一 <em>il</em>, 發 <em>bal</em>)</li><li><strong>जापानी</strong>: पीछे एक स्वर जोड़ देती है: -t बनता है -tsu या -chi, -k बनता है -ku या -ki, और पुराना -pu ज़्यादातर घिसकर दीर्घ स्वर रह गया है (十 <em>jū</em>, 法 <em>hō</em>)</li><li><strong>मंदारिन</strong>: तीनों को मिटा देती है, केवल स्वराघात में निशान बचते हैं</li></ol><p>學 (अध्ययन; बैक्सटर की लिपि में मध्यकालीन चीनी <em>haewk</em>) के लिए: कोरियाई <em>hak</em>, जापानी <em>gaku</em>, वियतनामी <em>học</em>, मंदारिन <em>xué</em>। चार में से तीन में -k जीवित है।</p><h3>जापानी में कई पाठ क्यों हैं</h3><p>जापान ने चीनी उच्चारण कम से कम तीन अलग लहरों में उधार लिया: <strong>呉音 गो-ऑन</strong> (वू-आधारित, 5वीं–6ठी सदी), <strong>漢音 कान-ऑन</strong> (थांग दरबार का मानक, 8वीं–9वीं सदी), और <strong>唐音 तो-ऑन</strong> (सुंग–मिंग काल)। 行 के लिए:</p><ul><li>गो-ऑन: <em>gyō</em></li><li>कान-ऑन: <em>kō</em></li><li>तो-ऑन: <em>an</em> (दक्षिणी बोलियों से)</li></ul><p>इसके विपरीत कोरियाई को उच्चारण अपेक्षाकृत एक ही स्रोत से मिला: चीनी-कोरियाई (漢字音) की मुख्य परत को आमतौर पर थांग चीन के छांगआन मानक तक ले जाया जाता है, जिसे सिल्ला के छात्र और दूत 8वीं और 9वीं सदी में थांग राजधानी से घर लाए। एक ही मुख्य स्रोत पर टिके होने से चीनी-कोरियाई, जापानी परतों की तुलना में, अपने भीतर कहीं ज़्यादा एकरूप है — और संयोग से वह लगभग वही थांग मानक है जिससे <em>कान-ऑन</em> आया।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='focus' data-code='ko'>📍 मानचित्र पर कोरियाई देखें</button><button type='button' class='trivia-action' data-action='focus' data-code='ja'>📍 मानचित्र पर जापानी देखें</button></div><h3>स्वराघात संरक्षण की सीढ़ी</h3><p>व्यंजनों की तरह स्वराघात के बचे रहने का भी एक साफ़ क्रम है। मध्यकालीन चीनी में 4 स्वराघात श्रेणियाँ थीं, जो कुछ भाषाओं में 8 में बँट गईं:</p><ul><li>कैंटोनीज़: <strong>6–9 स्वराघात</strong> (सर्वोत्तम संरक्षण)</li><li>वियतनामी: <strong>6 स्वराघात</strong> — या 8, अगर -p, -t, -c पर ख़त्म होने वाले अक्षरों को अलग गिनें, और तब ये मध्यकालीन चीनी की 8 श्रेणियों से बड़ी सफ़ाई से मेल खाते हैं (उत्कृष्ट)</li><li>चीनी-कोरियाई: <strong>ऐतिहासिक रूप से 3 सुर-बलाघात</strong>, सोल की बोली में अब लगभग समतल (अच्छा ऐतिहासिक अभिलेख)</li><li>जापानी ओन-पाठ: <strong>कोई स्वराघात नहीं</strong>। कभी जापानी पाठक चीनी स्वराघातों को अक्षरों के कोनों पर छोटे-छोटे बिंदुओं (声点, <em>shōten</em>) से चिह्नित करते थे; बाद में जब ये बिंदु काना पर लगाए जाने लगे, तो घोषत्व दिखाने वाला दोहरा बिंदु ही आज के दाकुतेन ゛ का पूर्वज बना</li><li>मंदारिन: <strong>4 स्वराघात</strong>, भारी विलयों के साथ — सबसे कमज़ोर संरक्षण</li></ul><p>यही सीढ़ी तुलना को उपयोगी बनाती है: कैंटोनीज़ और वियतनामी मिलकर वह अधिकांश बचाए रखते हैं जो मध्यकालीन चीनी अलग करती थी, और एक अक्षर को चारों प्रणालियों में पढ़ने से मूल रूप का उतना हिस्सा वापस मिल जाता है जितना उनमें से कोई अकेली प्रणाली नहीं रखती।</p>","simplified-chinese-1956":"<h3>कूँची के पीछे की राजनीति</h3><p>1956 में, पीपुल्स रिपब्लिक ऑफ चाइना ने पहली <em>हानज़ी सरलीकरण योजना</em> प्रकाशित की, जिसने 515 वर्णों की रेखाओं की संख्या घटाई और 54 सरलीकृत घटकों (偏旁) को मानकीकृत किया। हालात कठिन थे। 1949 में जब जनवादी गणराज्य की स्थापना हुई, तब लगभग 80% आबादी पढ़ नहीं सकती थी, और गाँवों में यह आँकड़ा 95% से ऊपर था। उम्मीद थी कि सरल अक्षर लोगों को जल्दी पढ़ना-लिखना सिखा देंगे।</p><p>सरलीकृत रूप शून्य से नहीं गढ़े गए थे। बहुत-से रूप उस घसीट लिखावट और उन लोकप्रिय संक्षिप्त रूपों पर टिके थे जिन्हें लिपिक और व्यापारी सदियों से बरतते आए थे। और यह विचार कम्युनिस्टों का अपना भी नहीं था: 1935 में राष्ट्रवादी सरकार के शिक्षा मंत्रालय ने विद्वान छ्येन श्वानथोंग द्वारा तैयार 324 सरलीकृत वर्णों की सूची जारी की थी, और फिर अपनी ही पार्टी के भीतर विरोध के चलते साल भर बाद उसे वापस ले लिया। 1956 के बाद बदला यह कि अब राज्य इन्हें लागू करवा रहा था: स्कूल, समाचार पत्र और सरकारी दस्तावेज़ नए रूपों पर आ गए।</p><h3>1977 का अति-सुधार</h3><p>दिसंबर 1977 में दूसरी लहर ने 853 और सरलीकरण प्रस्तावित किए, जिनमें से कुछ बेहद कठोर थे: 蛋 \"अंडा\" को 旦 लिखा जाना था, और 停 \"रुकना\" को 仃। पहले दौर के ज़्यादातर रूप जनता में पहले से चलते थे, पर इस बार कई रूप अनजाने थे, और 1978 के मध्य तक प्रकाशकों से इन्हें इस्तेमाल न करने को कह दिया गया। राज्य परिषद ने 24 जून 1986 को योजना औपचारिक रूप से रद्द कर दी। यह प्रसंग एक चेतावनी की तरह है: सरलीकरण की ध्वन्यात्मक और अर्थगत सीमाएँ होती हैं।</p><h3>बड़ा बँटवारा</h3><p>ताइवान, हांगकांग और मकाओ ने कभी सरलीकृत वर्ण नहीं अपनाए। दूसरी ओर सिंगापुर ने 1969 से सरलीकरण के अपने दौर चलाए और आख़िर में मुख्य भूमि वाला समूह ही अपना लिया, और मलेशिया 1981 में उसी राह चला। ताइवान ने <strong>पारंपरिक वर्णों</strong> को सांस्कृतिक विरासत का प्रतीक बनाया। पर बोली में दोनों पक्ष एकमत हैं। ताइवान का आधिकारिक मानक मिन नान या कैंटोनीज़ नहीं, बल्कि <strong>गुओयू</strong> (國語, मंदारिन) है — यह बीजिंग उच्चारण पर आधारित वह राष्ट्रीय मानक भाषा है जिसे चीन गणराज्य ने 1930 के दशक तक तय कर लिया था और 1945 में ताइवान ले आया। मुख्य भूमि ने बाद में उसी मानक को <em>पुतोंगहुआ</em> नाम से अपनाया, इसलिए ताइवान बोली का मानक तो साझा करता है, पर मुख्य भूमि के लिपि सुधार को नकारता है। हांगकांग औपचारिक चीनी आज भी पारंपरिक वर्णों में लिखता है, जैसा हमेशा से लिखता आया है; उसकी \"द्वि-लिपिक और त्रि-भाषी\" नीति का मतलब है लिखित चीनी और अंग्रेज़ी, और बोली जाने वाली कैंटोनीज़, पुतोंगहुआ और अंग्रेज़ी।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.91\" data-lng=\"116.39\" data-zoom=\"4\">🗺 बीजिंग — सुधार का केंद्र की ओर जाएँ</button></div>\n","japanese-shinjitai-postwar":"<h3>कब्ज़े के दौर की जल्दी</h3><p>चीन का सरलीकरण ज़्यादा मशहूर है, लेकिन जापान वहाँ पहले पहुँचा — और अपने बूते: उसके आधिकारिक सरलीकृत रूप 1949 में आ गए थे, चीन की 1956 की योजना से सात साल पहले। 1946 की <em>तोयो कांजी</em> (当用漢字) सूची ने — जिसे जापान की अपनी राष्ट्रीय भाषा परिषद ने 1920 के दशक से चले आ रहे प्रस्तावों के आधार पर तैयार किया और जो अमेरिकी कब्ज़े के दौरान जारी हुई — दैनिक उपयोग के 1,850 अक्षर तय किए और उनमें से 131 को पहले ही सरलीकृत रूप में छापा। 1949 की अक्षर-रूप तालिका (当用漢字字体表) ने इन <strong>शिंजिताई</strong> (新字体, 'नए अक्षर-रूप') को लगभग 500 अक्षरों तक फैला दिया। पीछे इससे भी कहीं ज़्यादा क्रांतिकारी दबाव था: 1946 के अमेरिकी शिक्षा मिशन ने रोमाजी की सिफ़ारिश की थी। लेकिन 1948 के एक राष्ट्रव्यापी साक्षरता सर्वेक्षण में पता चला कि लगभग हर वयस्क कम-से-कम कुछ कांजी पढ़-लिख सकता था, और रोमाजी की मुहिम ठंडी पड़ गई।</p><h3>तीन चरणों में मानकीकरण</h3><ul><li><strong>1946</strong>: तोयो कांजी — सरकारी दस्तावेज़ों और प्रेस के लिए एक प्रतिबंधात्मक सूची: अगर किसी शब्द का कांजी इसमें नहीं था, तो लेखकों से कहा गया कि कोई दूसरा शब्द चुनें या उसे काना में लिखें।</li><li><strong>1981</strong>: जोयो कांजी — 1,945 अक्षर, विद्यालयों और मीडिया का संदर्भ मानक।</li><li><strong>2010</strong>: संशोधित जोयो कांजी — 196 अक्षर जोड़े गए और 5 हटाए गए, कुल 2,136। नए अक्षरों में 俺 और 誰 जैसे रोज़मर्रा के अक्षर थे, और पहली बार जापान के सभी प्रांतों (प्रीफ़ेक्चरों) के नामों का हर अक्षर (岡, 阪, 熊, 鹿, 梨 आदि)।</li></ul><h3>एक मक़सद, अलग-अलग कैंचियाँ</h3><ul><li><strong>廣 → 広</strong> (जापान) vs <strong>广</strong> (चीन) — जापान ने अक्षर की बनावट ज़्यादा बचाए रखी।</li><li><strong>鐵 → 鉄</strong> (जापान) vs <strong>铁</strong> (चीन) — दोनों ने जटिल दायाँ हिस्सा 失 से बदल दिया; फ़र्क़ बस इतना है कि चीन ने धातु-मूलक 金 को भी छोटा करके 钅 कर दिया।</li><li><strong>體 → 体</strong>: दोनों एक ही रूप पर पहुंचे।</li></ul><h3>क्युजिताई और सांस्कृतिक तर्क</h3><p>रूढ़िवादी विद्वानों ने तर्क दिया कि पुराने रूप, <em>क्युजिताई</em> (旧字体), अपनी बनावट में ही अर्थ सँजोए रहते हैं — कि 鐵 अपना इतिहास अपनी आकृति में लिए चलता है, जबकि 鉄 महज़ एक शॉर्टहैंड है। और वह भी एक अशुभ शॉर्टहैंड, क्योंकि इसे 金を失う, यानी \"पैसा गँवाना\", पढ़ा जा सकता है: कुछ जापानी इस्पात कंपनियाँ और रेलवे आज भी अपने नामों और लोगो में इससे बचती हैं और इसकी जगह 鐵 या उसका वैकल्पिक रूप 鉃 लिखती हैं। यह बहस चीनी पारंपरिक/सरलीकृत विभाजन से मेल खाती है, लेकिन जापान में कांजी काना के साथ एक मिली-जुली व्यवस्था का हिस्सा है, जिसमें व्याकरणिक अंत काना सँभालते हैं — इसलिए कहा जा सकता है कि हर अक्षर की ठीक-ठीक आकृति पर उतना कुछ नहीं टिका जितना केवल अक्षरों वाले चीनी पाठ में।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja_kun\">📍 मानचित्र पर कुन-योमि (जापानी मूल पठन) देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.69\" data-zoom=\"5\">🗺 टोक्यो की ओर जाएँ</button></div>\n","ducai-yuan-zhongyuan-yinyun":"<h3>मंदारिन के जन्म का दस्तावेज़</h3><p>1324 में, युआन राजवंश के मध्यकाल में, गीतकार और संगीत-तत्ववेत्ता <strong>ज़ोऊ देछिंग (周德清)</strong> ने <em>ज़ोंगयुआन यिनयुन</em> पूरा किया। उद्देश्य व्यावहारिक था — लोकप्रिय <strong>ज़ाजू (雜劇)</strong> ओपेरा के संगीतकारों को ऐसे तुक खोजने में मदद करना जो उत्तरी बोली में गाए जाने पर सच में तुक बनें। उनका घोषणापत्र एक पंक्ति में समा जाता है: \"गीत लिखने हों तो अपनी बोली सुधारो; बोली सुधारनी हो तो मध्य मैदान की ध्वनियों पर चलो।\" 1341 में छपी यह पुस्तक 5,866 अक्षरों को केवल 19 तुक-समूहों में छाँटती है — 東鍾 से 廉纖 तक — और इसमें कोई उलट-वर्तनी (反切) नहीं है: समध्वनि अक्षरों का हर समूह बस साथ-साथ गिना दिया गया है।</p><p>पर ऐतिहासिक भाषाविज्ञान के लिए यही वह दस्तावेज़ है जो मध्यकालीन चीनी (सुई-तांग ध्वनि, ~600 ई) से शुरुआती आधुनिक मंदारिन तक के बदलाव को पक्का करता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"一\">📍 बोलियों में 一 देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"zh_yuan\">🎭 युआन मंदारिन</button></div><h3>क्या साबित होता है</h3><ul><li><strong>प्रवेश-स्वर (入聲) के अक्षर बाक़ी तीन स्वराघातों में रखे गए हैं।</strong> ज़्यादातर पुराने पूर्ण-घोष आद्य व्यंजन के बाद यांगपिंग में, अनुनासिक या l- के बाद छ्यू में, और अघोष आद्य व्यंजन के बाद शांग में। यह पैटर्न बीजिंग के बजाय आज की च्याओ-ल्याओ मंदारिन के ज़्यादा क़रीब है, जो शानदोंग और ल्याओदोंग प्रायद्वीपों पर बोली जाती है — बीजिंग में अघोष वाला समूह चारों स्वराघातों में बिखर गया। ज़्यादातर विद्वान इसे इस बात का सबूत मानते हैं कि प्रवेश-स्वर ख़त्म हो चुका था, पर ख़ुद ज़ोऊ ने लिखा कि उन्होंने ये अक्षर \"तुकों को चौड़ा करने के लिए, गीत लिखने हेतु\" दूसरे स्वराघातों में बाँटे, और कि \"साँस और बोली में प्रवेश-स्वर का भेद अब भी है\"; लू झीवेई और दूसरे विद्वान निष्कर्ष निकालते हैं कि वह अभी लुप्त नहीं हुआ था।</li><li><strong>यिनपिंग और यांगपिंग अलग हो गए थे।</strong> मध्यकालीन चीनी की एक ही 平 (सम) श्रेणी मूल आद्य व्यंजन के घोषत्व के आधार पर बँट गई थी — इसी से आज के <em>पहले</em> और <em>दूसरे</em> स्वराघात बने।</li><li><strong>घोष व्यंजन अघोष हो गए थे।</strong> मध्यकालीन चीनी की 全濁 (पूर्ण-घोष) शृंखला — b, d, g, dz, dʒ — अब स्वनिमिक नहीं रही थी; यही विलय आज मंदारिन को वू से अलग करता है।</li></ul><h3>रंगमंच से मंदारिन</h3><p>दिलचस्प यह है कि शुरुआती मंदारिन का मुख्य दस्तावेज़ <em>गीतकारों की मार्गदर्शिका</em> है, कोई दरबारी शब्दकोश नहीं। ज़ोऊ सहमति के साथ उन लोगों को उद्धृत करते हैं जो मानते थे कि मध्य मैदान का उच्चारण पहले ही एक साझा मानक बन चुका था — शासन पर चर्चा करते अधिकारियों और राजकीय अकादमी के शिक्षकों से लेकर अदालत में मुक़दमे सुनते मजिस्ट्रेटों तक, सब उसे बरतते थे। <em>ज़ोंगयुआन यिनयुन</em> उसी बोली को लिखित रूप में तय करता है। 廣韻 (1008) ने मध्यकालीन चीनी को एक साहित्यिक आदर्श के रूप में सहेजा; <em>ज़ोंगयुआन यिनयुन</em> दिखाता है कि तीन सदियों बाद लोग मंच पर सचमुच क्या गा रहे थे।</p>","phags-pa-as-hangul-origin":"<h3>एक चुभता हुआ दावा</h3><p>1966 के अपने डॉक्टोरल शोध-प्रबंध में अमेरिकी कोरियाई-अध्ययन विद्वान <strong>गैरी लेड्यार्ड</strong> ने तर्क दिया कि राजा सेजोंग की <em>हुनमिनजेओंग्म</em> (訓民正音, 1443) किसी विदेशी नमूने की कुछ ऋणी थी। कनाडाई भाषाविद् ई. आर. होप के 1957 के एक लेख को आगे बढ़ाते हुए उन्होंने प्रस्तावित किया कि पाँच मूल व्यंजन-आकार <strong>फग्स-पा लिपि</strong> से ढाले गए थे — यूआन साम्राज्य की वह वर्णमाला जिसे तिब्बती भिक्षु द्रोगन छोग्यल पाक्पा ने 1269 में बनाया था। उनका सुराग़ ख़ुद स्रोतों में था: 1443 का दरबारी अभिलेख कहता है कि नए अक्षर \"प्राचीन मुहर-लिपि की नक़ल करते हैं\" (字倣古篆)। लेड्यार्ड ने \"मुहर\" को फग्स-पा की ओर एक छिपा इशारा पढ़ा, क्योंकि \"मुहर\" से एक मंगोल लिपि-शैली का भी वर्णन हो सकता था।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"zh_phagspa\">ꡛ फग्स-पा</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko_mid\">📜 मध्ययुगीन कोरियाई</button></div><h3>प्रमाण</h3><p>लेड्यार्ड ने पाँच अक्षरों में दिखने की समानता की ओर इशारा किया: ㄱ, ㄷ, ㄹ, ㅂ, ㅅ — प्रत्येक अपने संगत फग्स-पा व्यंजन (ꡂ, ꡊ, ꡙ, ꡎ, ꡛ) से मिलता-जुलता: ㄱ है ꡂ <em>g</em>, जिसका निचला खाना हटा दिया गया, और ㅂ है ꡎ <em>b</em>, घुमाकर और सरल करके। उनका तर्क था कि हर ध्वनि-वर्ग के ऐसे एक नमूना-अक्षर से बाक़ी व्यंजन रेखाएँ जोड़कर या हटाकर बनाए गए। उन्होंने यह भी बताया कि कोरिया में फग्स-पा कोई मृत लिपि नहीं थी: जब यह लिपि नई थी तब गोरियो मंगोल शासन के अधीन था, और जोसियन तब भी इसके सरकारी पाठ्यक्रम चलाता था — 1423 तक पढ़ाई घट रही थी, पर बंद नहीं हुई थी। 1443 तक युआन को गए 75 साल हो चुके थे, पर फग्स-पा के रूप कोरियाई दरबार में रखी किताबों में बचे हुए थे, जिनमें <em>मेंग्गु ज़ियून</em> जैसी चीनी-मंगोल छंद-सामग्री भी थी जिस पर सेजोंग के भाषाशास्त्री काम करते थे।</p><h3>खंडन</h3><p>आलोचकों ने — जिनमें कोरियाई भाषाविद् <strong>सांग-ओक ली</strong> और <strong>यंग-की किम-रेनो</strong> शामिल हैं — जवाब दिया कि समानताएँ इतनी कम हैं कि उन्हें व्यवस्थित नहीं कहा जा सकता, कि इतने सरल अक्षर लगभग किसी भी लिपि से मिलाए जा सकते हैं, और कि <em>हुनमिनजेओंग्म हेरये</em> (1446) हांगुल व्यंजन रूपों को साफ़ शब्दों में उच्चारण-अंगों के चित्र बताता है। उनका कहना है कि उस दौर की कोई और लिपि अपने अक्षर-आकारों को इस तरह वाक्-अंगों की बनावट पर नहीं टिकाती — तो सेजोंग के विद्वान इतनी विस्तृत \"लीपापोती\" क्यों गढ़ते? समर्थकों का जवाब है कि दोनों बातें टकराती नहीं: कुछ रूपरेखाएँ उधार लेना उनके ऊपर खड़ी की गई अभिलक्षण-आधारित व्यवस्था के आगे छोटी बात होगी।</p><h3>अब तक कोई निर्णय नहीं</h3><p>पश्चिमी विद्वान सहमत नहीं, बँटे हुए हैं: <strong>पीटर टी. डेनियल्स</strong> ने लिखा कि लेड्यार्ड के पाँच अक्षर \"लगभग निश्चित रूप से संगत फग्स-पा अक्षरों पर आधारित हैं\"; <strong>जे जुंग सोंग</strong> इस प्रभाव को \"संभावनाओं के दायरे में\" रखते हैं; <strong>रिचर्ड स्प्राउट</strong> कहते हैं कि प्रभाव को ख़ारिज नहीं किया जा सकता, पर उसका कोई सीधा सबूत भी नहीं है; <strong>जेफ़्री सैम्पसन</strong> किसी बड़े प्रभाव को लेकर संशय में हैं; और <strong>रॉस किंग</strong> ने 1987 में बताया कि वरिष्ठ कोरियाविद् एडवर्ड वैगनर और सैमुअल मार्टिन इसे नहीं मानते थे। जिस पर विवाद नहीं है वह यह कि सैद्धांतिक ढाँचा — उच्चारण-ध्वनिविज्ञान — सेजोंग का अपना है। यानी बहस असल में पाँच रूपरेखाओं की है, इस बात की नहीं कि व्यवस्था किसने रची: लेड्यार्ड की व्याख्या में भी, ध्वनि के बनने का तरीक़ा दिखाने वाले अक्षरों का विचार, और उन्हें रेखा-दर-रेखा खड़ा करने का विचार, सेजोंग के दरबार का ही है।</p>","manchu-script-origins":"<h3>लेवांत से निषिद्ध नगर तक</h3>\n<p><strong>मांचू लिपि</strong> — छिंग राजवंश (1644–1912) की द्विभाषी शिलाओं पर लूपों और बिंदुओं से भरे खड़े स्तंभ — मांचूरिया में जन्मी नहीं थी। इसकी वंशावली दो हजार वर्षों से अधिक पुरानी है, जो ईसा पूर्व 5वीं शताब्दी में अकेमेनिड फारसी साम्राज्य की प्रशासनिक भाषा <strong>अरामी लिपि</strong> तक जाती है।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"mnc\">📍 नक्शे पर मांचू भाषा देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"41.8\" data-lng=\"123.4\" data-zoom=\"4\">🗺️ मांचूरिया की ओर उड़ें</button>\n</div>\n\n<p>विरासत की कड़ियाँ इस तरह चलती हैं:</p><ul><li><strong>अरामी (5वीं शताब्दी BCE):</strong> एक अब्जद (केवल व्यंजन लिखने वाली वर्णमाला), जो फ़ारसी साम्राज्य में मिस्र से मध्य एशिया तक फैली। इसका दाएँ से बाएँ लिखा जाने वाला घसीट रूप बाद की दर्जनों लिपियों का साँचा बना।</li><li><strong>सोग्दियाई (1–10वीं शताब्दी CE):</strong> सोग्दियाई व्यापारी अरामी से निकले अक्षर रेशम मार्ग पर ले गए, जो तब भी क्षैतिज पंक्तियों में दाएँ से बाएँ लिखे जाते थे।</li><li><strong>प्राचीन उइगुर (लगभग 8वीं शताब्दी CE):</strong> तुर्क उइगुर लिपिकों ने सोग्दियाई को अपनी भाषा के लिए ढाला और उसे 90° घुमा दिया, ताकि वह <em>ऊपर से नीचे</em>, बाएँ से दाएँ पढ़े जाने वाले स्तंभों में चले — शायद चीनी की नक़ल में; इस शृंखला की हर बाद की लिपि ने यही ढाँचा रखा। चंगेज़ ख़ान के मंगोलों ने 13वीं सदी की शुरुआत में यह लिपि अपनाई — 1204 में नाइमानों को हराने और उनकी सेवा में रहे तता-तोंगा नाम के एक उइगुर लिपिक को बंदी बनाने के बाद।</li><li><strong>मंगोलियाई (13वीं शताब्दी):</strong> प्राचीन उइगुर अक्षर मंगोल ध्वनियों के अनुरूप ढाले गए; यह लिपि आज भी भीतरी मंगोलिया में मंगोल विद्यार्थियों को पढ़ाई जाती है, और 2025 से ख़ुद मंगोलिया में भी सिरिलिक के साथ सह-आधिकारिक है।</li><li><strong>मांचू (1599):</strong> जुरचेन सरदार <em>नूरहाची</em> ने अपने सलाहकार एर्देनी और गागाई को मंगोल वर्णमाला को जुरचेन (बाद में मांचू) भाषा के लिए ढालने का आदेश दिया। यह पहला रूप, <em>tongki fuka akū hergen</em> यानी \"बिंदु और वृत्त के बिना लिपि\", विशेषक चिह्नों से रहित था, इसलिए कुछ अक्षर अस्पष्ट रहते थे। <strong>1632</strong> में दाहाई ने बिंदु और वृत्त जोड़े (<em>tongki fuka sindaha hergen</em>), जिससे ज़्यादातर अस्पष्टताएँ दूर हो गईं।</li></ul>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"sjo\">📍 सिबे भाषा (मांचू का जीवित वंशज) देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"43.8\" data-lng=\"81.0\" data-zoom=\"6\">🗺️ क़ापक़ल, शिनजियांग की ओर उड़ें</button>\n</div>\n\n<p>उइगुरों के लिपि घुमाने के बाद से इस शृंखला की लिपियों में एक ख़ास बात साझा है: वे <strong>खड़े स्तंभों में लिखी जाती हैं, और स्तंभ पन्ने पर बाएँ से दाएँ बढ़ते हैं</strong>, जबकि चीनी स्तंभ दाएँ से बाएँ चलते हैं। इसलिए मांचू पांडुलिपि पश्चिमी किताब की तरह बाईं ओर से खुलती है, फिर भी हर स्तंभ शास्त्रीय चीनी की तरह ऊपर से नीचे पढ़ा जाता है।</p><p>उइगुरों के लिपि घुमाने के बाद से इस शृंखला की लिपियों में एक ख़ास बात साझा है: वे <strong>खड़े स्तंभों में लिखी जाती हैं, और स्तंभ पन्ने पर बाएँ से दाएँ बढ़ते हैं</strong>, जबकि चीनी स्तंभ दाएँ से बाएँ चलते हैं। इसलिए मांचू पांडुलिपि पश्चिमी किताब की तरह बाईं ओर से खुलती है, फिर भी हर स्तंभ शास्त्रीय चीनी की तरह ऊपर से नीचे पढ़ा जाता है।</p><h3>फग्स-पा का अंतराल</h3><p>इस शृंखला के बीच एक भटकाव भी आया। 13वीं शताब्दी में तिब्बती भिक्षु <strong>फग्स-पा</strong> ने कुबलई ख़ान के लिए एक बिलकुल नई लिपि रची, जिसका उद्देश्य था मंगोल साम्राज्य की सभी भाषाओं को एक ही एकीकृत प्रणाली में लिखना। <em>फग्स-पा लिपि</em> (八思巴文) लगभग 1269 से 1368 तक राजकीय मुहरों और अभिलेखों पर प्रयुक्त हुई। तिब्बत में इसी नाम से जानी जाने वाली एक मुहर-लिपि 20वीं सदी तक मुहरों पर खोदी जाती रही, हालाँकि कुछ विद्वान उस बाद की लिपि को असली फग्स-पा के बजाय एक अलग तिब्बती मुहर-लिपि मानते हैं। पर फग्स-पा एक <em>समानांतर प्रयोग</em> थी, मांचू शृंखला की कड़ी नहीं: उसने आगे चलकर कोरियाई हांगुल की चर्चा को प्रभावित किया और पूर्वी एशियाई पुरालिपिशास्त्र पर छाप छोड़ी, किंतु मांचू लिपि उइगुर-व्युत्पन्न मंगोल लिपि से उतरी है, फग्स-पा से नहीं।</p>\n\n<h3>सिबे: जीवित उत्तराधिकारी</h3><p>ख़ुद मांचू भाषा मातृभाषा के रूप में अब लगभग विलुप्त है; हेइलोंगच्यांग के दूरस्थ गाँवों में शायद मुट्ठी भर वृद्ध वक्ता बचे हैं। पर लिपि ज़िंदा है। <strong>1764</strong> में छिंग दरबार ने सिबे बैनरमैनों की एक चौकी शेंगजिंग (आज का शेनयांग) से शिनजियांग में इली की सुदूर पश्चिमी सीमा पर भेजी। कई हज़ार सैनिकों और उनके परिवारों ने यह सफ़र किया, कुछ हिस्सा बैलगाड़ियों पर, और इसमें उन्हें साल भर से कहीं ज़्यादा लगा। उनके वंशज, <strong>छापछाल के सिबे लोग</strong>, मांचू लिपि और मांचू-परिवार की भाषा सुरक्षित रखे हुए हैं। 2000 में लगभग 30,000 लोग अब भी सिबे बोलते थे। 1998 में छापछाल के प्राथमिक विद्यालयों में पढ़ाई चीनी में होती थी, पर सिबे के पाठ अनिवार्य थे। समाचारपत्र <em>Cabcal Serkin</em> (छापछाल समाचार) — 1946 से प्रकाशित, और अक्सर दुनिया का अकेला सिबे-भाषी अख़बार कहा जाने वाला — उसी ऊर्ध्वाधर लिपि में छपता है जिसे एर्देनी और गागाई ने 1599 में तैयार किया था।</p><p>उस ऊर्ध्व वंशरेखा की दो शाखाएँ आज भी जीवित हैं: भीतरी मंगोलिया और मंगोलिया में मंगोल लिपि, और छापछाल के सिबे लोगों में मांचू लिपि। आज सिबे में होमवर्क लिखता कोई विद्यार्थी ऐसे अक्षर बरत रहा है जिनके पूर्वज कोई 2,500 साल पहले फ़ारसी साम्राज्य की दफ़्तरी लिपि थे।</p>","old-mongol-uyghur-script":"<h3>एक जाति, दो लिपियाँ</h3>\n<p>उलानबातर में कोई भी मंगोल साइनबोर्ड देखिए — वहाँ <strong>सिरिलिक</strong> मिलेगी। होहहोत (भीतरी मंगोलिया, चीन) में कोई भी मंगोल साइनबोर्ड देखिए — वहाँ एक बहती हुई लिपि मिलेगी, जो ऊपर से नीचे स्तंभों में लिखी जाती है और जिसके स्तंभ बाएँ से दाएँ बढ़ते हैं। दोनों आबादियाँ एक ही वंश, एक ही भाषा-परिवार और एक ही महाकाव्य — <em>मंगोलों का गुप्त इतिहास</em> — साझा करती हैं, फिर भी अपनी भाषा बिल्कुल अलग वर्णमालाओं में लिखती हैं।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"47.9\" data-lng=\"106.9\" data-zoom=\"5\">🗺️ उलानबातर तक उड़ें (सिरिलिक मंगोलिया)</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"40.8\" data-lng=\"111.7\" data-zoom=\"5\">🗺️ होहहोत तक उड़ें (भीतरी मंगोलिया, पारंपरिक लिपि)</button>\n</div>\n\n<h3>चरण 1: चंगेज़ ख़ान और उइगुर लेखक (1206)</h3>\n<p>1204 में — 1206 के महाकुरुलताई में <strong>तेमुजिन</strong> के <em>चंगेज़ ख़ान</em> घोषित होने से दो साल पहले — उनकी सेना ने नाइमान महासंघ को कुचल दिया। बंदियों में नाइमान ख़ान का एक उइगुर लिपिक था, जो उसकी मुहर और ख़ज़ाना सँभालता था — <strong>तता-तोंगा</strong> (जिसे ततातुंगा भी लिखा जाता है) — और जब उसे विजेता के सामने लाया गया, तब भी वह अपने मालिक की मुहर थामे हुए था। मंगोलों के पास अपना कोई लेखन नहीं था; तता-तोंगा के पास था। चंगेज़ ख़ान ने उसे अपने बेटों और दूसरे राजकुमारों को प्राचीन उइगुर लिपि सिखाने पर लगाया, और उनके हाथों में वह लिपि मंगोल ध्वनियों के साँचे में ढल गई।</p>\n\n<p>इससे बनी <strong>मंगोल बिचिग</strong> (मंगोल लिपि) ऊर्ध्वाधर लिखी जाती है, ऊपर से नीचे, ऐसे स्तंभों में जो बाएँ से दाएँ बढ़ते हैं। यह अजीब मेल इतिहास का एक संयोग है: उइगुरों ने जो सोग्दियाई लिपि उधार ली थी, वह क्षैतिज रूप से दाएँ से बाएँ चलती थी, और उइगुर लिपिकों ने चीनी स्तंभों की नक़ल में उसे घड़ी की उल्टी दिशा में 90 अंश घुमा दिया, अक्षरों का क्रम बदले बिना। इसकी संतानों (मंगोल, ओइरात स्पष्ट लिपि, मांचू) ने स्तंभों का यह दुर्लभ बाएँ-से-दाएँ क्रम बनाए रखा, और बाद में फग्स-पा लिपि ने भी इसकी नक़ल की। भीतरी मंगोलिया में यह लिपि आज भी मंगोल भाषा का आधिकारिक लिखित रूप है — मंगोल-माध्यम स्कूलों में पढ़ाई जाती है और सार्वजनिक साइनबोर्डों पर चीनी अक्षरों के साथ दिखती है।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"mnc\">📍 मानचित्र पर मांचू</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"pmgl\">📍 प्रोटो-मंगोलिक पुनर्निर्माण</button>\n</div>\n\n<h3>चरण 2: फग्स-पा का अंतराल (1269–1368)</h3>\n<p>मंगोल साम्राज्य इतना विविध था कि ततातुंगा वाली उइगुर-मूल लिपि चीनी, तिब्बती, संस्कृत या फ़ारसी लिखने के लिए नाकाफ़ी पड़ने लगी। 1269 में कुबलई ख़ान ने तिब्बती भिक्षु <strong>फग्स-पा</strong> को एक सार्वभौमिक लिपि रचने का काम सौंपा। जो <em>फग्स-पा लिपि</em> (八思巴文) बनी — तिब्बती अक्षरों पर आधारित, पर ऊर्ध्व स्तंभों में लिखी जाने वाली — उसका इरादा था साम्राज्य की हर भाषा को, चीनी समेत, अक्षर-दर-अक्षर लिख पाना। युआन राजवंश भर यह शाही मुहरों और राजाज्ञाओं पर प्रयुक्त हुई, और कुछ विद्वानों ने — सबसे बढ़कर गैरी लेड्यार्ड ने — तर्क दिया है कि इसने कोरियाई हांगुल (1443) की रचना को प्रभावित किया, हालाँकि यह बात आज भी विवादित है। 1368 में मिंग राजवंश ने जब मंगोलों को खदेड़ा, फग्स-पा शाही प्रयोग से हट गई, पर मंगोल बिचिग बिना रुके चलती रही।</p>\n\n<h3>चरण 3: स्तालिन की कैंची (1946)</h3>\n<p>बीसवीं सदी तक मंगोलियाई जन गणराज्य (आज का मंगोलिया) सोवियत उपग्रह-राज्य था, और उसकी लिपि मॉस्को की लाइन के साथ बदलती रही। पहली लैटिन वर्णमाला 1931 में अपनाई गई और 1933 तक चुपचाप छोड़ दी गई। 21 फ़रवरी <strong>1941</strong> को मंगोलिया ने आधिकारिक रूप से एक नई <strong>लैटिन</strong> वर्णमाला अपनाई। मुश्किल से एक महीने बाद, 25 मार्च <strong>1941</strong> को, जब ख़ुद सोवियत संघ अपनी अल्पसंख्यक भाषाओं को लैटिन से सिरिलिक पर ले जा रहा था, लैटिन वाला निर्णय रद्द कर दिया गया और उसकी जगह <strong>सिरिलिक</strong> अपनाई गई, जो 1 जनवरी <strong>1946</strong> को औपचारिक सरकारी लिपि बन गई। घोषित कारण था मंगोल साक्षरता को सोवियत मुद्रण-ढाँचे से जोड़ना; वास्तविक प्रभाव यह हुआ कि सिरिलिक में पढ़ी-लिखी पीढ़ी 1946 से पुराने पाठ, शास्त्रीय साहित्य और मंगोल साम्राज्यों के शिलालेख सीधे पढ़ने की क्षमता से कट गई।</p>\n\n<p>इस बीच भीतरी मंगोलिया चीन गणराज्य के, और फिर चीनी जनवादी गणराज्य के अधीन रहा; जहाँ पारंपरिक लिपि का प्रयोग लगातार चलता रहा — कभी सरकारी समर्थन के दौर में, कभी उत्पीड़न के दौर में, जिनमें सबसे बुरा था सांस्कृतिक क्रांति का समय। परिणाम: एक ही भाषा-समुदाय, जिसे राजनीतिक सीमा ने दो बिल्कुल अलग लेखन-परंपराओं में बाँट दिया।</p>\n\n<h3>चरण 4: 2020 के विरोध</h3>\n<p>26 अगस्त <strong>2020</strong> को, स्कूली सत्र शुरू होने से कुछ ही दिन पहले, भीतरी मंगोलिया के शिक्षा विभाग ने घोषणा की कि मंगोल-माध्यम स्कूलों में तीन विषय <em>मंदारिन चीनी</em> और राष्ट्रीय चीनी-भाषा पाठ्यपुस्तकों पर चले जाएँगे: भाषा और साहित्य तथा \"नैतिकता और क़ानून\" पहली कक्षा से, और इतिहास सातवीं से। यह पाठ्यपुस्तकों के उस राष्ट्रीय एकीकरण का हिस्सा था जो 2017 से चीन में दूसरी जगहों पर लागू हो चुका था। प्रतिक्रिया तेज़ थी, और इस क्षेत्र के लिए अपने पैमाने में दुर्लभ: अभिभावकों ने स्कूलों का बहिष्कार किया, विद्यार्थी कक्षाओं से बाहर निकल आए, और पूरे भीतरी मंगोलिया में लोगों ने प्रदर्शन किए। प्रदर्शनकारियों ने पारंपरिक मंगोल लिपि में लिखे तख़्ते उठाए, जिन पर उन्होंने लिखा कि वे अपनी संस्कृति और भाषा के अस्तित्व के लिए लड़ रहे हैं।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"44.0\" data-lng=\"117.0\" data-zoom=\"5\">🗺️ भीतरी मंगोलिया — 2020 के विरोधों का क्षेत्र</button>\n</div>\n\n<h3>मंगोलिया में पुनरुत्थान</h3>\n<p>1990 की लोकतांत्रिक क्रांति के बाद से मंगोलिया ने सिरिलिक के साथ-साथ पारंपरिक लिपि की साक्षरता पुनर्जीवित करने का आधिकारिक संकल्प लिया है। उलानबातर के सड़क-चिह्नों पर अब कभी-कभी ऊर्ध्व मंगोल लिपि भी दिखती है। 2015 के मंगोल भाषा क़ानून ने <strong>2025</strong> की समय-सीमा तय की थी, और वह तारीख़ निभाई गई: जनवरी 2025 से राज्य और स्थानीय सरकारी निकायों को अपना आधिकारिक पत्राचार सिरिलिक और मंगोल बिचिग, दोनों में रखना होता है। सिरिलिक को हटाया नहीं जा रहा; ऊर्ध्व लिपि उसके बगल में जोड़ी जा रही है। प्रगति धीमी है: सिरिलिक के दशकों में स्कूल गए अधिकांश मंगोल वह लिपि नहीं पढ़ सकते जिसे उनके पूर्वज सात शताब्दियों तक बरतते रहे। पर युवा पीढ़ी सीख रही है — कुछ गर्व से, और कुछ इसलिए कि चंगेज़ ख़ान के शब्दों को उसी रूप में पढ़ने का एकमात्र रास्ता पारंपरिक मंगोल लिपि है जिस रूप में उनके अपने लेखकों ने उन्हें लिखा था।</p>\n\n<p>इस तरह वही ऊर्ध्व अक्षर आज दो अलग अर्थ ढोते हैं। उलानबातर में वे एक विरासत हैं जिसे क़ानून के सहारे फिर से खड़ा किया जा रहा है; होहहोत में, जहाँ उनका प्रयोग कभी रुका ही नहीं, 2020 में वे विरोध का झंडा बन गए।</p>","jurchen-script-deciphered":"<h3>राजनीतिक महत्वाकांक्षा से जन्मी लिपि</h3>\n<p>1115 में जुरचेन नेता <strong>वान्यान अगुदा</strong> ने जिन राजवंश (金朝) की स्थापना की, और शुरू में उनका दरबार खितान में लिखता था। पर साम्राज्य को अपनी लिपि चाहिए थी, इसलिए उन्होंने खितान, चीनी और जुरचेन भाषाओं में पारंगत विद्वान <strong>वान्यान शियिन</strong> (完顏希尹) को इसकी रचना का कार्य सौंपा। 1119–1120 तक शियिन ने <em>जुरचेन बड़ी लिपि</em> तैयार कर दी — जो दिखने में खितान बड़ी लिपि के तर्क पर चलती थी, पर जुरचेन की तुंगुसी ध्वनियों के हिसाब से ढाली गई थी। ठीक उन्नीस साल बाद, 1138 में, एक दूसरी और सरल प्रणाली — <em>जुरचेन छोटी लिपि</em> (女真小字) — <strong>शीज़ोंग सम्राट</strong> ने जारी की, जिनके बारे में कहा जाता है कि उन्होंने इसे ख़ुद बनाया था; <em>जिन शी</em> में इसका पहला सरकारी प्रयोग 1145 में दर्ज है। कौन-सी लिपि किस शिलालेख में है और दोनों प्रणालियों का आपसी संबंध क्या है, इस पर विद्वानों में आज भी बहस है।</p>\n\n<h3>~900 अक्षर और खितान का DNA</h3>\n<p>बची हुई समूची सामग्री में जुरचेन के केवल लगभग <strong>900 अक्षर</strong> ही प्रमाणित हैं — अकेले मिंग कालीन शब्द-सूची में इनमें से करीब 720 प्रयुक्त हुए हैं। कुछ अक्षर लोगोग्राम की तरह काम करते हैं (एक अक्षर = एक रूपिम), कुछ ध्वनि के लिए (एक अक्षर = एक शब्दांश), और कई खितान से उधार लिए गए चिह्न हैं जिन्हें जुरचेन ध्वनियों के लिए ढाला गया। चूंकि जुरचेन एक <em>योगात्मक भाषा</em> है — चीनी से बिल्कुल भिन्न — लिपिकों को क्रिया-प्रत्यय और विभक्ति-अंत लिखने के लिए इस व्यवस्था को सूझ-बूझ से फैलाना पड़ा।</p>\n\n<h3>मिंग काल का द्विभाषी शब्दकोश जिसने लिपि बचाई</h3>\n<p>1234 में मंगोलों के हाथों जिन राजवंश के पतन के बाद जुरचेन लिपि धीरे-धीरे ओझल होने लगी — और \"धीरे-धीरे\" ही सही शब्द है: 1413 में भी मिंग के खोजा नौसेनापति यिशिहा ने निचले अमूर पर तिर में खड़े किए अपने शिलास्तंभ पर एक जुरचेन पाठ खुदवाया था। मिंग काल के जुरचेनों ने 1635 में अपना नाम बदलकर मांचू रख लिया, और आगे चलकर अपनी भाषा मंगोल वर्णमाला से ढाली गई एक लिपि में लिखी — जिसका पुराने जुरचेन अक्षरों से कोई नाता नहीं था। जुरचेन लिपि को पूर्ण विस्मृति से बचाने वाला था मिंग कालीन दस्तावेज़: <strong>《女真譯語》</strong> (<em>नूझेन यियू</em>) — जुरचेन अक्षरों को चीनी अनुवाद और ध्वन्यात्मक टिप्पणी के साथ जोड़ने वाली द्विभाषी शब्द-सूची। यह जुरचेन लिपि-विश्लेषण की 'रोज़ेटा शिला' बन गई।</p>\n\n<h3>डैनियल केन और 800 साल पुरानी पहेली</h3>\n<p>आधुनिक अध्ययन की राह जर्मन चीनविद् विल्हेम ग्रूबे की <em>Die Sprache und Schrift der Jučen</em> (1896) ने खोली, जो मिंग शब्द-सूची पर आधारित थी। जापान में कियोसे गिसाबुरो और चीन में जिन छिज़ोंग जैसे विद्वानों ने काम को आगे बढ़ाया, और ऑस्ट्रेलियाई भाषाविद् <strong>डैनियल केन</strong> की 1989 की पुस्तक ने कसे हुए ध्वन्यात्मक पुनर्निर्माण स्थापित किए। आधुनिक विद्वान शब्द-सूचियों में वास्तव में मिलने वाले सात सौ से कुछ अधिक अक्षरों में से अधिकांश के पाठ निर्धारित कर चुके हैं। इस केंद्रीय हिस्से से आगे लिपि आज भी केवल आंशिक रूप से ही पढ़ी जा सकी है: बची हुई सामग्री बहुत थोड़ी है — नौ ज्ञात शिलालेख और मिंग कालीन शब्द-सूचियाँ — और कई अक्षर इतने कम संदर्भों में मिलते हैं कि उन्हें निश्चित रूप से पढ़ना कठिन है।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"juc\">📍 मानचित्र पर जुरचेन देखें</button>\n<button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"41.8\" data-lng=\"125.0\" data-zoom=\"5\">🗺 जुरचेन मातृभूमि (मांचूरिया) की ओर जाएँ</button></div>\n\n<h3>यह क्यों महत्वपूर्ण है</h3><p>जुरचेन पूर्वी एशिया के इतिहास की धुरी पर खड़ी है। इसके बोलने वालों ने वह राजवंश स्थापित किया जिसने उत्तरी चीन पर एक शताब्दी शासन किया, सोंग को पीछे धकेला, और वह राजनीतिक भूगोल गढ़ा जिसे आगे चलकर मंगोलों ने विरासत में पाया। इस लिपि के अक्षरों की कोई संतान नहीं बची, पर इसकी लिपिक-परंपरा ने परवर्ती मांचू लिपि की ज़मीन तैयार की — और वही मांचू लिपि आगे चलकर छिंग राजवंश (1644-1912) की राजकीय लिपि बनी, जो आज भी जीवित है: औपचारिक रूप से निषिद्ध नगर के भीतर द्विभाषी पट्टिकाओं पर, और एक जीवित लिखित भाषा के रूप में शिनजियांग के छापछाल शिबे स्वायत्त काउंटी की सिबे लिपि में। जुरचेन को पढ़ पाना सिर्फ़ पुरानी चीज़ों का शौक़ नहीं है: इससे उत्तरी चीन के अभिलेखों का सदी भर लंबा ख़ालीपन भरता है, और समझ आता है कि तुंगुसी लोगों ने अपनी भाषाई पहचान छोड़े बिना चीनी ढर्रे पर पढ़ी-लिखी नौकरशाही कैसे खड़ी की।</p>\n\n<blockquote>बहुत कम लिपियों से इतना बेढब काम माँगा गया है जितना एक योगात्मक तुंगुसी भाषा को चीनी ढंग के अक्षरों में बिठाना।</blockquote>","yale-mc-tonal-categories":"<h3>चार पूर्वज</h3>\n<p>लगभग 7वीं सदी ईस्वी में — <em>क्येयून</em> (切韻) पद्य-कोश के काल में, जो 601 ईस्वी में सुई राजवंश के समय संकलित हुआ और जिसे तांग राजवंश ने मानक बनाया — चीनी में चार स्वराघात श्रेणियाँ थीं: <strong>पिंग (平), शांग (上), क्यू (去) और रू (入)</strong>। <em>प्रवेशी स्वराघात</em> (入声) सुर का कोई आकार नहीं, बल्कि शब्दांश की बनावट की श्रेणी थी: उसके सभी अक्षर एक छोटे व्यंजन-विराम (-p, -t या -k) पर समाप्त होते थे।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"yue_hk\">📍 मानचित्र पर कैंटोनीज़ देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"zh\">📍 मानचित्र पर मंदारिन देखें</button>\n</div>\n\n<h3>सघोष-विभाजन: सब पर राज करने वाला एक नियम</h3>\n<p>मध्यकालीन चीनी में सघोष और अघोष आदि-व्यंजनों की बहुत-सी जोड़ियाँ थीं। अगली सदियों में सघोष व्यंजन हर बोली में अलग-अलग ढंग से विलुप्त या विलीन हुए — पर पहले एक स्थायी छाप छोड़ गए: मूल सघोष आदि-व्यंजन वाले अक्षरों में <strong>निम्न-स्वराघात</strong> विकसित हुए, अघोष में उच्च-स्वर। यही <em>यिन-यांग विभाजन</em> है। (कुछ बोलियों में बाद में सुर उलट गए, इसलिए कई भाषाविद् इन दोनों रजिस्टरों को \"ऊपरी\" और \"निचला\" कहने के बजाय \"अँधेरा\" (यिन) और \"उजला\" (यांग) कहते हैं।) नतीजा यांत्रिक है: मूल चारों स्वराघात <strong>यिन (阴/ऊपरी)</strong> और <strong>यांग (阳/निचले)</strong> रजिस्टर में बँट गए, बस इस आधार पर कि अक्षर पहले किस तरह के व्यंजन से शुरू होता था। चार स्वराघात × दो रजिस्टर = आठ संभावित स्थान। फिर बोलियों ने कुछ स्थान मिला दिए, कुछ को दूसरे ढंग से बाँटा, और सिनिटिक परिवार में अंतिम गिनती बहुत अलग-अलग है।</p>\n\n<h3>कैंटोनीज़ का मामला: 9 स्वराघात (या 6+3)</h3>\n<p>कैंटोनीज़ इसका आदर्श उदाहरण है। छह <em>जीवित स्वराघात</em> पिंग/शांग/क्यू के यिन-यांग विभाजन का परिणाम हैं — <strong>6 आरोह-अवरोह स्वराघात</strong>। कैंटोनीज़ ने प्रवेशी स्वराघात भी बनाए रखा। यिन-यांग विभाजन से उसके दो अवरुद्ध स्वराघात बने, और बाद में कैंटोनीज़ के भीतर ही एक और विभाजन हुआ — जिसकी शर्त पुराना आदि-व्यंजन नहीं, बल्कि स्वर की लंबाई थी — और तीसरा जुड़ गया, जिससे कुल <strong>3 अवरुद्ध स्वराघात</strong> बने। इसलिए पारंपरिक गिनती <strong>9 स्वराघात</strong> है, पर रोज़मर्रा में मिलने वाले रोमनीकरण नौ नहीं लिखते। येल सात लिखता है (वह ऊँचे अवरोही को ऊँचे सम से अलग रखता है), पर अवरुद्ध अक्षर को ठीक उसी ऊँचे, मध्य या निचले सम स्वराघात की तरह लिखता है जिसकी सुर-ऊँचाई उसमें है; इस मानचित्र पर प्रयुक्त जुटपिंग भी केवल 1–6 अंक देता है (一 <em>jat1</em>, 目 <em>muk6</em>)। 陰入/中入/陽入 के लिए 7, 8 और 9 अंक पारंपरिक स्वराघात-तालिकाओं और कैंटोनीज़ पिनयिन (教院式) प्रणाली में बचे हैं — ये इतिहास का हिसाब रखने वाले लेबल हैं, तीन अतिरिक्त सुर नहीं।</p>\n\n\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"yue_hk\">📍 मानचित्र पर हांगकांग कैंटोनीज़ देखें</button></div>\n<h3>मंदारिन: 4 स्वराघात, प्रवेशी स्वराघात विलुप्त</h3>\n<p>मानक मंदारिन ने व्यवस्था को बहुत ज़्यादा सरल कर दिया। सघोष आदि-व्यंजन जल्दी ही पूरी तरह लुप्त हो गए; पिंग स्वराघात दो में बँटा, पर बाक़ी रजिस्टर विलीन हो गए, और सघोष स्पर्श या संघर्षी से शुरू होने वाले पुराने शांग-स्वराघात के शब्द थोक में क्यू-स्वराघात में चले गए (ख़ुद 上 <em>shàng</em> उन्हीं में से एक है — आज चौथा स्वराघात)। प्रवेशी स्वराघात ने अपने अंतिम व्यंजन-विराम खो दिए और उसके अक्षर फिर से बाँटे गए। इसका बड़ा हिस्सा नियमित था: सघोष स्पर्श से शुरू होने वाले शब्द दूसरे स्वराघात में गए (十 <em>shí</em>, 白 <em>bái</em>), और अनुनासिक या l- से शुरू होने वाले चौथे में (六 <em>liù</em>, 木 <em>mù</em>)। केवल अघोष आदि-व्यंजन वाले शब्द बिना किसी नियम के चारों स्वराघातों में बिखर गए — राजधानी में बोलियों के मेल-जोल की विरासत — और यही वे शब्द हैं जिनके कारण मंदारिन में पुराने 入声 अक्षर पहचानना इतना मुश्किल है।</p>\n\n\n\n<h3>मिन नान: 7 या 8 स्वराघात, प्रवेशी स्वराघात जीवित और दुगुना</h3><p>होक्किएन/ताइवानी (闽南语, मिन नान) ने प्रवेशी स्वराघात को उसकी अंत्य स्पर्श ध्वनियों (-p, -t, -k) समेत बचाए रखा। कैंटोनीज़ की तरह उसने भी प्रवेशी स्वराघात पर यिन-यांग विभाजन लागू किया, जिससे दो प्रवेशी स्वराघात बने (陰入 और 陽入)। शेष स्वराघातों में आगे भी विलय और विभाजन हुए, और मानक मिन नान में <strong>7 स्वराघातों</strong> का आधार बना। मिन नान अपनी <em>संधि</em> प्रणाली के लिए भी प्रसिद्ध है: स्वाभाविक बोली में वाक्यांश के आख़िरी अक्षर को छोड़कर हर अक्षर दूसरे स्वराघात पर चला जाता है। यह बदलाव काफ़ी हद तक नियमित है — एक शृंखला जिसे सीखने वाले एक चक्र की तरह याद करते हैं (ताइपे की बोली में स्वराघात 1 बनता है 7, 7 बनता है 3, 3 बनता है 2, 2 बनता है 1) — इसलिए हर शब्द के दो स्वराघात नहीं, बस नियमों का एक समूह सीखना होता है।</p>\n\n<h3>हक्का, वू और पूरा वर्णक्रम</h3><p>हक्का (客家话) बोलियों में सामान्यतः 5-7 स्वराघात होते हैं, और ज़्यादातर में प्रवेशी स्वराघात अपने -p, -t, -k के साथ बचा हुआ है (हक्का चर्च रोमनीकरण में 十 है <em>sṳ̍p</em>)। वू (吴语, शंघाईनीज़ सहित) पुरानी शियांग के साथ वह सबसे जाना-माना समूह है जो पुराने व्यंजनों का तीन-तरफ़ा भेद आज भी बचाए हुए है, इसलिए यिन-यांग विभाजन आज भी सुनाई देता है। वेनझोउ जैसी रूढ़िवादी दक्षिणी वू में आज भी आठ गिने जाते हैं, हालाँकि ख़ुद शंघाईनीज़ में घटकर लगभग पाँच रह गए हैं — इस मानचित्र की उत्तरी वू पंक्तियों के 1–8 अंक वुग्नियु की स्वराघात-श्रेणियाँ हैं, आठ अलग-अलग सुर नहीं। एक सावधानी: उत्तरी वू में, शंघाईनीज़ समेत, \"घोष\" व्यंजन आम तौर पर साँस-भरे घोष, यानी \"मरमराहट\", के साथ बोले जाते हैं, जो पूरे अक्षर के सुर को भी नीचे खींच लेती है। इसलिए वू यह ज़्यादा दिखाती है कि पुराना घोषत्व-भेद कहाँ गया, यह कम कि वह ठीक-ठीक सुनाई कैसा देता था।</p><p>पूरी कहानी एक ही शब्द में देखी जा सकती है। 十 \"दस\" एक प्रवेशी अक्षर था जो -p पर ख़त्म होता था। कैंटोनीज़ आज भी <em>sap6</em> कहती है, होक्किएन <em>tsa̍p</em> और हक्का <em>sṳ̍p</em> — सबमें स्पर्श सलामत। मंदारिन <em>shí</em> ने -p खो दिया, और चूँकि शब्द एक घोष व्यंजन से शुरू होता था, वह नियम के मुताबिक़ दूसरे स्वराघात पर जा उतरा। जापानी ने भी इसे उधार लिया: आज यह <em>jū</em> है, पर पुरानी काना वर्तनी じふ (<em>jifu</em>, पहले के <em>-pu</em> से) में -p अब भी छिपा है।</p>","old-chinese-baxter-sagart":"<h3>सबसे पुरानी चीनी भाषा जिसे हम 'सुन' सकते हैं</h3><p>पुरानी चीनी (OC) लगभग 1250–200 ईसा पूर्व बोली जाती थी — शिजिंग (詩經) और ऑरेकल-बोन शिलालेखों का युग। इसकी आवाज़ का कोई सीधा रिकॉर्ड नहीं है; भाषाविद् बाद के रूपों से पीछे की ओर चलकर इसे फिर से गढ़ते हैं। शुरुआती बिंदु है मध्यकालीन चीनी (MC) — 601 ई. के छंद-कोश <em>चिएयुन</em> (切韻) में दर्ज ध्वनि-व्यवस्था। इसमें वे जोड़ते हैं <em>शिजिंग</em> के गीतों के तुकांत, अक्षरों में गुँथे ध्वनि-सुराग़ (\"ध्वन्यात्मक श्रृंखलाएँ\"), दक्षिण-पूर्व की मिन बोलियाँ, जो कुछ पुराने भेद बचाए हुए हैं, पड़ोसी भाषाओं के शुरुआती उधार शब्द, और संबंधित चीनी-तिब्बती भाषाओं से तुलना।</p><h3>कार्लग्रेन का अग्रणी कार्य और उसकी सीमाएं</h3><p>स्वीडिश विद्वान कार्लग्रेन ने 1940 में <em>Grammata Serica</em> के रूप में पहला व्यवस्थित पुनर्निर्माण-कोश प्रकाशित किया, जो उनके पहले के कोश <em>Analytic Dictionary of Chinese and Sino-Japanese</em> (1923) द्वारा स्थापित मध्यकालीन चीनी प्रणाली पर टिका था। मध्यकालीन चीनी को धुरी बनाकर उन्होंने *mi̯wən (文) जैसे रूप निकाले। लेकिन बाद के विद्वानों ने दो बड़ी सीमाएं पाईं। उन्होंने अपनी प्रणाली ध्वन्यात्मक श्रृंखलाओं पर ही खड़ी की थी — एक ही घटक साझा करने वाले अक्षरों का समूह संकेत देता है कि उनका OC आदि-व्यंजन एक ही था — पर उन्हें एक कठोर <em>समस्थानी सिद्धांत</em> से बाँध दिया, यानी एक श्रृंखला के हर अक्षर का उच्चारण-स्थान एक ही होना चाहिए, जिससे जहाँ भी कोई श्रृंखला इस नियम पर खरी नहीं उतरती वहाँ कामचलाऊ जोड़-तोड़ करनी पड़ी; और उनकी स्वर-प्रणाली में ज़रूरी भेद काफ़ी नहीं थे।</p><h3>व्यंजन-समूह की क्रांति</h3><p>एक ही ध्वन्यात्मक घटक (<em>शिंगशंग</em> 形聲) साझा करने वाले अक्षरों के मध्यकालीन चीनी आदि-व्यंजन कभी-कभी बिल्कुल अलग होते हैं: 各 (MC kak) और 路 (MC luH) एक ही ध्वन्यात्मक घटक बाँटते हैं। आम व्याख्या यह है कि OC में व्यंजन-<em>समूह</em> या उपसर्ग थे, जो बाद में अलग-अलग शब्दों में अलग-अलग ढंग से सरल हो गए। ख़ुद कार्लग्रेन ने ऐसे मामलों के लिए *-l- वाले समूह प्रस्तावित किए थे; बाद के विद्वान इस विचार को बहुत आगे ले गए। Pulleyblank (1962) ने यह तर्क भी दिया कि चीनी का आरोही स्वराघात एक अंत्य कंठ्य-स्पर्श से आया — यह समझाने का एक अहम क़दम कि स्वराघात-रहित OC स्वराघात वाली कैसे बनी। Baxter के 1992 के ग्रंथ ने व्यंजन-समूहों की एक कसी हुई प्रणाली को औपचारिक रूप दिया, जिसने ऐसी सैकड़ों पहेलियाँ सुलझा दीं। 路 के लिए Baxter और Sagart का बाद का उत्तर दिखाता है कि विश्लेषण कितना आगे बढ़ चुका है: व्यंजन-समूह नहीं, बल्कि एक ढीला जुड़ा पूर्व-अक्षर और एक प्रत्यय, *Cə.rˤak-s, 各 *kˤak के बगल में।</p><h3>बैक्सटर-सागार्ट 2014</h3><p><em>Old Chinese: A New Reconstruction</em> (2014) ने Sagart का रूपात्मक आयाम जोड़ा:</p><ul><li><strong>अर्ध-अक्षर</strong>: 水 (जल) → *s.turʔ, जहाँ <em>s.</em> का बिंदु ढीले जुड़े पूर्व-अक्षर को दर्शाता है, जो मुख्य अक्षर का हिस्सा नहीं है। योजक चिह्न इसका उलटा दर्शाता है: 山 *s-ŋrar में <em>s-</em> धातु के आदि-व्यंजन से कसकर जुड़ा हुआ है।</li><li><strong>रूपात्मक उपसर्ग/प्रत्यय</strong>: उदाहरण के लिए प्रेरणार्थक बनाने वाला *s-, अकर्मक या स्थितिवाचक क्रियाएँ बनाने वाला *N-, और *-s, जो दूसरे कामों के साथ क्रियाओं से संज्ञाएँ बनाता था। एक ही अक्षर से लिखे जाने वाले, पर आज अलग-अलग स्वराघातों में पढ़े जाने वाले संबंधित शब्दों के जोड़े अक्सर इसी खोए हुए रूप-विधान के निशान हैं।</li><li><strong>ग्रसनी-ध्वनीकरण</strong>: लंबे समय से विवादित A/B प्रकार का अक्षर-भेद यहाँ मुख्य अक्षर के आदि-व्यंजन के ग्रसनी-ध्वनीकरण के रूप में समझाया गया है — यह Jerry Norman (1994) का प्रस्ताव था, जिसे Baxter और Sagart ने अपनाकर हर A प्रकार के अक्षर तक बढ़ाया (五 *C.ŋˤaʔ)।</li></ul><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"一\">一 दिखाएं</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"山\">山 दिखाएं</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"pst\">आदि-चीनी-तिब्बती देखें</button></div><h3>दो अक्षर पढ़ना</h3><p><strong>一</strong>: OC *ʔi[t] → मध्यकालीन ʔjit। स्वर-यंत्र व्यंजन OC में पहले से मौजूद था; मंदारिन <em>yī</em> ने कंठ्य-स्पर्श और अंत्य <em>-t</em>, दोनों खो दिए हैं, जबकि कैंटोनीज़ <em>jat</em> में <em>-t</em> अब भी बचा है। <strong>山</strong>: OC *s-ŋrar — पूर्व-व्यंजन <em>s-</em> ने मध्य *-r- के साथ मिलकर मध्यकालीन चीनी का मूर्धन्य ऊष्म sr- (ʂ-) दिया, यानी आधुनिक <em>shān</em> का <em>sh-</em>, जबकि धातु का आदि-व्यंजन *ŋ- लुप्त हो गया। सजातीय अक्षरों में यह *ŋ- अब भी दिखता है: Baxter और Sagart 顏 (चेहरा) का पुनर्निर्माण *C.ŋˤrar करते हैं।</p><h3>खुले प्रश्न</h3><p>OC में 4, 6 या अधिक स्वर थे? पूर्व-अक्षर वास्तविक अक्षर था या केवल व्यंजन उपसर्ग? तिब्बती और बर्मी सजातीय शब्द स्वर प्रणाली को कैसे सीमित करते हैं?</p>","sino-tibetan-cognates":"<h3>सहस्राब्दियों बाद फिर जुड़ता भाषा परिवार</h3><p>चीनी-तिब्बती भाषा परिवार — जिसमें चीनी, तिब्बती, बर्मी और सैकड़ों छोटी भाषाएं शामिल हैं — लगभग 1.4 अरब बोलने वालों के साथ भारोपीय के बाद दूसरे स्थान पर है। फिर भी इसकी मूल-भाषा को भारोपीय के मुक़ाबले अब भी कम समझा गया है। इसकी एक वजह यह है कि चीनी वर्ण ध्वनि से कहीं बेहतर अर्थ दर्ज करते हैं, और परिवार का आंतरिक वर्गीकरण अभी भी विवादित है।</p><p>चीनी को उसकी संबंधित भाषाओं से जोड़ने वाला सबसे मजबूत प्रमाण <em>समजातीय शब्द</em> हैं: ऐसे शब्द जो एक साझा पूर्वज शब्द से अलग-अलग विरासत में मिले और नियमित ध्वनि परिवर्तनों पर चलते हैं, जिनका पहले से अनुमान लगाया जा सकता है।</p><h3>'पाँच': तीन शाखाओं में *ŋā</h3><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"五\">五 दिखाएं</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"pst\">आदि-चीनी-तिब्बती देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"bo_sino\">तिब्बती-हान परत देखें</button></div><p>PST का 'पाँच' का मूल <strong>*ŋā</strong> पुनर्निर्मित है:</p><ul><li><strong>चीनी</strong>: प्राचीन *C.ŋˤaʔ → मध्यकालीन *ŋuX → मंदारिन <em>wǔ</em> 五. *ŋ- बस लुप्त हो गया: 疑 वर्ग का आदि व्यंजन मंदारिन के शून्य आदि व्यंजन में मिल गया, और <em>wǔ</em> का <em>w</em> केवल पिनयिन में <em>u</em> से शुरू होने वाले शब्दांश को लिखने का ढंग है। यही लोप 銀 <em>yín</em> और 我 <em>wǒ</em> में भी दिखता है, चाहे स्वर गोल हो या न हो।</li><li><strong>तिब्बती</strong>: <em>lnga</em> (ལྔ). l- उपसर्ग है; मूल <em>ŋa</em> PST से सीधे मेल खाता है।</li><li><strong>बर्मी</strong>: <em>ngā</em> (ငါး). ŋ- बिना उपसर्ग के बना रहा; स्वर *ā को सीधे दर्शाता है।</li></ul><h3>'चार': तीन शाखाओं में *li(j)</h3><p>'चार' का मूल <strong>*li(j)</strong> भी तीनों शाखाओं में इसी तरह मिलता है:</p><ul><li><strong>चीनी</strong>: प्राचीन *s.li[j]-s → मध्यकालीन *sijH → मंदारिन <em>sì</em> 四. उपसर्ग के असर से *l- की जगह *s- आ गया।</li><li><strong>तिब्बती</strong>: <em>bzhi</em> (བཞི།). b- उपसर्ग; मूल का <em>zh-</em> तिब्बती के भीतर ही हुआ तालव्यीकरण है: PST का पार्श्विक *l- *li(j) के अग्र स्वर से पहले तालव्य बन गया।</li><li><strong>बर्मी</strong>: <em>le</em> (လေး). PST का *l- यहाँ सीधे बचा है।</li></ul><h3>दो और समजातीय जोड़े</h3><p><strong>आँख (目)</strong>: PST *myak → प्राचीन *C.m(r)[u]k → <em>mù</em>; तिब्बती <em>mig</em> (མིག); बर्मी <em>myak</em>. मूल व्यंजन *m- तीनों में टिका हुआ।</p><p><strong>नाम (名)</strong>: PST *r-miŋ → प्राचीन *C.meŋ → <em>míng</em> 名; तिब्बती <em>ming</em> (མིང་); बर्मी <em>a-maññ</em> (အမည်, उच्चारण /ʔəmjì/). अनुनासिक अंत तीनों शाखाओं में साझा है — जहाँ चीनी और तिब्बती में -ŋ है, वहाँ बर्मी में तालव्य -ññ है, और यह एक नियमित संगति है।</p><h3>तरीक़े को लेकर एक ज़रूरी चेतावनी</h3><p>चीनी-तिब्बती में समजातीय शब्द पहचानना भारोपीय से तीन कारणों से कठिन है: चीनी के एक-अक्षरी शब्द पुरानी शब्द-रचना को ढक लेते हैं; चीनी दो हज़ार साल से भी ज़्यादा समय से अपने पड़ोसियों को बड़े पैमाने पर शब्द उधार देती आई है, इसलिए कोई समानता विरासत नहीं, उधार भी हो सकती है; और परिवार-वृक्ष ख़ुद विवादित है। पारंपरिक तस्वीर इसे एक ओर चीनी और दूसरी ओर \"तिब्बती-बर्मी\" में बाँटती है, पर किसी ने कभी यह नहीं दिखाया कि सारी ग़ैर-चीनी भाषाओं का अपना कोई साझा पूर्वज है; हो सकता है चीनी बस कई शाखाओं में से एक हो। सागार्ट की विवादित चीनी-ऑस्ट्रोनेशियाई परिकल्पना — कि चीनी और ऑस्ट्रोनेशियाई का पूर्वज साझा है — दिखाती है कि कितना कुछ अभी खुला है। इसे ऑस्ट्रो-ताई समझ लेना आसान है, जो एक अलग विद्वान का अलग दावा है: बेनेडिक्ट का 1942 का प्रस्ताव, जो ऑस्ट्रोनेशियाई को क्रा-दाई से जोड़ता है और जिसमें चीनी है ही नहीं।</p><p>एक मिथक साफ़ कर देना ठीक रहेगा: संख्याएँ उधार से बची हुई <em>नहीं</em> हैं, पूर्वी एशिया में तो बिल्कुल नहीं। थाई <em>hâa</em> \"पाँच\" और <em>sìi</em> \"चार\" चीनी 五 और 四 से लिए गए पुराने उधार हैं, और जापानी, कोरियाई और वियतनामी, तीनों अपनी देसी संख्याओं के साथ चीनी संख्याओं से भी गिनती करती हैं। तिब्बती <em>lnga</em> और बर्मी <em>ngā</em> को उधार के बजाय विरासत जैसा दिखाने वाली चीज़ उनकी बारीकियाँ हैं: तिब्बती <em>l-</em> और <em>b-</em> जैसे उपसर्ग, जिन्हें कोई चीनी उधार साथ नहीं लाता, और ऐसी ध्वनि-संगतियाँ जो सैकड़ों शब्दों में दोहराई जाती हैं। 2019 के दो कम्प्यूटेशनल अध्ययनों ने परिवार के साझा पूर्वज को लगभग 5,900 या 7,200 साल पहले रखा — यानी 五 को ལྔ से जोड़ने वाला धागा कोई छह-सात हज़ार साल लंबा है।</p>","ko-mid-eastguk-jeongun":"<h3>उस भाषा के लिए एक शब्दकोश जिसे कोई नहीं बोलता था</h3>\n<p>1447-1448 में जोसियन के राजा सेजोंग ने <strong>東國正韻</strong> (<em>तोंगुक चोंगुन</em>, “पूर्वी राज्य के शुद्ध तुक”) के संकलन की देखरेख की — छह खंडों का एक छंद-कोश, जो अक्षरों को 91 तुक-वर्गों और 23 आद्य व्यंजनों में छाँटता था और हर एक के लिए एक “शुद्ध” चीनी-कोरियाई पाठ निर्धारित करता था। तकनीकी रूप से यह ग्रंथ बेहद बारीक था, पर इसके तय किए पाठ कभी आम कोरियाई ज़बान पर नहीं चढ़े।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">👤 人 कई भाषाओं में देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko\">📍 मानचित्र पर कोरियाई पर केंद्रित करें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"37.57\" data-lng=\"126.98\" data-zoom=\"5\">🗺 सोल की ओर मानचित्र सरकाएँ</button>\n</div>\n\n<p>सेजोंग जिस समस्या को सुलझाना चाहते थे वह वास्तविक थी: 15वीं शताब्दी तक कोरियाई पाठक चीनी अक्षरों का उच्चारण ऐसे कर रहे थे जो समकालीन चीनी मानकों से बहुत दूर जा चुका था। हर हांजा — चीनी अक्षरों के लिए कोरियाई शब्द — पर एक चीनी-कोरियाई पाठ (한자음) चढ़ चुका था, जिसे चीनी में नहीं बल्कि कोरियाई में हुए सदियों के ध्वनि-परिवर्तन ने गढ़ा था। सेजोंग — वही राजा जिन्होंने अभी-अभी, 1443 में, हांगुल रचा था — मानते थे कि ये पाठ बिगड़ चुके हैं और इन्हें एक व्यवस्थित मानक पर लौटाना चाहिए। शिन सुक-जू की प्रस्तावना “ग़लतियाँ” गिनाती है: कोरियाई पाठों में घोष आद्य व्यंजन नहीं थे, महाप्राण और सादे <em>k</em> में घालमेल था, आरोही और प्रस्थायी स्वराघातों में भेद नहीं था, और जिन प्रवेशी अक्षरों को <em>-t</em> पर बंद होना चाहिए था, वे इसकी जगह <em>-l</em> पर ख़त्म होते थे।</p>\n\n<h3>एक आदर्श चीनी को कसौटी बनाना</h3>\n<p>विद्वान शिन सुक-जू के नेतृत्व में संकलनकर्ताओं ने अपने समय की मिंग बोली को आदर्श नहीं बनाया। उन्होंने शास्त्रीय छंद-कोश परंपरा से काम लिया — युआन-कालीन <strong>古今韻會擧要</strong> (<em>कूचिन यून्हुइ चूयाओ</em>, 1297), जिसे सेजोंग ने 1444 में नई लिपि में अनूदित कराया था, तथा मिंग-कालीन <strong>洪武正韻</strong> (<em>होंगवू चंगयून</em>, 1375), जिसके शीर्षक और स्वरूप की झलक तोंगुक चोंगुन में जानबूझकर रखी गई है। ये ग्रंथ जो दर्ज करते हैं, वह मध्यकालीन चीनी की छंद-परंपरा में जड़ें रखने वाला एक साहित्यिक मानक है, किसी समुदाय की जीती-जागती बोली नहीं। संकलनकर्ताओं ने उस व्यवस्था को मौजूदा कोरियाई पाठों के ढाँचे के साथ मिला दिया, और नतीजा एक ऐसा समझौता निकला जो न चीनी बोली से मेल खाता था, न कोरियाई से।</p>\n\n<p>नतीजा ऐसे उच्चारण थे जो:</p>\n<ul>\n  <li>घोष आद्य व्यंजन वापस लाते थे, जिन्हें दोहरे अक्षरों (ㄲ ㄸ ㅃ ㅉ ㅆ ㆅ) से लिखा जाता था — जबकि चीनी-कोरियाई में वे कभी थे ही नहीं</li>\n  <li>प्रवेशी स्वराघात वाले शब्दों (चीनी <em>-t</em>) के कोरियाई अंत्य <em>-l</em> की जगह <strong>ㅭ</strong> रखते थे — यानी ㄹ और कंठ्य-स्पर्श का अक्षर <strong>ㆆ</strong> (कोरियाई में <em>-p</em> और <em>-k</em> पहले से थे, इसलिए \"सुधार\" केवल <em>-t</em> का चाहिए था)</li>\n  <li>हर अक्षर को एक अंत्य वर्ण देते थे, खुले अक्षरों को भी: एक मूक ㅇ, या <em>-w</em> अंत के लिए ㅱ</li>\n  <li>चीनी छंद-कोशों की तरह आरोही और प्रस्थायी स्वराघातों को अलग-अलग चिह्नित करते थे</li>\n</ul>\n\n<p>यह व्यवस्था ख़ुद <em>हुनमिनजोंगुम</em> के कोरियाई अनुवाद में देखी जा सकती है, जहाँ हर अक्षर पर उसका निर्धारित पाठ लगा है; ㆆ अक्षर का वर्णन करने वाली एक ही पंक्ति में 字 'अक्षर' लिखा है ᄍᆞᆼ (आज 자), 發 'निकालना' 버ᇙ (आज 발), 喉 'गला' ᅘᅮᇢ (आज 후) — बस तीन अक्षरों में एक दोहरा आद्य व्यंजन, एक मूक अंत्य, एक ㅭ और एक ㅱ।</p>\n\n<h3>एक काल्पनिक ध्वनि के लिए विलुप्त अक्षर</h3>\n<p><strong>ㆆ</strong> और <strong>ㅭ</strong> अक्षर शायद तोंगुक चोंगुन की सबसे अटपटी विरासत हैं। 1443 में घोषित सेजोंग का हांगुल ध्वनियों के हिसाब से बेहद सटीक रचा गया था — हर अक्षर का आकार वाग्-अंगों की स्थिति दर्शाता माना जाता है। प्रवेशी <em>-t</em> के लिए संकलनकर्ताओं का गढ़ा <strong>ㅭ</strong> संयुक्ताक्षर साधारण कोरियाई की कोई ध्वनि लिखता ही नहीं था, और जिन पाठों के लिए बना था, उन्हीं के साथ लुप्त हो गया। ㆆ की उम्र थोड़ी लंबी रही: देशज कोरियाई में वह कुछ व्याकरणिक जगहों पर दिखता है, जैसे <em>योंगबिओचोंगा</em> (1447) में 先考ㆆ ᄠᅳᆮ 'मेरे स्वर्गीय पिता की इच्छा' या <em>हुनमिनजोंगुम</em> के अनुवाद में 니르고져 호ᇙ 배 '(वे) जो कहना चाहें'। पर उसका मुख्य काम तोंगुक चोंगुन के पाठ ही थे, और वह उन्हीं के साथ ग़ायब हो गया। (इसके विपरीत ㅸ देशज कोरियाई का असली अक्षर था — एक नर्म <em>b/v</em> जैसी ध्वनि, 셔ᄫᅳᆯ “सोल” और 고ᄫᅡ “सुंदर” जैसे शब्दों में; ध्वनि के <em>w</em> में बदल जाने से वह कुछ ही दशकों में अपने आप लुप्त हो गया, और इसीलिए आज के रूप 서울 और 고와 हैं।) हांगुल वर्णमाला का इतिहास पढ़ने वाले आधुनिक विद्वानों को उन अक्षरों का हिसाब देना पड़ता है जो उसी शब्दकोश के साथ मर गए जिसके लिए वे बने थे।</p>\n\n\n\n<h3>छोड़ा गया, पर खोया नहीं</h3>\n<p>सरकारी रहते हुए भी यह व्यवस्था ज़्यादातर छपे पन्नों पर ही जी — सबसे बढ़कर बौद्ध धर्मग्रंथों के हांगुल अनुवादों में — और 16वीं सदी की शुरुआत तक इसका इस्तेमाल पूरी तरह बंद हो चुका था। <em>हुनमोंगजाहो</em> (1527) के समय तक व्यावहारिक अक्षर-कोश बस वही उच्चारण दर्ज करने लगे जो कोरियाई वास्तव में प्रयोग करते थे। पर शब्दकोश की नाकामी भाषाविज्ञान के लिए ख़ज़ाना बन गई। उसकी बारीक हांगुल वर्तनियाँ ठीक-ठीक दिखाती हैं कि 15वीं सदी के कोरियाई विद्वानों ने चीनी छंद-कोशों की श्रेणियों को अपनी ध्वनियों पर कैसे बिठाया — और जिन \"ग़लतियों\" को वे सुधारने निकले थे, उनके ज़रिए वे यह भी दर्ज कर गए कि उस समय असली चीनी-कोरियाई कैसी सुनाई देती थी। ख़ुद मिंग चीनी के लिए बेहतर साक्षी उसकी बहन-परियोजना है, <em>होंगवू चंगयून योक्हुन</em> (1455), जिसने चीनी छंद-कोश को हांगुल में लिप्यंतरित किया।</p>","kokugo-versus-kango":"<h3>तीन शब्द-स्तर</h3>\n<p>जापानी शब्दभंडार को आम तौर पर तीन ऐतिहासिक परतों में बाँटकर देखा जाता है। <strong>和語</strong> (<em>वागो</em>, “जापानी भाषा के शब्द”) देशज केंद्र हैं — वे शब्द जो चीनी लेखन के आने से पहले ही जापानी में थे। (कुछ बहुत शुरुआती उधार इतने पहले घुस आए कि अब वागो ही लगते हैं: 梅 <em>उमे</em>, \"आलूबुख़ारा\", शायद भेस बदले हुए चीनी 梅 ही है।) <strong>漢語</strong> (<em>कांगो</em>, “हान भाषा के शब्द”) वे उधार शब्द हैं जो लगभग 5वीं शताब्दी से चीन से बौद्ध धर्म, कन्फ्यूशियसवाद और साक्षरता के साथ आए। <strong>外来語</strong> (<em>गाइराइगो</em>, “बाहर से आए शब्द”) बाद की उधार-परत हैं, ज़्यादातर पुर्तगाली, डच, अंग्रेज़ी, जर्मन और फ़्रांसीसी से, जिसकी शुरुआत 1543 के यूरोपीय संपर्क से हुई, जब एक पुर्तगाली जहाज़ पहली बार जापान पहुँचा।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"山\">🏔 山 (yama / san) कई भाषाओं में देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja_kun\">📍 ja_kun (कुन पाठ) पर केंद्रित करें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ja\">📍 चीनी-जापानी पाठ पर केंद्रित करें</button>\n</div>\n\n<h3>क्षेत्र के अनुसार वितरण</h3>\n<p>हर परत का दबदबा अलग-अलग क्षेत्र में है। सर्वेक्षणों के अनुसार बोलचाल में <strong>वागो 70% से अधिक</strong> होते हैं (परिवार, शरीर, मौसम और भाव के पुराने शब्द), जबकि समाचारपत्रों के गद्य में <strong>कांगो 70% पार कर जाते हैं</strong> — कुछ हद तक इसलिए कि मेइजी जापान ने पश्चिमी शब्द उधार लेने के बजाय कांगो समास गढ़कर आधुनिकीकरण किया। संतुलन खिसकता रहता है: जापान के राष्ट्रीय जापानी भाषा एवं भाषाविज्ञान संस्थान (NINJAL) के 1994 के एक पत्रिका-सर्वेक्षण में इस्तेमाल हुए अलग-अलग शब्दों में गाइराइगो 33.8% थे — कांगो (34.2%) के लगभग बराबर, और वागो (25.7%) से काफ़ी आगे। 電話 (<em>देनवा</em>, टेलीफ़ोन), 経済 (<em>केइज़ाइ</em>, अर्थव्यवस्था — एक पुराना चीनी पद, जिसे नया अर्थ दिया गया) और 哲学 (<em>तेत्सुगाकु</em>, दर्शन) जैसे शब्द मेइजी जापान में बने और बाद में चीन तथा कोरिया को निर्यात हुए। 哲学 का आविष्कारक भी ज्ञात है: विद्वान निशि आमाने, जिन्होंने 1874 में इसे तय किया — पहले 希哲学 आज़माने के बाद, जो यूनानी <em>philosophia</em>, \"ज्ञान की चाह\", का शाब्दिक अनुवाद था।</p>\n\n<p>तीनों स्तरों का अंतर “सुंदर” के लिए प्रयुक्त शब्दों में दिखता है:</p>\n<ul>\n  <li><strong>美しい</strong> (<em>उत्सुकुशी</em>) — वागो; आत्मीय और व्यक्तिगत। मान्योशू में इसका अर्थ अभी \"सुंदर\" था ही नहीं: कवि ओकुरा कहते हैं कि पत्नी और बच्चों को देखकर उन्हें वे <em>megushi utsukushi</em>, \"प्यारे और दुलारे\", लगते हैं। हेइआन काल में इसका अर्थ हुआ \"मनभावन, प्यारा\", ख़ासकर छोटी चीज़ों के लिए, और मध्ययुग के अंत की ओर जाकर ही यह प्रकृति और कला की सुंदरता तक फैला</li>\n  <li><strong>美麗</strong> (<em>बिरेइ</em>) — कांगो; औपचारिक, वस्तुनिष्ठ, साहित्यिक, गद्य और समालोचना में प्रयुक्त</li>\n  <li><strong>ビューティフル</strong> (<em>ब्यूतिफुरु</em>) — गाइराइगो; युवा, फ़ैशनेबल, प्रायः व्यंग्यात्मक या खिलंदड़</li>\n</ul>\n<p>ये तीनों विकल्प शैली में भी अलग हैं और इसमें भी कि किन शब्दों के साथ बैठते हैं। अंग्रेज़ी में भी जर्मैनिक, फ़्रांसीसी और लैटिन से विरासत में मिले ऐसे त्रिक हैं — <em>kingly, royal, regal</em>; <em>ask, question, interrogate</em>। जापानी लेखन में कांजी, हिरागाना या काताकाना के चुनाव से प्रायः शब्द का स्तर आँखों के सामने आ जाता है।</p>\n\n<h3>लेखन और शब्द-स्तर</h3>\n<p>जापानी वर्तनी से प्रायः देखते ही पता चल जाता है कि शब्द किस स्तर का है। <strong>हिरागाना</strong> और <strong>कुन पाठ वाले कांजी</strong> वागो का संकेत देते हैं। <strong>ओन पाठ वाले कांजी</strong> कांगो का। <strong>काताकाना</strong> गाइराइगो (और वैज्ञानिक नामों) का। इन परिपाटियों से पाठक को शब्द का अर्थ जानने से पहले ही उसके इतिहास का अंदाज़ा हो सकता है। <em>私は毎日コーヒーを飲む</em> (“मैं रोज़ कॉफ़ी पीता हूँ”) जैसे वाक्य में तीनों स्तर हैं: 私 (वागो), 毎日 (कांगो), コーヒー (डच <em>koffie</em> से गाइराइगो), 飲む (वागो)।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"天\">☀️ 天 (ame/sora/ten) सभी परतों में देखें</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.69\" data-zoom=\"5\">🗾 जापान की ओर मानचित्र सरकाएँ</button>\n</div>\n\n<h3>जब स्तर आपस में टकराते हैं</h3>\n<p>किनारों पर तीन-स्तरीय मॉडल टूट जाता है। अनेक शब्द संकर हैं: <strong>頭痛持ち</strong> (<em>ज़ुत्सू-मोची</em>, “जिसे अकसर सिरदर्द होता है”) कांगो 頭痛 को वागो 持ち से जोड़ता है। <strong>チョコレート工場</strong> (chokorēto kōjō) गाइराइगो (チョコレート, अंग्रेज़ी <em>chocolate</em> से) को कांगो (工場 <em>कोजो</em>, कारख़ाना) से मिलाता है। कुछ शब्द इतने लंबे समय से उधार हैं कि देशज लगते हैं — <em>ताबाको</em> (तंबाकू, पुर्तगाली <em>tabaco</em> से, लगभग 1600 में आया) उतना ही जापानी लगता है जितना <em>साकुरा</em>।</p>\n\n<p>मिश्रित रूपों का अपना नाम है: <strong>混種語</strong> (<em>कोन्शुगो</em>, \"मिश्रित प्रकार के शब्द\"), जो एक मानक आधुनिक शब्दकोश (<em>शिनसेन कोकुगो जितेन</em>, 2002) के सामान्य शब्दों का लगभग 8% हैं। <strong>テレビ局</strong> (<em>तेरेबि-क्योकु</em>, टीवी चैनल) अंग्रेज़ी गाइराइगो テレビ को कांगो 局 से जोड़ता है। ऐसे संकर आधुनिक जापानी में सामान्य हैं और दिखाते हैं कि इस त्रिविभाजन की दीवारें पक्की नहीं हैं।</p>\n\n<p>तीन-स्तरीय मॉडल एक सरलीकरण है, पर काम का। जो जापानी लेखक 美麗 या ビューティフル के बजाय 美しい चुनता है, वह केवल अर्थ ही नहीं, एक लिपि और आवाज़ का एक लहजा भी चुन रहा होता है।</p>","tang-empire-multilingual-coins":"<h3>एक सिक्का जो सभ्यताओं को पार कर गया</h3><p>621 ई. में तांग दरबार ने एक नया कांस्य सिक्का जारी किया जिस पर चार अक्षर उत्कीर्ण थे: <strong>開元通寶</strong> (Kāiyuán tōngbǎo)। इसका मोटा अर्थ है \"नई शुरुआत का प्रचलित ख़ज़ाना\": 開元 नए राजवंश का जयघोष था, किसी शासनकाल का नाम नहीं (सम्राट ज़ुआनज़ोंग का मशहूर कैयुआन शासनकाल तो 713 में जाकर शुरू हुआ)। लगभग तीन सौ वर्षों तक ढलता रहा यह सिक्का एशियाई इतिहास के सबसे दूर-दूर तक घूमे सिक्कों में से एक बन गया। समरकंद की सोग्दियाई टकसालों ने इसकी नक़ल की, शिनजियांग में इसके हज़ारों सिक्कों के ख़ज़ाने मिले हैं, और कैयुआन सिक्कों की लड़ियाँ नौवीं सदी के उस जहाज़ के साथ डूबीं जो चीन से मध्य-पूर्व जा रहा था और जावा सागर में बेलितुंग के पास टूट गया।</p><p>開元通寶 यह भी दिखाता है कि एक ही लिखा हुआ लेख अलग-अलग समुदायों में कैसे चल सकता था, जहाँ हर कोई उसे अपने ढंग से पढ़ता था। चीन के भीतर भी क्रम पर एकराय नहीं थी: ऊपर-नीचे-दाएँ-बाएँ की जगह चौकोर छेद के चारों ओर घूमते हुए पढ़ें तो लेख 開通元寶 बन जाता है — और यह ग़लत पाठ इतना आम था कि बाद के सिक्कों के \"युआनबाओ\" नाम इसी से प्रेरित हुए।</p><ul><li><strong>चीनी (मंदारिन):</strong> kāiyuán tōngbǎo — यह आधुनिक मानक उच्चारण है; तांग दरबार में तो यह <em>khoj ngjwon thuwng pawX</em> जैसा कुछ बोला जाता था (बैक्सटर की मध्यकालीन चीनी लिप्यंतरण पद्धति, जिसमें अंत का -X आरोही स्वराघात दर्शाता है)</li><li><strong>जापानी:</strong> kaigen tsūhō — यह चीनी-जापानी पठन अधिकतर कान-ऑन है, पर 通 का <em>tsū</em> कान-ऑन <em>tō</em> नहीं है (शब्दकोश इसे गो-ऑन या कान्योओन में गिनते हैं); जापान के अपने सबसे पुराने सिक्के — फ़ुहोनसेन और फिर 708 का वादो काइचिन — इसी के नमूने पर बने थे, सुलेख समेत</li><li><strong>कोरियाई:</strong> 개원통보 (gaewon tongbo) — चीनी-कोरियाई पठन, जो आज भी मुद्राशास्त्र के साहित्य में चलता है</li><li><strong>वियतनामी:</strong> khai nguyên thông bảo — तांग काल के उत्तरार्ध (8वीं-9वीं सदी) की चीनी ध्वनियों की विशेषताएँ बची हुई</li></ul><p>दूसरे अक्षर \"元\" में अंतर सबसे स्पष्ट है: मंदारिन में <em>yuán</em>, जापानी में <em>gen</em>, वियतनामी में <em>nguyên</em>। तांग अक्षर एक कंठ्य अनुनासिक से शुरू होता था (<em>ngjwon</em>): वियतनामी ने ng- को ज्यों का त्यों रखा, जापानी में उसका निशान g- के रूप में बचा, और मंदारिन उसे पूरी तरह खो बैठी — क्योंकि उधार लिए गए पठन जम गए, जबकि मंदारिन बदलती रही।</p><p>जापान के नारा प्रांत में एक मंदिर-पगोडा स्थल से लेकर रेशम मार्ग के मरूद्यानों और जावा सागर की तलहटी तक, सारे सिक्कों पर एक ही लेख है। अक्षर पासपोर्ट थे; उच्चारण स्थानीय लहजा।</p>","korean-eumhun-tradition":"<h3>दो-लेबल प्रणाली</h3><p>कोई कोरियाई हांजा पाठ्यपुस्तक खोलिए, एक ख़ास ढर्रा दिखेगा: हर अक्षर के साथ दो बातें दी जाती हैं। '水' अक्षर <strong>물 수 (水)</strong> के रूप में दिखाई देता है — पहले देशज कोरियाई शब्द <em>mul</em> (पानी), फिर चीनी-कोरियाई शब्दांश <em>su</em>। इस जोड़ी को <strong>音訓</strong> (음훈, eum-hun) कहते हैं: ध्वनि और अर्थ एक साथ।</p><p>यह आदत सदियों पुरानी है। कोरियाई बच्चे अक्षर <strong>千字文</strong> (हज़ार अक्षरों का ग्रंथ) से सीखते थे — 6वीं सदी की एक चीनी प्रारंभिक पुस्तक — और जब कोरियाई वर्णमाला आ गई (1446), तो प्रारंभिक पुस्तकें हर एक अक्षर का अर्थ-शब्द और ध्वनि, दोनों लिखकर बता सकती थीं। 1527 की <em>हुनमोंग जाहोए</em> 3,360 अक्षरों के लिए यही करती है; टिप्पणी-युक्त 千字文 का सबसे पुराना बचा संस्करण 1575 में ग्वांगजू में छपा, और सबसे मशहूर — सुलेखक हान सोक-बोंग के हाथ का लिखा — 1583 में। तब से यह ढाँचा मुश्किल से बदला है।</p><h3>मुख्य उदाहरण</h3><ul><li>山 = <strong>메 산</strong> (पर्वत) — <em>me</em> एक पुराना शब्द है जिसे आधुनिक कोरियाई ने वैसे तो छोड़कर ख़ुद 산 अपना लिया है; यह मुख्यतः यहीं बचा है, और 멧돼지 <em>metdwaeji</em> (\"पहाड़ी सूअर\", यानी जंगली सूअर) जैसे समासों में</li><li>人 = <strong>사람 인</strong> (व्यक्ति)</li><li>木 = <strong>나무 목</strong> (पेड़)</li></ul><h3>जापानी 訓読み से मूलभूत अंतर</h3><p>आम ग़लतफ़हमी यह है कि कोरियाई 훈 जापानी 訓読み की तरह काम करता है। फ़र्क़ बुनियादी है: जापानी में कुन-योमि रोज़ के लेखन में <em>सचमुच बरता जाने वाला</em> पाठ है, जबकि कोरियाई में 훈 बस <em>याद रखने का एक पढ़ाई वाला सहारा</em> है। आज कोई भी '水' लिखकर उसे <em>mul</em> पढ़ने की उम्मीद नहीं करता; आधुनिक कोरियाई पाठ में '水' चीनी-कोरियाई <em>su</em> ही पढ़ा जाता है।</p><p>हमेशा ऐसा नहीं था। अपनी भाषा को अक्षरों में लिखने वाले पुराने कोरियाई लिपिक (<em>इदू</em> और <em>ह्यांगछाल</em> प्रणालियों में) कुछ अक्षरों को उनके देशी अर्थ से पढ़ते थे — बहुत कुछ वैसे ही जैसे जापानी आज भी करती है। इसका एक निशान ख़ुद कोरियाई अक्षरों के नामों में बचा है, जो पहली बार उसी 1527 की पुस्तक में दर्ज हुए। ㄷ का नाम 池末 और ㅅ का 時衣 लिखते हुए पुस्तक के लेखक छ्वे सेजिन को <em>-geut</em> या <em>-ot</em> उच्चारण वाला कोई चीनी अक्षर नहीं मिला, इसलिए उन्होंने 末 \"अंत\" और 衣 \"कपड़े\" को उनके देशी अर्थ-शब्दों, 귿 और 옷, से पढ़ने के लिए चिह्नित कर दिया। इसीलिए ये अक्षर आज भी 디귿 <em>digeut</em> और 시옷 <em>siot</em> कहलाते हैं। 훈 एक स्मृति-आधार है, जीवित पाठ नहीं। वह सीखने वाले को बताता है: इस अमूर्त अक्षर का वही अर्थ है जो उस देशज शब्द का है जिसे आप पहले से जानते हैं। सीख लेने के बाद वास्तविक लेखन में अक्षर केवल अपनी चीनी-कोरियाई ध्वनि के साथ बरता जाता है। इस मायने में कोरियाई हांजा का इस्तेमाल उस ढंग के ज़्यादा क़रीब है जिससे यूरोपीय विद्यार्थी यूनानी या लैटिन मूल सीखते हैं: आप जानते हैं कि <em>aqua</em> का अर्थ पानी है, जिससे <em>aquifer</em> समझने में मदद मिलती है, पर अंग्रेज़ी वाक्य में आप <em>aqua</em> कभी नहीं लिखते।</p>\n<div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"ko\">📍 मानचित्र पर कोरियाई देखें</button></div>\n","cantonese-script-uniquely":"<h3>लिपि के भीतर एक लिपि</h3><p>जब हांगकांग के लोग फोन पर टाइप करते हैं या अखबार पढ़ते हैं, तो उन्हें ऐसे हान अक्षर मिलते हैं जिन्हें मानक लिखित चीनी शायद ही कभी बरतती है। ये कैंटोनीज़ के बोली-अक्षर (方言字) हैं, जो उन कैंटोनीज़ शब्दों और व्याकरण के लिए लिखे जाते हैं जिनका मंदारिन में कोई सीधा समकक्ष नहीं है। इनमें से कई किसी मिलती-जुलती ध्वनि वाले अक्षर में \"मुख\" मूलक 口 जोड़कर बनाए गए हैं — यह निशानी कि शब्द बोलचाल का है। कुछ के पीछे तो किस्सा भी है: 咩 <em>me1</em> \"क्या?\" जिस अक्षर से लिखा जाता है, वह असल में भेड़ के मिमियाने के लिए था (口 \"मुख\" + 羊 \"भेड़\")।</p><p>पाँच मुख्य अक्षर:</p><ul><li><strong>嘅 ge3</strong>: संबंध कारक/विशेषण कण (मंदारिन में 的 का उपयोग)</li><li><strong>喺 hai2</strong>: स्थानिक क्रिया (मंदारिन: 在)</li><li><strong>唔 m4</strong>: नकारात्मक उपसर्ग (मंदारिन: 不 / 沒)</li><li><strong>咁 gam3</strong>: 'इस तरह / ऐसे' (मंदारिन: 這樣)</li><li><strong>啲 di1</strong>: बहुवचन/आंशिक 'कुछ / थोड़ा' (मंदारिन: 一些)</li></ul><p>ये अक्षर टाइपो या स्लैंग संक्षिप्तीकरण नहीं हैं; पाँचों Unicode के मूल CJK Unified Ideographs ब्लॉक में दर्ज हैं और हांगकांग में रोज़ छपते हैं। एप्पल डेली (2021 में बंद होने पर मजबूर किए जाने तक) और ओरिएंटल डेली ने बरसों तक अपने स्तंभों, मनोरंजन और गपशप के पन्नों तथा घुड़दौड़ के पन्नों में 粵語白話文 छापा, जबकि समाचार पन्ने मानक लिखित चीनी में ही रहे और वहाँ कैंटोनीज़ मुख्यतः शीर्षकों और उद्धृत कथनों में झलकती थी; और हांगकांग वालों की सोशल-मीडिया पोस्टों और संदेशों में तो ये अक्षर हर जगह हैं। पर मुख्य भूमि चीन इनमें से ज़्यादातर को अपनी राष्ट्रीय मानक अक्षर-सूची से बाहर रखता है: 嘅, 喺, 咁 और 啲 通用规范汉字表 (2013) में कहीं नहीं हैं। 唔 अपवाद है — यह उसी सूची की द्वितीय श्रेणी तालिका में क्रमांक 4500 पर दर्ज है, पर मंदारिन के विस्मयादिबोधक ('हूँ') के रूप में, कैंटोनीज़ वाले नकारवाचक के रूप में नहीं। कुछ लोग इसमें एक बड़ा राजनीतिक और भाषाई तनाव देखते हैं: कैंटोनीज़ को कैंटोनीज़ में लिखना चुपचाप उस अनकही मान्यता को चुनौती देता है कि मंदारिन ही चीनी का सार्वभौमिक रूप है।</p><p>कैंटोनीज़ ने वे अंत्य स्पर्श -p, -t और -k भी बचाए रखे हैं जो मंदारिन खो चुकी है, और जब मध्यकालीन चीनी के घोष आद्य व्यंजन अघोष हुए, तब उसके स्वराघात ऊपरी और निचले रजिस्टरों में बँट गए। मंदारिन भी ऐसे ही बँटवारे से गुज़री, पर फिर उसने इसका बड़ा हिस्सा वापस समेटकर चार स्वराघात कर लिए, जबकि कैंटोनीज़ ने छह रखे (छोटे, स्पर्शांत अक्षरों को अलग गिनें तो नौ) — यही एक वजह है कि साझा शब्दावली भी दोनों के बीच पहचानी नहीं जाती। बहुत संभव है कि 嘅 परिमाण-शब्द 個 (मंदारिन gè) से विकसित हुआ, और 唔 m- वाले नकारवाचकों के उस प्राचीन परिवार का सदस्य है जिसमें 無 और 毋 आते हैं — वही परिवार जिसका सदस्य होक्किएन और हक्का का शब्दांशी नकारवाचक <em>m</em> है। ये आधुनिक आविष्कार नहीं, बल्कि सदियों पुराने मौखिक रूप हैं जिन्हें आख़िरकार अपना लिखित घर मिला है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"yue\">मानचित्र पर कैंटोनीज़ देखें</button></div>","shanghainese-ipa-wugniu":"<h3>जब तीन ध्वनियाँ एक बन जाती हैं, या तीन ही रहती हैं</h3><p>मंदारिन में, मध्यकालीन चीनी (中古漢語) की पुरानी तीन-तरफ़ा स्पर्श व्यंजन प्रणाली बहुत पहले ढह गई: <em>b-</em> जैसे सघोष आदि-व्यंजन अघोष वर्गों में मिल गए। लेकिन शंघाईनीज़ — वू (吳語) की प्रतिष्ठित बोली — ने कभी यह विलय पूरा नहीं किया। इसमें वह तीन-तरफ़ा भेद आज भी है जिसे मंदारिन सदियों पहले खो चुकी:</p><ul><li><strong>अघोष अल्पप्राण</strong>: 搭 <em>taq</em> (खड़ा करना, बनाना)</li><li><strong>सघोष</strong>: 踏 <em>daq</em> (पैर रखना)</li><li><strong>अघोष महाप्राण</strong>: 塔 <em>thaq</em> (पगोडा)</li></ul><p>एक सावधानी: शब्द की शुरुआत में ये \"सघोष\" स्पर्श अंग्रेज़ी वाले अर्थ में सघोष नहीं होते। ये सुनने में अघोष लगते हैं, पर इनमें एक साँस-भरी, मरमराती-सी आवाज़ होती है और ये हमेशा नीचे (\"हल्के\") स्वराघात के साथ आते हैं; पूरी तरह सघोष ये केवल दो स्वरों के बीच बनते हैं।</p><p>वुग्नियु (吳語拼音), जिसे वू भाषा प्रेमियों ने 2000 के दशक के मध्य की Wu Chinese Society योजना पर बनाया और जो 2010 के दशक में अपने मौजूदा रूप में तय हुआ, तीनों श्रृंखलाओं को केवल सादे ASCII में अलग-अलग रखता है: सघोष आदि-व्यंजनों के लिए <strong>b- / d- / g-</strong>, अघोष अल्पप्राण के लिए <em>p- / t- / k-</em>, और अघोष महाप्राण के लिए <em>ph- / th- / kh-</em>। हर श्रृंखला के लिए एक ही वर्तनी, कोई विशेष चिह्न नहीं।</p><p>ऐतिहासिक भाषाविज्ञान के लिए इसकी अहमियत यह है कि मध्यकालीन चीनी में ठीक यही तीन-तरफ़ा प्रणाली थी, और उसका पुनर्निर्माण कुछ हद तक इसीलिए हो पाता है कि शंघाईनीज़ जैसी भाषाओं में वह बची है। वू और शियांग के बाहर सिनिटिक भाषाओं में सघोष अवरोधक व्यंजन दुर्लभ हैं। कैंटोनीज़ ने केवल दो श्रेणियाँ रखीं (अघोष अल्पप्राण बनाम महाप्राण; पुरानी सघोष श्रृंखला अघोष हो गई, और सम व आरोही स्वराघातों में महाप्राण तथा बाक़ी जगह अल्पप्राण निकली)। होक्किएन में सघोष <em>b-</em> और <em>g-</em> हैं तो सही, पर वे पुराने अनुनासिकों से आए हैं (文 \"लेखन\" है <em>bûn</em>, मध्यकालीन चीनी <em>m-</em> से), मध्यकालीन चीनी के सघोष स्पर्शों से नहीं — वे वहाँ भी अघोष हो गए। दूसरा बड़ा अपवाद पुरानी शियांग है — हूनान में शुआंगफ़ेंग के आसपास की रूढ़िवादी लोऊ–शाओ बोलियाँ (लगभग 1.1 करोड़ वक्ता), जो सघोष श्रृंखला बनाए हुए हैं, जबकि नई शियांग में (जैसे छांगशा में) यह अघोष हो गई। वू और पुरानी शियांग ही मुख्य जीवित साक्षी हैं।</p><p>शंघाईनीज़ पर मंदारिन का भारी दबाव है। शंघाई की आबादी में से अब केवल लगभग आधे लोग इसमें बातचीत कर पाते हैं, और 2010 के एक सर्वेक्षण में 62.6% प्राथमिक-विद्यालय के बच्चों ने कहा कि घर पर उनकी पहली भाषा मंदारिन है। फिर भी पलटवार के कुछ संकेत हैं: 2013 से बसें शंघाईनीज़ में स्टॉप की घोषणा करती हैं, और 2017 में Apple की Siri ने भी इसे सीख लिया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"focus\" data-code=\"wuu\">मानचित्र पर वू क्षेत्र देखें</button></div>","pan-sinosphere-counting":"<h3>एक अक्षर, अनेक स्वर</h3><p>संख्या <strong>一</strong> (एक) सबसे सरल चीनी अक्षर है — एक अकेली क्षैतिज रेखा। फिर भी हान अक्षर जगत में इसका उच्चारण चौंकाने वाले ढंग से अलग-अलग है: मंदारिन में <em>yī</em>, कैंटोनीज़ में <em>yat</em>, होक्किएन/मिन में <em>it</em>, हक्का में <em>yit</em>, वू (शंघाई) में <em>iq</em>, जापानी में <em>ichi/itsu</em>, कोरियाई में <em>il</em>, वियतनामी में <em>nhất</em>। चीनी बोलियों को ये पाठ (उच्चारण) ज़्यादातर विरासत में मिले, क्योंकि वे मध्यकालीन चीनी की वंशज हैं, जो सुई और तांग राजवंशों की भाषा थी। (मिन पहले ही अलग हो गई थी, और उसके साहित्यिक पाठ, जैसे होक्किएन <em>it</em>, ख़ुद बाद की एक उधार परत हैं।) जापानी, कोरियाई और वियतनामी ने अपने पाठ उधार लिए, और हर उधार पाठ उस चीनी का जीवाश्म है जो उसे अपनाते समय बोली जा रही थी।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='一'>🔢 मानचित्र पर 一 दिखाएँ</button></div><h3>तुलनात्मक तालिका: 1–10</h3><ul><li><strong>मंदारिन (zh):</strong> yī, èr, sān, sì, wǔ, liù, qī, bā, jiǔ, shí</li><li><strong>कैंटोनीज़ (yue):</strong> yat, yi, saam, sei, ng, luk, chat, baat, gau, sap</li><li><strong>मिन नान (nan):</strong> it/tsi̍t, jī/nn̄g, sam/sann, sì, gōo, la̍k, tshit, peh, káu, si̍p/tsa̍p</li><li><strong>हक्का (hak):</strong> yit, ngi, sam, si, ng, liuk, chhit, pat, kiu, sip</li><li><strong>वू / शंघाई (wuu):</strong> iq, gni, se, sy, ng, loq, chiq, paq, cieu, zeq</li><li><strong>जापानी गो-ऑन 呉音:</strong> ichi, ni, san, shi, go, roku, shichi, hachi, ku, jū</li><li><strong>जापानी कान-ऑन 漢音:</strong> itsu, ji, san, shi, go, riku, shitsu, hatsu, kyū, shū</li><li><strong>कोरियाई (ko):</strong> il, i, sam, sa, o, yuk, chil, pal, gu, sip</li><li><strong>चीनी-वियतनामी (vi):</strong> nhất, nhị, tam, tứ, ngũ, lục, thất, bát, cửu, thập</li></ul><h3>जब 一 का उच्चारण <em>yī</em> नहीं होता</h3><p>मंदारिन में फ़ोन नंबर बोलिए और 1 <em>yāo</em> निकलता है, <em>yī</em> नहीं। यह 一 का कोई पाठ नहीं, बल्कि उसकी जगह आया दूसरा अक्षर है: जो अक्षर काम आता है वह 幺 है, शाब्दिक अर्थ 'सबसे छोटा', और शब्दकोश 一 को केवल एक ही उच्चारण <em>yī</em> देते हैं। कारण है साफ़ सुनाई देना: शोर भरी लाइन पर <em>yī</em> आसानी से <em>qī</em> (7) से गड्डमड्ड हो जाता है। चीनी सैन्य रेडियो इस विचार को पूरी हद तक ले जाता है। उसके 0–9 अंक हैं 洞 幺 两 三 四 五 六 拐 八 勾 (<em>dòng, yāo, liǎng, sān, sì, wǔ, liù, guǎi, bā, gōu</em>), जहाँ 0 है <em>dòng</em> \"छेद\" और 7 है <em>guǎi</em> \"मोड़\" — अंकों की आकृति के हिसाब से। यह आदत आम लोगों तक भी फैल गई है: आपातकालीन नंबर 110 और 119 सामान्यतः <em>yāo-yāo-líng</em> और <em>yāo-yāo-jiǔ</em> पढ़े जाते हैं। कैंटोनीज़ में यह चलन नहीं; वहाँ 幺 रोज़मर्रा में केवल 十三幺 में मिलता है, जो माजोंग के पत्तों का एक संयोजन है।</p><h3>थांग–कैंटोनीज़–वियतनामी का मेल</h3><p><strong>कैंटोनीज़</strong> और <strong>चीनी-वियतनामी</strong> थांग राजवंश (618–907) की ध्वनि-व्यवस्था को विशेष रूप से निकट से बचाए हुए हैं। दोनों वे अंत्य स्पर्श व्यंजन (-t, -k, -p) बनाए रखते हैं जिन्हें मंदारिन छोड़ चुकी है। तुलना कीजिए: कैंटोनीज़ <em>yat</em> / चीनी-वियतनामी <em>nhất</em> बनाम मंदारिन <em>yī</em>। कैंटोनीज़ को ये स्पर्श सीधे विरासत में मिले, और चीनी-वियतनामी पाठ मुख्यतः उत्तर-थांग काल की चीनी से उधार लिए गए, इसलिए दोनों ने वह बचाए रखा जो मध्यकालीन चीनी में था। जिन उत्तरी बोलियों से मंदारिन बनी, उन्होंने बाद में अपने ही ध्वनि-परिवर्तनों से वे स्पर्श व्यंजन खो दिए — 1324 की छंद-पुस्तक <em>चोंग-युआन यिन-यून</em> के समय तक पुराना -p/-t/-k भेद ढह चुका था और प्रवेशी स्वराघात वाले अक्षर बाकी स्वराघातों में बाँटे जा रहे थे।</p><h3>जापान की परतें</h3><p><strong>呉音 (गो-ऑन)</strong> — वू उच्चारण — 5वीं–6ठी सदी में कोरियाई प्रायद्वीप के रास्ते आए और दक्षिणी चीन की ध्वनि-व्यवस्था दर्शाते हैं। <strong>漢音 (कान-ऑन)</strong> — हान उच्चारण — 7वीं–9वीं सदी में जापानी दूतमंडलों ने सीधे थांग काल के छांगआन से लाए। तीसरी परत <strong>唐音 (तो-ऑन)</strong> ज़ेन बौद्ध धर्म के साथ सुंग और मिंग चीन से आई। जापानी गिनती ज़्यादातर गो-ऑन बरतती है (<em>ichi, ni, san, shi, go, roku, shichi, hachi, ku, jū</em>), रोज़मर्रा की बोली में दो अपवादों के साथ: 9 आम तौर पर <em>kyū</em> है, यानी कान-ऑन पाठ, और 4 व 7 की जगह अक्सर देशज <em>yon</em> और <em>nana</em> आ जाते हैं।</p><h3>मृत्यु की संख्या: 四 = 死</h3><p>जापानी में — और पूरे हान अक्षर जगत में — <strong>4</strong> पर एक छाया है। गो-ऑन में 四 <em>shi</em> पढ़ा जाता है, ठीक 死 (<em>shi</em>, मृत्यु) की तरह। यहीं से चार का वह डर (<strong>चतुर्भय</strong>) निकलता है जो दूर-दूर तक फैला है: जापान में कुछ अस्पताल और अपार्टमेंट-इमारतें 4 की संख्या छोड़ देती हैं, और 49 से भी बचा जाता है, क्योंकि <em>shi-ku</em> सुनने में \"दुख भोगो और मरो\" जैसा लगता है। कोरियाई 사 <em>sa</em> भी \"मृत्यु\" का समध्वनि है, और दक्षिण कोरिया की लिफ़्टों में कभी-कभी चौथी मंज़िल पर 4 की जगह \"F\" लिखा होता है। नोकिया ने 4000 शृंखला का कोई फ़ोन कभी नहीं निकाला। अपशकुन से बचने के लिए प्रायः देशज जापानी पाठ <em>yon</em> (देशज <em>yo</em> का बाद का विस्तारित रूप) चुना जाता है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='四'>💀 मानचित्र पर 四 (मृत्यु की संख्या) दिखाएँ</button><button type='button' class='trivia-action' data-action='focus' data-code='ja'>🗾 जापानी गो-ऑन पाठ देखें</button></div><h3>सांस्कृतिक अंक-विद्या</h3><p><strong>आठ</strong> (八, <em>bā</em>) चीनी संस्कृति की सबसे शुभ संख्या है, क्योंकि यह 發 (<em>fā</em>, समृद्धि) जैसी सुनाई देती है। <strong>छह</strong> निर्बाध प्रवाह का प्रतीक है (六六大順), और <strong>नौ</strong> 久 (<em>jiǔ</em>, दीर्घायु) जैसी लगती है। वहीं <strong>चार</strong> से हर जगह बचा जाता है — मंदारिन में 14 (<em>shísì</em>) सुनने में \"मर चुका है\" (是死 <em>shì sǐ</em>) जैसा लगता है और 4 से भी ज़्यादा अशुभ माना जाता है, और 74 से लोग इसलिए डरते हैं कि वह \"सचमुच मर गया\" जैसा सुनाई देता है।</p>","tea-tea-cha-cha":"<h3>उच्चारण के दो रास्ते</h3><p>चीनी अक्षर <strong>茶</strong> (chá) का अर्थ है चाय। इस शब्द के दो <em>क्षेत्रीय</em> उच्चारण अलग-अलग व्यापार जालों में गए, जिससे दूसरी भाषाओं में चाय के शब्दों के दो परिवार बने — <em>tea</em> प्रकार और <em>cha/chai</em> प्रकार। <em>World Atlas of Language Structures</em> की 230 भाषाओं के नमूने में 110 भाषाएँ <em>cha</em>-प्रकार का शब्द बरतती हैं, 84 <em>te</em>-प्रकार का, और केवल 36 कुछ बिल्कुल अलग।</p><p>दोनों एक ही शब्द से निकले हैं। मध्यकालीन चीनी में 茶 एक स्पर्श-जैसी मूर्धन्य ध्वनि <em>ɖ-</em> से शुरू होता था। ज़्यादातर चीनी बोलियों ने बाद में इस ध्वनि को स्पर्श-संघर्षी बना दिया, जिससे <em>ch-</em> बना; फ़ुजियान की मिन बोलियों ने सादा <em>t-</em> बचाए रखा, जैसा वे इस वर्ग के बहुत-से शब्दों में करती हैं (होक्किएन 豬 <em>ti</em> \"सूअर\", 竹 <em>tek</em> \"बाँस\", जबकि मंदारिन में <em>zhū</em>, <em>zhú</em>)। यानी \"tea\" कोई अलग शब्द नहीं है; उसमें बस व्यंजन ज़्यादा पुराने ढंग का है।</p><h3>समुद्री मार्ग</h3><p>तटीय फ़ुजियान प्रांत के <strong>मिन बोली-समूह</strong> में, जिसमें अमॉय (शियामेन) बंदरगाह भी आता है, 茶 का उच्चारण लगभग <em>t&ecirc;</em> था। 17वीं सदी की शुरुआत में जब VOC के डच व्यापारियों ने होक्किएन व्यापारियों और अपने साम्राज्य के मलय-भाषी बंदरगाहों के ज़रिए चाय का व्यापार शुरू किया, तो उन्होंने यह शब्द <strong>thee</strong> के रूप में अपनाया (सीधे होक्किएन <em>t&ecirc;</em> से या मलय <em>teh</em> के रास्ते — इस पर अब भी बहस है)। डच से यह शब्द तेज़ी से फैला:</p><ul><li><strong>अंग्रेज़ी:</strong> tea (डच <em>thee</em> से, लगभग 1650 का दशक)</li><li><strong>फ्रांसीसी:</strong> th&eacute;</li><li><strong>जर्मन:</strong> Tee</li><li><strong>स्पेनिश:</strong> t&eacute;</li><li><strong>इतालवी:</strong> t&egrave;</li><li><strong>मलय / इंडोनेशियाई:</strong> teh (होक्किएन बंदरगाहों से सीधे)</li><li><strong>तमिल:</strong> t&#275;n&#299;r (शाब्दिक अर्थ \"चाय-पानी\")</li><li><strong>अफ़्रीकान्स:</strong> tee</li></ul><p>ये हैं <strong>समुद्री मार्ग वाले देश</strong>, जिनके यहाँ चाय का शब्द दक्षिणी चीन के मिन-भाषी तट से जहाज़ों पर आया।</p><h3>थल मार्ग</h3><p>मंदारिन और ज़्यादातर दूसरी चीनी बोलियों में इस अक्षर का आदि व्यंजन <em>ch</em> जैसा है — मंदारिन <em>chá</em>, कैंटोनीज़ <em>caa4</em>। चीन का उत्तरी, मंदारिन-भाषी छोर यही रूप <strong>रेशम मार्ग</strong> और चाय-घोड़ा मार्गों से ज़मीन के रास्ते भेजता था, और वहाँ से यह कारवाँ व्यापारियों और रूसी व्यापारियों के ज़रिए दुनिया तक पहुँचा। रास्ते में फ़ारसी में इसके पीछे <em>-y</em> जुड़ गया, इसीलिए इनमें से इतने सारे रूप सादे <em>cha</em> नहीं, बल्कि <em>chai</em> हैं:</p><ul><li><strong>रूसी:</strong> &#1095;&#1072;&#1081; (chay)</li><li><strong>तुर्की:</strong> &ccedil;ay</li><li><strong>फ़ारसी:</strong> &#1670;&#1575;&#1740; (ch&#257;y)</li><li><strong>अरबी:</strong> &#1588;&#1575;&#1610; (sh&#257;y)</li><li><strong>हिंदी / उर्दू:</strong> &#2330;&#2366;&#2351; (ch&#257;y)</li><li><strong>स्वाहिली:</strong> chai</li><li><strong>यूनानी:</strong> &#964;&#963;&#940;&#953; (tsai)</li><li><strong>जापानी:</strong> &#12362;&#33590; (o-cha), सीधे चीन से; बाद का एक पाठ <em>sa</em> 喫茶店 <em>kissaten</em> \"कैफ़े\" में बचा है</li><li><strong>कोरियाई:</strong> 차 (cha), सीधे चीन से</li><li><strong>पुर्तगाली:</strong> ch&aacute; (मकाऊ के रास्ते, समुद्री देशों में मशहूर अपवाद)</li></ul><p><strong>पुर्तगाली</strong> को अक्सर अपवाद के तौर पर गिनाया जाता है: समुद्री देश होकर भी उसका शब्द <em>ch&aacute;</em> है, क्योंकि चाय से उसका पहला संपर्क मकाऊ के ज़रिए हुआ, जो कैंटोनीज़-भाषी बंदरगाह था, डच-होक्किएन जाल के ज़रिए नहीं। दरअसल पुर्तगाली रूप ही अंग्रेज़ी में पहले पहुँचा: <em>cha</em> 1590 के दशक में दर्ज है, <em>tea</em> से दशकों पहले, और ब्रिटिश बोलचाल के \"a cup of char\" में आज भी ज़िंदा है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='24.5' data-lng='118.1' data-zoom='5'>🚢 फ़ूज्यान तट पर जाएं (समुद्री मार्ग का उद्गम)</button><button type='button' class='trivia-action' data-action='focus' data-code='nan'>📍 नक्शे पर मिन नान देखें</button></div>\n\n<h3>भौगोलिक वितरण</h3><p>मोटे तौर पर यह बँटवारा समुद्री व्यापार से जुड़े <em>tea / thé / Tee / té</em> रूपों को उन <em>chai / chay / cha / çay</em> रूपों से अलग करता है जो ज़मीनी रास्तों और चीन से दूसरे संपर्कों से जुड़े हैं। इसमें उन कई शुरुआती आधुनिक रास्तों की छाप है जिनसे चाय और उसका नाम फैले।</p>\n\n<h3>यह विभाजन क्या दर्ज करता है</h3><p>यह विभाजन एक ऐसा बोली-भेद दर्ज करता है जिसने व्यापार के साथ सफ़र किया। ज़्यादातर भाषाओं में चाय के शब्द का पहला व्यंजन काफ़ी भरोसे से बता देता है कि शब्द फ़ुजियान तट के होक्किएन-भाषियों से शुरू हुई व्यापार-शृंखला से उतरा, या चीन से किसी और रास्ते आया।</p>","oracle-bone-script":"<p>चीनी लिपि का एक अविच्छिन्न अभिलेख <strong>甲骨文 (jiǎgǔwén)</strong> तक पहुँचता है — «अस्थि-भविष्यवाणी लिपि», वे अभिलेख जिन्हें उत्तर-शांग दरबार के भविष्यवक्ताओं ने लगभग १२५० से १०५० ईसा पूर्व के बीच बैलों की कंधे की हड्डियों और कछुओं के उदर-कवच पर उकेरा। लगभग १,५०,००० अंकित टुकड़े मिले हैं, जिनमें से अधिकांश यिनशू (殷墟) से हैं, जो शांग की अंतिम राजधानी थी, आज के हेनान प्रांत के अन्यांग के पास। ये पाठ दरबारी अभिलेख हैं: पूर्वजों और देवताओं से पूछे गए प्रश्न — फ़सल, युद्ध, प्रसव, राजा के दाँत के दर्द, क्या वर्षा होगी, और क्या आने वाला दस-दिनी सप्ताह बिना किसी विपत्ति के बीतेगा, इनके बारे में।</p><p>यह लिपि आग से भविष्य बाँचने की प्रथा से निकली थी। भविष्यवक्ता हड्डी या कवच के पीछे तैयार किए गए एक गड्ढे में तपी हुई नोक तब तक दबाता जब तक वह तीखी चटक के साथ न फट जाती, और दरार जिस आकृति में चलती उसे पूर्वजों के उत्तर के रूप में पढ़ा जाता। अक्षर <em>卜</em> (bǔ, «भविष्यवाणी करना») उसी दरार का चित्र है। उसके बगल में प्रश्न उकेरा जाता। कभी-कभी यह भी उकेरा जाता कि राजा ने दरार का क्या अर्थ लगाया और असल में हुआ क्या।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='36.10' data-lng='114.35' data-zoom='6'>🌍 अन्यांग (यिनशू) की ओर जाएँ</button><button type='button' class='trivia-action' data-action='setchar' data-char='牛'>मानचित्र पर 牛 (बैल) दिखाएँ</button></div><p>हड्डियाँ तीन हज़ार साल तक खोई रहीं और फिर दो बार मिलीं। पीढ़ियों तक अन्यांग के आसपास के किसान इन्हें खोदकर निकालते और औषधि-विक्रेताओं को <em>lónggǔ</em> (龍骨), «ड्रैगन-हड्डियों» के रूप में बेच देते, ताकि इन्हें पीसकर दवा बनाई जाए। १८९९ में बीजिंग की शाही अकादमी के कुलपति वांग यीरोंग (王懿榮) ने अपने ही संग्रह की हड्डियों पर के चिह्नों को चीनी लेखन का एक प्राचीन रूप पहचाना। अगले ही वर्ष उनका देहांत हो गया; उनके मित्र ल्यू अ (劉鶚) ने १९०३ में पहला मुद्रित संग्रह, «तिएयुन त्सांगगुई» (鐵雲藏龜), प्रकाशित किया — १,०५८ छापें, जिनमें से ल्यू ने ३४ अक्षर सही-सही पहचाने। लुओ जेनयू ने हड्डियों का स्रोत अन्यांग तक खोज निकाला और ३०,००० से अधिक एकत्र कीं; वे, वांग गुओवेई, तुंग त्सुओबिन और कुओ मोरुओ अस्थि-भविष्यवाणी अध्ययन के «चार भवन» (四堂) कहलाए — उनके उपनामों में आए भवन-नामों के आधार पर।</p><p>यह लिपि बहुत बड़ी है और अभी अधूरी ही पढ़ी गई है। समूचे संग्रह में ३०,००० से अधिक भिन्न आलेखीय रूप सूचीबद्ध किए गए हैं, जो संभवतः लगभग ४,००० अलग-अलग अक्षरों को निरूपित करते हैं; इनमें से विद्वान विश्वास के साथ १,५०० से २,००० पढ़ सकते हैं। बाक़ी में नाम, स्थान-नाम और ऐसे शब्द हैं जिनका बाद की चीनी तक कोई सिलसिला नहीं मिला। नवंबर २०१६ में अन्यांग स्थित चीनी लेखन के राष्ट्रीय संग्रहालय ने किसी भी एक अपठित अक्षर के विश्वसनीय प्रथम पाठ के लिए १,००,००० युआन — लगभग १५,००० अमेरिकी डॉलर — और किसी विवादित अक्षर के नए पाठ के लिए उसका आधा देने की घोषणा की। अक्तूबर २०१७ में ये अभिलेख यूनेस्को के «मेमोरी ऑफ़ द वर्ल्ड» रजिस्टर में शामिल किए गए। फिर भी, तीन हज़ार साल पहले किसी शांग भविष्यवक्ता ने अग्नि-दरार के बगल में जो चिह्न उकेरे, उनमें से आधे या उससे भी अधिक का अब तक किसी शब्द से मिलान नहीं हो सका है।</p>","kana-genesis":"<h3>उधार लिए गए संकेताक्षरों के एक ढेर से दो लिपियाँ</h3><p>जापानी में दो ध्वन्यात्मक अक्षरमालाएँ हैं, हिरागाना और काताकाना, जिनमें वही 46 मूल ध्वनियाँ हैं पर हर एक का आकार बिलकुल अलग है। दोनों एक ही खंड से काटी गई थीं: <em>मान्योगाना</em>, यानी जापानी अक्षरों को केवल ध्वनि के आधार पर चुने गए चीनी संकेताक्षरों से लिखने की प्रथा। <em>मान्योशू</em> संकलन में (759 के बाद संकलित) अक्षर <em>a</em> को 安 या 阿 लिखा जा सकता था, और <em>i</em> को 伊 या 以। किसी छोटी-सी कविता को ध्वन्यात्मक रूप से लिखने भर के लिए पाठक को दर्जनों संकेताक्षर जानने पड़ते थे। दोनों कानाएँ इसी लिखावट को छोटा करने के दो अलग-अलग तरीके हैं।</p><p>हिरागाना ने पूरा संकेताक्षर लिया और उसके स्ट्रोक आपस में मिला दिए। लेखकों ने मान्योगाना को 草書 (<em>सोशो</em>) में लिखा, जो चीनी सुलेख की सबसे तेज़ घसीट शैली है, और कूँची स्ट्रोकों को घोलती गई, यहाँ तक कि केवल एक बहती रूपरेखा बची रह गई। 安 (<em>an</em>), जो <em>a</em> के लिए प्रयुक्त होता था, पिघलकर あ बन गया; 以 जो <em>i</em> के लिए था, い बन गया; 宇 पिघलकर う; 衣 पिघलकर え; 於 पिघलकर お बन गया। ये रूप लगभग 800 ई. के आसपास के माने जा सकते हैं।</p><p>काताकाना ने इसके उलट किया: उसने एक टुकड़ा रखा और बाकी छोड़ दिया। स्रोत वही मान्योगाना का ढेर था, पर चौकोर 楷書 (<em>काइशो</em>) शैली में लिखा हुआ, और सरलीकरण का तरीका था किसी एक घटक को ले लेना। ア, 阿 का बायाँ भाग है (阝 मूलांश); イ, 伊 का बायाँ भाग; ウ, 宇 का शीर्ष 宀; エ, 江 से; オ, 於 से; カ, 加 का बायाँ भाग है। जो बचता है वह एक अंश है, इसीलिए काताकाना कोणदार दिखती है जबकि हिरागाना गोल।</p><p>दोनों लिपियाँ इस आधार पर बँटीं कि उन्हें किसने और किसलिए इस्तेमाल किया। काताकाना को 9वीं सदी में नारा और उसके आसपास के बौद्ध भिक्षुओं ने गढ़ा, जिन्हें शास्त्रीय चीनी को जापानी में ज़ोर से पढ़ना होता था। वे चीनी सूत्र के स्तंभों के बीच की खाली जगहों में नन्हे अक्षर-चिह्न और व्याकरणिक कण टाँक देते थे — <em>कानबुन कुंदोकु</em> की <em>कुंतेन</em> टिप्पणियाँ — और हाशिए में ठुँसे किसी संकेत को छोटा और तेज़ होना ज़रूरी था, इसलिए पूरे घसीट रूप से बेहतर एक टुकड़ा रहा। सदियों तक काताकाना पुरुष विद्वत्ता की लिपि बनी रही: बौद्ध और कन्फ्यूशियसी टीकाएँ और सरकारी टिप्पणियाँ।</p><p>हिरागाना दूसरी राह गई, हेइआन दरबार की स्त्रियों के हाथों में, जिन्हें औपचारिक रूप से चीनी नहीं सिखाई जाती थी और जो राष्ट्रभाषा को घसीट रूपों में लिखती थीं। इसे 女手 (<em>ओन्नादे</em>) कहा गया, यानी \"स्त्रियों का हाथ\"। हेइआन साहित्य की प्रमुख कृतियाँ इसी में हैं: की नो त्सुरायुकी की <em>तोसा निक्की</em> (935) पूरी तरह काना में लिखी है, जिसमें त्सुरायुकी — एक पुरुष — एक स्त्री की आवाज़ में आरंभ करते हैं ताकि वे इसका प्रयोग कर सकें; मुरासाकी शिकिबु की <em>गेन्जी की कथा</em> (लगभग 1008) लगभग पूरी तरह हिरागाना और देशज शब्दावली में है।</p><p>हज़ार साल तक हर ध्वनि के लिए कोई एक सही आकार नहीं था। वही अक्षर कई अलग-अलग घसीट संकेताक्षरों से लिखा जा सकता था — <em>ha</em> 波, 者, या 八 से — और ये सब सामान्य थे। इन विविध रूपों को 変体仮名 (<em>हेनताइगाना</em>) कहते हैं। आज जो \"हर ध्वनि के लिए एक चिह्न\" वाला समुच्चय पढ़ाया जाता है, वह 1900 में प्राथमिक विद्यालयों के लिए बने एक सरकारी नियम से ही तय हुआ, जिसने हर अक्षर के लिए एक हिरागाना चुनी और बाकी को विदा कर दिया; छोड़ दिए गए आकार आज भी पुरानी दुकानों के साइनबोर्डों और सोबा-रेस्तराँ के परदों पर दिख जाते हैं।</p><p>हेइआन काल के उस विभाजन से निकला काम का बँटवारा आज भी चल रहा है। हिरागाना व्याकरण और देशज शब्द लिखती है; काताकाना उधार के शब्द, विदेशी नाम, ध्वन्यानुकरण और ज़ोर लिखती है। एक ही वाक्य में प्रायः कांजी, हिरागाना और काताकाना साथ-साथ चलते हैं। ये तीनों आठवीं सदी के उसी एक निर्णय की उपज हैं कि जापानी को चीनी संकेताक्षरों से लिखा जाए। हर एक ने संकेताक्षर का जो हिस्सा रखना चुना, उसी से वे एक-दूसरे से अलग बनी रहीं।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='35.01' data-lng='135.77' data-zoom='6'>🌍 हेइआन-क्यो (क्योतो) पर जाएँ</button></div>","bopomofo-zhuyin":"<p>नाम <strong>बोपोमोफ़ो</strong> दरअसल इसके पहले चार चिह्नों को ज़ोर से पढ़ने भर से बना है: <strong>ㄅ ㄆ ㄇ ㄈ</strong> (<em>b p m f</em>)। यह एक ध्वन्यात्मक लिपि है जो चीनी वर्णों की जगह नहीं लेती, बल्कि उनका उच्चारण दर्शाती है: इसके ३७ चिह्नों में २१ आरंभिक व्यंजन, ३ मध्यवर्ती ध्वनियाँ और ㄢ (<em>an</em>) व ㄤ (<em>ang</em>) जैसी १३ तुकांत ध्वनियाँ हैं, और पाँच स्वराघात-चिह्न टोन बताते हैं। इसकी ख़ास बात यह है कि इनमें से एक भी चिह्न लैटिन अक्षर नहीं। हर एक किसी चीनी वर्ण से लिया गया है — अक्सर किसी प्राचीन रूप का एक अवयव, कभी-कभी पूरा का पूरा कोई सरल वर्ण, जैसे 一 (ㄧ) या 丫 (ㄚ)।</p><h3>एक आयोग, तीन खेमे, दो महीने</h3><p>दिसंबर १९१२ में नवगठित चीनी गणराज्य ने उच्चारण-एकीकरण आयोग (讀音統一會) की स्थापना की। चवालीस प्रतिनिधि १५ फ़रवरी १९१३ को वू ज़ीहुई की अध्यक्षता में बीजिंग में मिले, और तीन खेमों में बँट गए: एक चाहता था कि पूरे चीनी वर्णों को ही ध्वनि-सूचक के रूप में प्रयोग किया जाए, एक लैटिन अक्षर चाहता था, और एक नए गढ़े गए चिह्न चाहता था। आयोग के २२ मई १९१३ को समाप्त होने से पहले वे लगभग दो महीने बहस करते रहे। जिस रूपरेखा पर वे सहमत हुए उसने उन १५ चिह्नों को लिया जिन्हें विद्वान ज़ांग बिंगलिन ने <em>ज़ुआनशू</em> (मुद्रा-लिपि) में बनाया था और जिन्हें 記音字母, यानी \"ध्वनि अंकित करने वाले अक्षर\" कहा था।</p><h3>आकृतियाँ कहाँ से आती हैं</h3><p>हर चिह्न किसी ऐसे वर्ण का छँटा हुआ रूप है जिसके अपने उच्चारण में वही ध्वनि मौजूद है — व्यंजन के लिए आरंभ में, अंत्य ध्वनि के लिए तुकांत में; इसीलिए ㄢ (<em>an</em>) प्राचीन वर्ण 𢎘 (<em>hàn</em>) से आया है। ㄅ (<em>b</em>) है 勹, जो 包 (<em>bāo</em>) का ऊपरी भाग है। ㄆ (<em>p</em>) है 攵, जो 攴 (<em>pū</em>) का एक रूपांतर है। ㄇ (<em>m</em>) है 冂, जो \"ढक्कन\" वाले मूल-अंश 冖 (<em>mì</em>) का प्राचीन रूप है। ㄈ (<em>f</em>) है 匚 (<em>fāng</em>), \"खुले बक्से\" वाला मूल-अंश। सिद्धांत है अक्रोफ़ोनी — यानी चिह्न का मान उस वस्तु के आरंभ से लेना जिससे वह बनाया गया है — ठीक वही प्रक्रिया जिसने एक बैल के सिर को यूनानी <em>अल्फ़ा</em> में बदल दिया।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='39.90' data-lng='116.40' data-zoom='5'>🌍 बीजिंग, १९१३ की ओर चलें</button></div><h3>\"अक्षरों\" से \"चिह्नों\" तक</h3><p>इस लिपि की घोषणा २३ नवंबर १९१८ को 注音字母 (<em>Zhuyin Zimu</em>), यानी \"ध्वनि-अंकन करने वाले अक्षर\" के रूप में हुई। अप्रैल १९३० में इसका नाम बदलकर 注音符號 (<em>Zhuyin Fuhao</em>), यानी \"ध्वनि-अंकन करने वाले चिह्न\" कर दिया गया। एक शब्द के इस बदलाव का महत्व था: 字母 (\"अक्षर\") एक ऐसी वर्णमाला का संकेत देता था जो किसी दिन अपने बल पर खड़ी होकर वर्णों को किनारे धकेल सकती थी, जबकि \"चिह्न\" ने इसे वापस इसके स्थान पर रख दिया — वर्णों को पढ़ने में सहायक के रूप में, कभी उनका विकल्प नहीं। इसी क्रम में बोली-विशेष ध्वनियों के तीन चिह्न — ㄪ (<em>v</em>), ㄫ (<em>ng</em>) और ㄬ (<em>gn</em>) — मानक प्रयोग से हटा दिए गए, हालाँकि तीनों आज भी यूनिकोड ब्लॉक में मौजूद हैं।</p><h3>जलडमरूमध्य के आर-पार एक विभाजन</h3><p>११ फ़रवरी १९५८ को पहली राष्ट्रीय जन कांग्रेस ने हान्यू पिनयिन अपनाया, जो झोउ योउगुआंग के नेतृत्व वाली टीम द्वारा विकसित लैटिन-आधारित प्रणाली है। मुख्यभूमि के विद्यालय इसी पर चले गए, और आज बीजिंग में पढ़ना सीखता बच्चा <em>b p m f</em> से रोमन अक्षरों में मिलता है। ताइवान ने मूल रूप को बनाए रखा। ताइवानी प्राथमिक विद्यालयों में ㄅㄆㄇㄈ आज भी वह पहली चीज़ है जो कोई पाठक सीखता है। ये चिह्न वर्णों के बगल में छोटी टिप्पणियों के रूप में छपे होते हैं। फ़ोन या कीबोर्ड पर चीनी टाइप करने का सबसे आम तरीका भी यही है। इन्हीं चिह्नों को अतिरिक्त आकृतियों के साथ विस्तारित करके ताइवानी होक्किएन और हक्का लिखी जाती है। प्राचीन वर्णों से इन आकृतियों को निकाले सौ से कुछ ज़्यादा वर्ष हो चुके हैं। फिर भी ताइवानी बच्चा सबसे पहले इन्हीं को सीखता है, और जिन वर्णों का उच्चारण ये बताती हैं, उनसे वह महीनों बाद मिलता है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='25.03' data-lng='121.56' data-zoom='6'>🌍 ताइपेई की ओर चलें</button></div>","kangxi-214-radicals":"<h3>एक अक्षर, एक दराज़</h3><p>कांगशी शब्दकोश (康熙字典) बनाने का आदेश कांगशी सम्राट ने 1710 में दिया और यह 1716 में प्रकाशित हुआ। इसके पहले दो संपादक, झांग यूशू (1642–1711) और चेन तिंगजिंग (1639–1712), दोनों नियुक्ति के दो वर्ष के भीतर चल बसे, और हानलिन अकादमी के विद्वानों ने काम पूरा किया। इसमें लगभग 47,035 अक्षर 214 दराज़ों में रखे गए। हर अक्षर ठीक एक दराज़ का होता था। दराज़ की पहचान एक साझा आकृतिगत घटक से होती थी, जो उस अक्षर का <strong>部首 (bùshǒu, खंड-शीर्ष, यानी रैडिकल)</strong> कहलाता है। फिर उस दराज़ के भीतर अक्षर की जगह एक दूसरी संख्या तय करती थी: रैडिकल घटाने के बाद बचे स्ट्रोक।</p><h3>रैडिकल और शेष</h3><p>校 ढूँढ़ने के लिए आप उसका रैडिकल 木 (पेड़, रैडिकल 75) पहचानते हैं, बचे स्ट्रोक गिनते हैं — 交 छह जोड़ता है — और लकड़ी +6 वाले खंड पर पहुँचते हैं। अनुक्रमणिका यांत्रिक है, पर दराज़ें बेहद असमान हैं। रैडिकल 140 艸 (घास) में सबसे ज़्यादा, 1,902 अक्षर हैं; रैडिकल 85 水 (पानी) में 1,595 और रैडिकल 75 木 में 1,369, जबकि रैडिकल 138 艮 में सिर्फ़ 5। ख़ुद रैडिकल एक स्ट्रोक (一, रैडिकल 1) से लेकर सत्रह स्ट्रोक (龠, एक बाँसुरी, रैडिकल 214) तक के हैं, और उनकी माध्यिका पाँच है।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='setchar' data-char='水'>🔡 水 दिखाएँ (रैडिकल 85)</button><button type='button' class='trivia-action' data-action='panto' data-lat='39.92' data-lng='116.39' data-zoom='4'>🌍 बीजिंग पर जाएँ</button></div><h3>कौन-सा हिस्सा गिना जाए</h3><p>यह व्यवस्था तभी काम करती है जब आपको पहले से पता हो कि कौन-सा घटक रैडिकल है, और वह हमेशा सबसे स्पष्ट वाला नहीं होता। 聞 (सुनना) को 耳 (कान, रैडिकल 128) के अंतर्गत रखा गया है, न कि उसे घेरने वाले 門 (द्वार) के अंतर्गत। 問 (पूछना) 口 (मुँह) के अंतर्गत जाता है, जबकि 間 (अंतराल) 門 के अंतर्गत। जिस अक्षर में कोई स्पष्ट अर्थसूचक हिस्सा नहीं होता, उसे आकृति के आधार पर रैडिकल सौंपा जाता है, इसलिए किसी छपे शब्दकोश में 甚 या 乃 खोज पाना इस बात की छोटी-सी परीक्षा है कि यह परिपाटी आपके हाथ बैठी है या नहीं।</p><h3>540 से 214 तक</h3><p>रैडिकल छिंग राजवंश का आविष्कार नहीं था। शू शेन का <em>शुओवेन जिएज़ी</em> (說文解字), जो 121 ईस्वी में हान दरबार को प्रस्तुत किया गया, पहले ही 9,353 अक्षरों को 540 खंड-शीर्षों के अंतर्गत छाँट चुका था — एक संख्या जिसे बाद के पाठकों ने 6 × 9 × 10, यानी एक ब्रह्मांडीय संख्या, के रूप में समझाया। 540 बहुत ज़्यादा और बहुत बारीक थे; कुछ के नीचे केवल एक ही अक्षर था। 1615 में मेई यिंगज़ुओ के <em>ज़ीहुई</em> (字彙) ने सूची घटाकर 214 कर दी और शेष-स्ट्रोक वाला क्रम जोड़ा, और 1627 के <em>झेंगज़ीतोंग</em> (正字通) ने वही 214 बनाए रखे। कांगशी शब्दकोश ने ये दोनों नवाचार अपनाए, और चूँकि यह शब्दकोश मानक संदर्भ-ग्रंथ बन गया, ये 214 आज <strong>कांगशी रैडिकल</strong> कहलाते हैं।</p><h3>अब भी मशीनरी में</h3><p>ये 214 साम्राज्य के बाद भी ज़िंदा रहे। जापानी शब्दकोश कांजी को 部首 (bushu) से अनुक्रमित करते हैं, कोरियाई 부수 (busu) से, और वियतनामी हान-नोम सूचियाँ भी इसी तरह काम करती हैं। यूनिकोड इस समूह को एक समर्पित ब्लॉक, Kangxi Radicals, में U+2F00–U+2FD5 पर एनकोड करता है (संस्करण 3.0, 1999 में जोड़ा गया), जो उन सामान्य अक्षरों से अलग है जो आम लेखन में इन्हीं रैडिकलों का काम करते हैं।</p><h3>उधड़ी सिलाई</h3><p>सरलीकरण ने यह तालमेल तोड़ दिया। जब 1956 के बाद मुख्यभूमि चीन ने हज़ारों अक्षरों में सुधार किया, तो कई बार रैडिकल वाला घटक ही ग़ायब हो गया, इसलिए कांगशी सूची अब सरलीकृत अक्षर-समूह को साफ़-साफ़ अनुक्रमित नहीं करती। मुख्यभूमि का वर्तमान मानक, GF 0011-2009, 201 प्रमुख अनुक्रमण घटकों और 100 संबद्ध घटकों का उपयोग करता है, और आज के शिनहुआ ज़ीदियान में रैडिकलों का क्रम यही तालिका तय करती है — कांगशी के 214 नहीं। यहाँ तक कि कांगशी शब्दकोश के अक्षरों की प्रसिद्ध गिनती भी तय नहीं है। अक्सर इसकी 47,043 अक्षर-प्रविष्टियाँ बताई जाती हैं, जबकि पूरक संस्करण की एक गणना 47,035 अलग-अलग प्रविष्टियों के साथ 1,995 आकृतिगत वैकल्पिक रूप दर्ज करती है। ऊपर से वांग यिनझी के 1831 के <em>ज़ीदियान काओझेंग</em> ने 1716 के पाठ में 2,588 सीधी त्रुटियाँ सूचीबद्ध कीं।</p>","clerical-change-lishu":"<h3>एक क़ैदी लिपिक, एक किंवदंती, और वे पट्टियाँ जिन्होंने उसे तोड़ दिया</h3><p>परंपरा एक सुघड़ कहानी सुनाती है: छिन का चेंग म्याओ (程邈) नामक एक अधिकारी, जिसे प्रथम सम्राट ने जेल में डाल दिया था, दस वर्ष क़ैद में रहकर मुहर लिपि के घुमावों को सीधा करता रहा, ताकि एक सरल लिखावट बने जो सरकारी काग़ज़ात के लायक हो, और इसी के लिए उसे क्षमा मिल गई। हान काल के स्रोत इतना नहीं कहते। उत्तर हान काल के विद्वान त्साई योंग लिपिक लिपि का श्रेय चेंग म्याओ को देते हैं। शू शेन के ग्रंथ <em>शुओवेन जिएज़ी</em> (說文解字, 121 ईस्वी में सिंहासन को प्रस्तुत) की उपसंहार-टिप्पणी कहती है कि लिपिक लिपि जेल और दफ़्तर के कामकाज में डूबे छिन अधिकारियों के बीच शुरू हुई, और उसका प्रचलित पाठ चेंग म्याओ का नाम उलटे लघु मुहर लिपि से जोड़ता है। जेल की बात पहली बार 5वीं सदी में यांग शिन के यहाँ मिलती है, और दस वर्षों की बात 8वीं सदी में झांग हुआइगुआन के <em>शूदुआन</em> में जाकर ही आती है। फिर दिसंबर 1975 में, हूबेई के युनमेंग ज़िले में शुइहूदी (睡虎地) की एक क़ब्र से छिन क़ानूनों की 1,100 से अधिक बाँस की पट्टियाँ निकलीं, जो लगभग 217 ईसा पूर्व में लिखी गई थीं — और उन पर लिखावट पहले से ही लिपिक है, या उसी राह पर है, एकीकरण के केवल चार वर्ष बाद। सिचुआन के छिंगछुआन से मिली लगभग 309 ईसा पूर्व की लकड़ी की पट्टियाँ, प्रथम सम्राट द्वारा चीन के एकीकरण से लगभग एक सदी पहले ही, यही रुझान दिखाती हैं। लिपिक लिपि का आविष्कार किसी एक व्यक्ति ने नहीं किया था। यह उस तेज़, सीधी रेखाओं वाली “लौकिक” लिखावट से विकसित हुई, जिसका प्रयोग लिपिक हमेशा से औपचारिक मुहर लिपि के साथ-साथ करते आ रहे थे।</p><h3>क्या टूटा</h3><p>इस बदलाव का एक नाम है: <strong>隸變</strong> (lìbiàn, “लिपिक परिवर्तन”), चीनी अक्षर के इतिहास का सबसे बड़ा विच्छेद। मुहर लिपि (篆書) ने अपने कांस्य-युगीन पूर्वजों की खींची हुई, घुमावदार रेखा बनाए रखी थी; अक्षर सिद्धांततः अब भी एक शैलीकृत चित्र ही था। लिपिक लिपि (隸書) ने घुमाव की जगह ब्रश को दबाकर और उठाकर खींचा गया सीधा स्ट्रोक रख दिया — वह क्षैतिज रेखा जो कुंद “रेशमकीट के सिर” से शुरू होकर फैली हुई “जंगली हंस की पूँछ” (蠶頭雁尾) में ख़त्म होती है। गोलाइयाँ कोने बन गईं, फंदे खाने बन गए, और जिस चित्रात्मक तर्क से <em>शुओवेन</em> हर अक्षर की व्याख्या करता था, वह पृष्ठ पर लिखे अक्षर से मेल खाना बंद हो गया। लगभग हर हान अक्षर का आधुनिक आकार लिपिक आकार ही है; उसके बाद लगभग 1,800 वर्षों तक मानक बनी रही नियमित लिपि ने अनुपात और रेखाओं के ब्योरे बदले, संरचना नहीं।</p><h3>वह 月 जो तीन अलग-अलग चीज़ें है</h3><p>सबसे साफ़ नुक़सान घटकों में दिखता है। लिबियान से पहले “मांस” (肉), “नाव” (舟) और “चंद्रमा” (月) मुहर लिपि के तीन अलग-अलग तत्व थे। सीधे स्ट्रोकों में चपटे होकर तीनों अक्षर के किनारे पर एक ही ⺝ आकार में समा गए। इसलिए 期 (अवधि) में 月 सचमुच चंद्रमा है; 服 (वस्त्र) और 朕 (शाही “हम”) में 月 नाव है; और 肝 (यकृत), 腸 (आँत), 肘 (कोहनी) तथा शरीर से जुड़े दर्जनों अन्य शब्दों में 月 मांस है। ताइवान की पारंपरिक टाइपसेटिंग आज भी मांस को ⺼ के रूप में अलग रखने की कोशिश करती है, पर अधिकांश फ़ॉन्ट अब इनमें भेद नहीं करते। उलटा भी होता है: अकेला “अग्नि” तत्व 火 अक्षर के निचले हिस्से में चार बिंदुओं 灬 में बँट गया — फिर भी 魚 (मछली) और 燕 (अबाबील) के नीचे के चार बिंदु पूँछ हैं, और 馬 (घोड़ा) के नीचे के चार बिंदु पैर, आग बिल्कुल नहीं।</p><h3>पढ़ने के लिए यह क्यों मायने रखता है</h3><p>लिबियान आधुनिक पाठक और किसी अक्षर की व्युत्पत्ति के बीच खड़ी दीवार है। सामान्यतः आप आज के किसी अक्षर को वापस उसके मूल हिस्सों में नहीं तोड़ सकते, क्योंकि लिबियान ने असंबंधित तत्वों को मिलाया भी और एकल तत्वों को तोड़ा भी। विद्वान इन मामलों को लोप (省變), संक्षेपण (簡變), किसी घटक की जगह असंबंधित घटक रख देना (調變), और पूरी तरह पहचान से परे आकार में उत्परिवर्तन (突變) में बाँटते हैं। यही कारण है कि गंभीर पुरालिपिशास्त्र आज भी उस अक्षर से नहीं जिसे आप टाइप कर सकते हैं, बल्कि मुहर और कांस्य रूपों से शुरू होता है: <em>शुओवेन</em> के विश्लेषण दीवार के लघु-मुहर वाले छोर पर लिखे गए थे, और अक्सर ऐसे अक्षर का वर्णन करते हैं जिसे पुस्तक पूरी होने तक लिपिक परिवर्तन पहले ही बिखेर चुका था।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"月\">🀄 मानचित्र पर 月 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"30.8\" data-lng=\"113.75\" data-zoom=\"6\">🌍 शुइहूदी (युनमेंग) पर जाएँ</button></div>","rhyme-dictionaries-qieyun":"<h3>विवाद सुलझाने के लिए बना एक कोश</h3><p>सन् 601 में, सुई राजवंश के समय, लू फ़ायान (陸法言) ने <em>चिएयुन</em> (切韻) पूरा किया, जिसमें 12,158 अक्षर-प्रविष्टियाँ पाँच खंडों में 193 तुक-समूहों में बाँटी गईं — दो खंड सम तान के लिए, और एक-एक आरोही, प्रस्थानी और प्रवेशी तान के लिए। इसका उद्देश्य किसी एक शहर की बोली का वर्णन करना नहीं था। अपनी भूमिका में लू लगभग बीस साल पहले की एक शाम याद करते हैं, जब छांगआन में उनके घर पर आठ विद्वान — पाँच उत्तरी और तीन दक्षिणी पृष्ठभूमि के, जिनमें यान झीतुई (顏之推) और श्याओ काई (蕭該) सबसे प्रभावशाली थे — इस पर बहस कर रहे थे कि कौन-से उच्चारण सही हैं। यह ग्रंथ पंच का काम करता है: जहाँ भी कोई प्रतिष्ठित परंपरा — उत्तरी या दक्षिणी, प्राचीन या समकालीन — कोई भेद अब भी बनाए रखती थी, वहाँ यह उस भेद को सुरक्षित रखता है।</p><p>हर शब्दांश <strong>फ़ानचिए</strong> (反切) पद्धति से लिखा गया है: दो अक्षर, जिनमें पहला आरंभिक व्यंजन देता है और दूसरा शब्दांश का शेष भाग और तान। 東 <em>dōng</em> को 德紅切 के रूप में दिया गया है — <em>d-</em> के लिए 德 (<em>dé</em>), और <em>-ōng</em> के लिए 紅 (<em>hóng</em>)। कोई भी ध्वनि सीधे नहीं लिखी जाती, फिर भी यह प्रणाली भीतर से एकदम सटीक है: फ़ानचिए में प्रयुक्त अक्षरों की शृंखलाओं का पीछा कीजिए, तो आरंभिक व्यंजनों और अंतिम अंशों की पूरी सूची अपने-आप सामने आ जाती है — उन ध्वनियों की भी, जिनमें आज कोई भी जीवित बोली भेद नहीं करती।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"東\">🀄 東 (dōng) दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"34.27\" data-lng=\"108.95\" data-zoom=\"5\">🌍 छांगआन (आज का शीआन) तक जाएँ</button></div><p>स्वयं <em>चिएयुन</em> खो गया। वह नक़ल और विस्तार के सहारे बचा रहा: पहले 706 में वांग रेनश्यू (王仁昫) का संशोधित संस्करण, फिर सोंग राजवंश का <em>ग्वांगयुन</em> (廣韻), 1007–1008, जिसे चेन फंगनियान (陳彭年) और चिउ योंग ने संकलित किया; इसमें तुकों की संख्या 206 और प्रविष्टियों की 26,194 तक पहुँच गई, जबकि पुरानी तुक-श्रेणियाँ लगभग ज्यों-की-त्यों बनी रहीं। सदियों तक विद्वानों के पास मूल के सबसे क़रीब यही <em>ग्वांगयुन</em> था। फिर 1947 में, बीजिंग के ल्यूलीचांग इलाक़े में किताबों की एक दुकान पर, दो विद्वानों को वांग रेनश्यू के संस्करण की एक लगभग पूरी तांग-कालीन पांडुलिपि मिली, जिसकी नक़ल 9वीं सदी के आरंभ में हुई थी — इससे पुष्टि हुई कि सोंग-कालीन ग्रंथ ने 601 की प्रणाली को निष्ठा से आगे बढ़ाया था।</p><p>फिर आईं <strong>तुक-सारणियाँ</strong> (韻圖)। <em>युनजिंग</em> (韻鏡), जिसके रचयिता और रचना-काल अज्ञात हैं और जो झांग लिनझी के 1161 और 1203 के संस्करणों में बची है, कोश के शब्दांशों को 43 ग्रिडों पर फैलाती है: 23 स्तंभों में समेटे गए 36 आरंभिक व्यंजन, और हर स्तंभ में ऊपर से नीचे चार तान, जिनमें से हर एक मध्यवर्ती ध्वनि और स्वर के आधार पर चार \"विभागों\" (等) में बँटी है। इन सारणियों ने फ़ानचिए के जाल को एक नक्शे में बदल दिया — एक नज़र में दिख जाता था कि कौन-से अंतिम अंश एक ही स्तंभ में आते हैं और कौन-से आरंभिक व्यंजन आपस में विरोधी हैं।</p><p>यही मध्यकालीन चीनी की कच्ची सामग्री है। स्वीडिश चीनविद् बर्नहार्ड कार्लग्रेन (高本漢) ने <em>ग्वांगयुन</em> की श्रेणियों और तुक-सारणियों को अपना ढाँचा बनाया, और आधुनिक चीनी बोलियों — जिनका सर्वेक्षण उन्होंने स्वयं किया था — तथा जापानी, कोरियाई और वियतनामी में सुरक्षित चीनी उधार-उच्चारणों की मदद से उनमें ध्वन्यात्मक मान भरे। विलियम बैक्सटर के 1992 के लिप्यंतरण ने यह तर्क स्पष्ट कर दिया: उनकी मध्यकालीन चीनी उन भेदों का एक संकेतन है जिन्हें <em>चिएयुन</em> दर्ज करता है, न कि यह दावा कि कोई एक व्यक्ति कैसे बोलता था। यही संकेतन — 東 <em>tuwng</em>, 一 <em>'jit</em> — बैक्सटर और सागार्ट अपने 2014 के पुरानी चीनी पुनर्निर्माण के ऊपरी आधार-बिंदु के रूप में इस्तेमाल करते हैं।</p><p>इससे वह प्रश्न बचता है जिसका उत्तर तुक-कोश स्वयं नहीं दे सकते। लू फ़ायान ने जान-बूझकर कई क्षेत्रों और कालों के भेद एकत्र किए थे; संभव है कि <em>चिएयुन</em> में सुरक्षित कुछ विरोध कभी किसी एक व्यक्ति के मुँह में साथ-साथ मौजूद ही न रहे हों। आज अधिकांश भाषाविद् मध्यकालीन चीनी को एक बहु-बोली प्रणाली (डायासिस्टम) मानते हैं: हर भेद कहीं न कहीं सचमुच बोला जाता था, पर किसी ने भी सारे भेद एक साथ उच्चारित नहीं किए।</p>","cjkv-false-friends":"<p>टोक्यो में <strong>手紙</strong> (<em>tegami</em>) का मतलब है चिट्ठी — लिफ़ाफ़ा, डाक टिकट, लिखा हुआ संदेश। बीजिंग में यही दो अक्षर, 手纸 (<em>shǒuzhǐ</em>) के रूप में लिखे जाने पर, टॉयलेट पेपर हैं। जिस जापानी पर्ची में 手紙 का ज़िक्र हो, वह चीनी पाठक को बाथरूम के रोल की बात लगेगी। अक्षर बिलकुल एक जैसे हैं; अर्थ ज़रा भी मेल नहीं खाते।</p>\n\n<div class=\"trivia-actions\">\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.69\" data-zoom=\"4\">🗼 टोक्यो पर जाएँ</button>\n  <button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.90\" data-lng=\"116.40\" data-zoom=\"4\">🏯 बीजिंग पर जाएँ</button>\n</div>\n\n<p>ऐसे जोड़े पूरे चीनी सांस्कृतिक क्षेत्र में फैले हुए हैं। चीनी अक्षर अलग-अलग सदियों में जापानी, कोरियाई और वियतनामी में उधार लिए गए, और कोई समास एक बार पहुँच गया तो हर भाषा के भीतर उसका अर्थ अपनी ही रफ़्तार से बदलता गया। पन्ने पर अक्षर जस के तस जमे रहे, जबकि उनके नीचे के शब्द खिसकते गए। कोशकारों के पास इस नतीजे का एक नाम है: झूठे दोस्त (false friends)।</p>\n\n<p><strong>汽車</strong> का शाब्दिक अर्थ है “भाप वाहन”, और दोनों पड़ोसियों ने इसे अलग-अलग मशीनों से जोड़ दिया। जापान ने इसे रेलवे पर टिका दिया: <em>kisha</em> भाप से चलने वाली रेलगाड़ी है, इसलिए 汽車 पकड़ने की बात करने वाला जापानी वाक्य ट्रेन में सवार होने के बारे में है। चीनी ने इस समास को सड़क से जोड़ा: 汽车 (<em>qìchē</em>) मोटरकार है। कहिए कि आप 汽車 से आए, तो जापानी श्रोता के मन में प्लेटफ़ॉर्म उभरेगा और चीनी श्रोता के मन में कार।</p>\n\n<p>सबसे चौड़ी दरार <strong>愛人</strong> यानी “प्रिय व्यक्ति” में है। मुख्यभूमि चीन में 爱人 (<em>àirén</em>) आपका जीवनसाथी है — वह पति या पत्नी जिसका परिचय आप सबके सामने कराते हैं — और विक्शनरी के अनुसार रोमांटिक साथी के लिए भी बुज़ुर्ग वक्ता 爱人 ही कहते हैं, जबकि युवा लोग 恋人 (<em>liànrén</em>) का सहारा लेते हैं। जापानी 愛人 (<em>aijin</em>) का अर्थ कभी प्रेमी या प्रियजन था, फिर द्वितीय विश्वयुद्ध के बाद यह “रखैल” — यानी विवाहेतर संबंध की साथी — के अर्थ तक फिसल गया। कोरियाई 애인 (<em>aein</em>) बीच में है: साधारण बॉयफ़्रेंड या गर्लफ़्रेंड। एक ही समास का अर्थ है वह व्यक्ति जिससे आपने शादी की, वह जिसके साथ आप बेवफ़ाई कर रहे हैं, और वह जिसे आप डेट कर रहे हैं — यह इस पर निर्भर करता है कि आप किस राजधानी में हैं।</p>\n\n<p><strong>工夫</strong> चार दिशाओं में बँटता है। कोरियाई 공부 (<em>gongbu</em>) पढ़ाई है — वही शब्द जिससे छात्र होमवर्क की बात करता है। जापानी 工夫 (<em>kufū</em>) का अर्थ है कोई तरीक़ा निकालना, सूझ-बूझ — और ज़ेन में, अनुशासित मानसिक प्रयास। चीनी 工夫 (<em>gōngfu</em>) किसी काम में लगाया गया समय या मेहनत है, और इसका जुड़वाँ रूप 功夫 उसी तरह कमाया गया हुनर है: मार्शल आर्ट्स वाला <em>कुंग फ़ू</em>। <strong>先生</strong>, “पहले जन्मा”, जापानी (<em>sensei</em>) और कोरियाई (선생, <em>seonsaeng</em>) में शिक्षक है, मंदारिन (<em>xiānsheng</em>) में किसी भी वयस्क पुरुष के लिए सादा “श्रीमान”, और वियतनामी में वह साहित्यिक <em>tiên sinh</em> है जो ज़्यादातर ऐतिहासिक और मार्शल-आर्ट्स ड्रामों में सुनाई देता है — वियतनाम में रोज़मर्रा का “श्रीमान” <em>ông</em> है, जो ख़ुद भी 翁 “बूढ़ा आदमी” से लिया गया एक पुराना चीनी-वियतनामी शब्द है।</p>\n\n<h3>एक ही अक्षर का अर्थ क्यों बदल जाता है</h3>\n<p>ज़्यादातर काम दो ताक़तें करती हैं। पहली है हर देश में अलग-अलग चलने वाला सामान्य अर्थ-परिवर्तन: 丈夫 जापानी में मज़बूत, तंदुरुस्त चीज़ है (<em>jōbu</em>), पर चीनी में पति (<em>zhàngfu</em>); 娘 जापानी में बेटी है (<em>musume</em>), और चीनी में माँ या स्त्री (<em>niáng</em>)। दूसरी है पुनर्निर्यात। मेइजी काल के जापान (1868–1912) में पश्चिमी अवधारणाओं के अनुवाद के लिए कई दो-अक्षरी समास गढ़े गए — <em>wasei-kango</em>, “जापान में बने चीनी शब्द” — और फिर वापस चीनी, कोरियाई और वियतनामी में भेजे गए, जहाँ उनके अर्थ फिर से बदले। इसके उलट 新聞 समाचार के लिए एक पुराना चीनी शब्द है, जो सिर्फ़ जापानी तरफ़ बदला: 新聞紙 “समाचार-काग़ज़-पन्ना” से छोटा होकर <em>shinbun</em> ख़ुद अख़बार बन गया, जबकि चीनी 新闻 (<em>xīnwén</em>) आज भी बस समाचार है।</p>\n\n<p>हर जोड़ा एक ही कहानी दर्ज करता है: साझा अक्षर एक बार उधार लिया गया, और फिर उधार लेने वाली भाषा ने उसे अपनी ज़रूरत के मुताबिक़ अर्थ दे दिया। ऑनलाइन लगातार चलता सीमा-पार संपर्क इनमें से कुछ को फिर क़रीब लाएगा या बस नए अंतर जोड़ेगा — यह अभी तय नहीं है।</p>","chinese-telegraph-code":"<p>मोर्स कोड एक वर्णमाला को ध्यान में रखकर बनाया गया था: छोटे और लंबे स्पंद छब्बीस लैटिन वर्णों और दस अंकों को दर्शाते हैं। चीनी लिपि में कोई वर्णमाला नहीं है और उसमें दसियों हज़ार अक्षर हैं, इसलिए किसी अक्षर को सीधे तार पर भेजने का कोई तरीका नहीं था। जब डेनमार्क के स्वामित्व वाली ग्रेट नॉर्दर्न टेलीग्राफ़ कंपनी ने 1871 में शंघाई और हांगकांग के बीच केबल शुरू की, तो चीनी भेजने के लिए पहले इस खाई को पाटना ज़रूरी था।</p><p>समाधान यह निकला कि अक्षर भेजना बंद करके उनकी जगह संख्याएँ भेजी जाएँ। शंघाई में तैनात फ़्रांसीसी सीमा-शुल्क अधिकारी <strong>सेप्टीम ऑगुस्त विगिए</strong> (威基謁) ने 1872 में <em>電報新書</em> (\"टेलीग्राफ़ के लिए नई पुस्तक\") प्रकाशित की, जिसमें हर अक्षर को 0001 से 9999 तक का एक चार अंकों वाला कोड दिया गया। उन्होंने डेनिश खगोलशास्त्री हान्स शेलेरुप की एक पुरानी सूची को आधार बनाया, और दोनों ने केवल आम तौर पर इस्तेमाल होने वाले अक्षरों का एक उपसमूह चुना; लेखन-प्रणाली का अधिकांश हिस्सा बाहर ही रह गया।</p><p>खोज एक ग्रिड पर आधारित है। कोड-पुस्तिका 100 पृष्ठों की है, और हर पृष्ठ 100 अक्षरों की 10×10 तालिका है। कोड के पहले दो अंक पृष्ठ बताते हैं, तीसरा पंक्ति और चौथा स्तंभ, और पहला स्तंभ सबसे दाईं ओर होता है। 中 है <strong>0022</strong> — पृष्ठ 00, पंक्ति 2, स्तंभ 2; 文 है <strong>2429</strong>। क्लर्क संदेश पढ़ता, पुस्तिका में हर अक्षर ढूँढता और मोर्स में चार अंक भेजता; दूसरे छोर पर बैठा क्लर्क यही खोज उलटी दिशा में करता। हर अक्षर की कीमत चार अंक थी, और यह बोझ इतना वास्तविक था कि बाद में इस कोड का तीन अक्षरों वाला एक संस्करण बनाया गया, जिससे अंतरराष्ट्रीय शुल्क चार अंकों वाले कोड की तुलना में 25% कम हो जाता था।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='31.23' data-lng='121.47' data-zoom='5'>🌍 शंघाई पर जाएँ</button></div><p>पहली पुस्तकों की आलोचना हुई कि उनमें अक्षर कम थे और क्रम अव्यवस्थित था। सुधारक <strong>झेंग गुआनयिंग</strong> ने 1881 में एक नई कोड-पुस्तिका तैयार की, जो तब तक प्रयोग में रही जब तक परिवहन और संचार मंत्रालय ने 1929 में उसका विकल्प जारी नहीं किया; 1933 में उसका एक पूरक भी आया। 1949 के बाद यह कोड मुख्य भूमि और ताइवान के अलग-अलग संस्करणों में बँट गया; चीनी जनवादी गणराज्य की <em>मानक टेलीग्राफ़ कोड-पुस्तिका</em> लगभग 7,000 अक्षरों के कोड देती है और 1983 में सरलीकृत रूपों पर आ गई।</p><p>टेलीग्राफ़ चला गया, पर संख्याएँ नहीं गईं। हांगकांग और मकाऊ के निवासी पहचान-पत्रों पर धारक के नाम का चीनी टेलीग्राफ़ कोड छपा होता है, और हांगकांग के सरकारी व व्यावसायिक फ़ॉर्म नियमित रूप से इसे माँगते हैं। अब कारण संदेश भेजना नहीं है: चार अंकों का कोड ठीक-ठीक तय कर देता है कि नाम में कौन-सा अक्षर है — यह काम रोमन लिपि में लिखी वर्तनी नहीं कर सकती, क्योंकि बहुत-से अक्षरों का उच्चारण एक ही होता है।</p><p>जो मोर्स की सीमा से निपटने का जुगाड़ था, वह अक्षरों की एक अनुक्रमणिका बन गया है। वही 0001–9999 तालिका, जिसने कभी 中 को 0022 के रूप में केबल पार कराया था, आज प्लास्टिक पर धारक के नाम के नीचे छपे एक भेद-सूचक के रूप में जीवित है।</p>","chinese-input-methods":"<h3>पचास हज़ार अक्षर, छब्बीस कुंजियाँ</h3><p>1716 के कांगशी शब्दकोश में 47,035 अक्षर दर्ज हैं; 1994 का <em>Zhonghua Zihai</em> यह गिनती 85,000 के पार ले जाता है। QWERTY कीबोर्ड पर रोमन वर्णों की 26 कुंजियाँ होती हैं। हर चीनी इनपुट पद्धति (輸入法, <em>shūrùfǎ</em>) इसी खाई को पाटने की एक योजना है — दसियों हज़ार चित्राक्षरों को कुछ दर्जन कुंजियों पर बिठाना, और फिर टाइप करने वाले को मेल खाने वाले मुट्ठी भर अक्षरों में से इच्छित अक्षर चुनने देना।</p><p>ये पद्धतियाँ एक ही सवाल पर बँटती हैं: आप अक्षर का रूप टाइप करते हैं या उसकी ध्वनि? आकार-आधारित पद्धतियाँ पहले आईं, क्योंकि वे समध्वनि शब्दों की समस्या से बच निकलती हैं। ताइवान में काम कर रहे चू बोंग-फ़ू (朱邦復) ने लगभग 1976 में त्सांगजिए (倉頡輸入法) बनाई और उसका नाम लेखन के पौराणिक आविष्कारक के नाम पर रखा। त्सांगजिए हर अक्षर को अधिकतम पाँच मूल आकार-इकाइयों में तोड़ती है, जो 24 वर्ण-कुंजियों पर रखी गई हैं — 日 A कुंजी पर, 月 B पर — इसलिए 明 \"उज्ज्वल\" <strong>AB</strong> से टाइप होता है। यह साधारण QWERTY कीबोर्ड पर चलने वाली पहली चीनी इनपुट पद्धति थी, और 1982 में चू ने इसे सांस्कृतिक विरासत बताते हुए इसका पेटेंट छोड़ दिया।</p><p>अगस्त 1983 में वांग योंगमिन (王永民) ने मुख्यभूमि चीन में वूबीज़िशिंग (五筆字型, \"पाँच-स्ट्रोक आकार\") जारी की। वूबी हर अक्षर को स्ट्रोक की पाँच श्रेणियों में बाँटती है और हर कुंजी पर कई घटक रखती है, ताकि किसी आम अक्षर के लिए अधिकतम चार कीस्ट्रोक लगें — और ध्वनि-आधारित इनपुट के विपरीत, इसमें लगभग कोई अस्पष्टता नहीं होती। प्रशिक्षित वूबी टाइपिस्ट पिनयिन वाले से तेज़ टाइप कर सकता है, इसीलिए आम उपयोगकर्ताओं के दूर हो जाने के बहुत बाद तक यह पेशेवर टाइपिस्टों और आशुलिपिकों के बीच टिकी रही। इसकी क़ीमत है रटना: किसी अक्षर के उच्चारण से उसके वूबी कोड का अनुमान लगाने का कोई तरीका नहीं है।</p><p>ध्वनि-आधारित इनपुट ने यह बाधा हटा दी। 1958 में मानकीकृत रोमनीकरण हान्यू पिनयिन की मदद से मंदारिन बोलने वाला कोई भी व्यक्ति 羅, 蘿, 鑼 और दर्जनों अन्य अक्षरों के लिए <em>luó</em> टाइप कर सकता है — और यहीं पेच है। मंदारिन में टोन-चिह्नित केवल लगभग 1,300 शब्दांश हैं, जिन पर हज़ारों अक्षरों का भार है, इसलिए हर पिनयिन स्ट्रिंग उम्मीदवारों की लंबी सूची लौटाती है, और टाइपिस्ट संख्या दबाकर चुनता है। ताइवान यही सिद्धांत झूयिन (注音, बोपोमोफ़ो) के ज़रिए लागू करता है — 1918 में अपनाई गई ध्वन्यात्मक वर्णमाला, जिसके 37 चिह्नों की कीबोर्ड पर अपनी अलग कुंजियाँ हैं।</p><p>आधुनिक IME का असली काम इसी समध्वनि सूची में होता है। 2006 में शुरू हुए सोगोउ पिनयिन ने अपना शब्दकोश किसी कोशकार से नहीं, बल्कि उन पन्नों से बनाया जिन्हें उसकी मूल कंपनी का सर्च इंजन पहले ही इंडेक्स कर चुका था, इसलिए नया स्लैंग और नए नाम कुछ ही दिनों में उम्मीदवार-सूची तक पहुँच जाते थे। यह उम्मीदवारों को आवृत्ति के आधार पर क्रमबद्ध करता था, हर उपयोगकर्ता के चुनावों से सीखता था, और अगला शब्द टाइप होने से पहले ही भाँप लेता था: उपनाम टाइप करें तो पूरा नाम सुझाता; दो शब्दांश टाइप करें तो चार-अक्षरी मुहावरा सुझाता।</p><p>इस दुष्प्रभाव का एक नाम है: 提筆忘字 (<em>tí bǐ wàng zì</em>), \"क़लम उठाओ और अक्षर भूल जाओ।\" जो व्यक्ति बरसों से 饕餮 को सूची से चुनता आया है, हो सकता है वह अब उसके 40 स्ट्रोक हाथ से न बना पाए। अप्रैल 2010 में China Youth Daily के 2,072 लोगों पर किए गए सर्वेक्षण में 83% ने बताया कि उन्हें ऐसे अक्षर लिखने में दिक़्क़त होती है जिन्हें वे अब भी पढ़ सकते हैं। ये सर्वेक्षण अनौपचारिक हैं, और 2018 में <em>The China Quarterly</em> में प्रकाशित एक पुनर्मूल्यांकन ने सवाल उठाया कि वे वास्तव में कितना मापते हैं; 2024 में <em>Reading and Writing</em> में छपे एक अध्ययन ने ध्यान दिलाया कि कोई नैदानिक परीक्षण मौजूद ही नहीं था, और कमी पूरी करने के लिए 30 अक्षरों का एक परीक्षण तैयार किया। पहचानने की क्षमता बनी रहती है, जबकि लिखने की घटती जाती है — अक्षर देखते ही आप उसे पहचान लेते हैं, पर कोरे पन्ने पर उसे उतार नहीं पाते।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"25.03\" data-lng=\"121.57\" data-zoom=\"4\">🌍 ताइपे — जहाँ त्सांगजिए बनी</button></div>","capital-numerals-daxie":"<h3>बहीखाते में 一二三 पर भरोसा क्यों नहीं किया जा सकता</h3><p>एक, दो और तीन के लिए रोज़मर्रा के चीनी अंक क्रमशः एक, दो और तीन क्षैतिज रेखाएँ हैं: <strong>一 二 三</strong> (yī èr sān)। रसीद पर यही कमज़ोरी है। एक रेखा जोड़ते ही 一 बन जाता है 二, और एक और जोड़ने पर 三; 十 (दस) ऊपर एक स्ट्रोक लगाते ही 千 (हज़ार) बन जाता है, और 三十 (तीस) को कोई भी, जिसके पास ब्रश और इरादा हो, बदलकर 五千 (पाँच हज़ार) बना सकता है। इसलिए अनुबंधों, कर-अभिलेखों और बैंक ड्राफ़्टों के लिए चीनी भाषा अंकों का एक दूसरा सेट रखती है, जिसे इस तरह गढ़ा गया है कि ऐसी कोई छेड़छाड़ काम न करे: 壹 貳 參 肆 伍 陸 柒 捌 玖 拾 佰 仟 萬। इन्हें 大寫 (<em>dàxiě</em>, \"बड़ा लेखन\") या बैंकरों के अंक कहा जाता है।</p><p>हर बड़ा रूप पहले से मौजूद एक अक्षर है, जिसे उसके अर्थ के लिए नहीं, बल्कि उसकी ध्वनि के लिए उधार लिया गया। 壹 (एक) का अर्थ \"संपूर्ण, एकाग्र होना\" भी था; 貳 (दो) का अर्थ था \"दुगुना करना, विश्वासघात करना\"; 參 (तीन) जिनसेंग का नाम है और इसका अर्थ \"भाग लेना\" भी है; 肆 (चार) का अर्थ था \"भोग-विलास में डूबना\" और यह आज भी दुकान के नाम में आता है; 陸 (छह) सूखी ज़मीन है; 玖 (नौ) जेड जैसा एक गहरे रंग का पत्थर है; 萬 (दस हज़ार) मूलतः बिच्छू का चित्र था। चूँकि इन तेरह अक्षरों की आकृतियों में आपस में कोई संबंध नहीं है, इसलिए 壹 में ऐसी कोई रेखा नहीं जोड़ी जा सकती जिससे वह 貳 बन जाए, और 參 (तीन) को फुलाकर किसी बड़ी संख्या में बदलने का कोई तरीका नहीं है। जालसाज़ के हाथ कोई सिरा लगता ही नहीं।</p><h3>पहले वू ज़ेत्यान, फिर होंगवू</h3><p>समध्वनि अक्षरों से बदल देने की यह तरकीब पुरानी है। परंपरा से इसका श्रेय चीन की एकमात्र महिला सम्राट वू ज़ेत्यान (शासन 690–705) को दिया जाता है, हालाँकि तांग-कालीन स्रोत यह नहीं बताते कि उन्होंने इन रूपों का प्रयोग क्यों किया। सोंग राजवंश के विद्वान चेंग दाचांग ने बाद में लिखा कि अधिकारी हिसाब-किताब में जटिल समध्वनि अक्षर रख देते थे, पर उन्होंने वू ज़ेत्यान का नाम नहीं लिया। निर्णायक मानकीकरण का श्रेय मिंग राजवंश के संस्थापक सम्राट झू युआनझांग (होंगवू सम्राट, शासन 1368–1398) को दिया जाता है, जिनके बारे में कहा जाता है कि एक बड़े गबन-कांड के बाद उन्होंने हिसाब बड़े अंकों में रखने का आदेश दिया — लोकप्रिय मान्यता के अनुसार यह 1385 का गुओ हुआन (郭桓) मामला था, जो मिंग राजवंश के \"चार बड़े मामलों\" में से एक है। मिंग इतिहास-ग्रंथों का कोई भी बचा हुआ अंश इस आदेश को ख़ास तौर पर उसी मामले से नहीं जोड़ता, इसलिए यह प्रथा होंगवू से जुड़ी है, यह बात पक्की है, पर उसकी तारीख़ पक्की नहीं।</p><div class='trivia-actions'><button type='button' class='trivia-action' data-action='panto' data-lat='32.06' data-lng='118.80' data-zoom='5'>🌍 मिंग की पहली राजधानी नानजिंग पर जाएँ</button></div><h3>आज भी हर नोट पर</h3><p>यह व्यवस्था कभी सेवानिवृत्त नहीं हुई। 100 युआन के रेनमिनबी नोट पर अरबी अंक \"100\" के बगल में <strong>壹佰圆</strong> (yībǎi yuán) छपा होता है। पीपल्स बैंक ऑफ़ चाइना क़ानून मुद्रा की इकाई 元 निर्धारित करता है, पर नोट पुराना रूप 圆 ही बनाए रखता है; 2015 का संस्करण आने पर भाषा-प्रयोग की पत्रिका <em>याओवेन जियाओज़ी</em> के संपादक हाओ मिंगजियान ने इसे त्रुटि बताया। मुख्यभूमि चीन के चेक, इनवॉइस और औपचारिक अनुबंधों में आज भी राशि 大写 में लिखना अनिवार्य है, जहाँ ¥1,250 लिखा जाता है 人民币壹仟贰佰伍拾元整 — और अंत में लगा 整 (\"पूरा\") संख्या के अंत पर मुहर लगा देता है, ताकि उसके बाद कुछ जोड़ा न जा सके। शून्य का भी अपना बड़ा रूप है, 零, जो छूटे हुए स्थान को दर्शाता है: 1,005 है 壹仟零伍।</p><h3>यह आदत दूर तक गई</h3><p>जापान और कोरिया ने अक्षरों के साथ यह परंपरा भी अपना ली। जापानी क़ानून आज भी राशियों और आधिकारिक रजिस्टरों के अंकों के लिए <em>दाइजी</em> (大字) रूप 壱 (1), 弐 (2), 参 (3) और 拾 (10) निर्धारित करता है; उदाहरण के लिए, वाणिज्यिक पंजीकरण नियम धनराशि, मात्रा, तिथियों और क्रमांकों के लिए इन्हीं रूपों को अनिवार्य करते हैं, हालाँकि पाठ क्षैतिज दिशा में लिखा हो तो अरबी अंकों की अनुमति है। ये रूप चीनी मूल से कुछ अलग हो गए (जापानी 壱弐参 बनाम चीनी 壹貳參), पर तर्क वही है: जहाँ एक अंक बदलने से पैसे का हेर-फेर हो सकता है, वहाँ ऐसा अक्षर लिखो जिसे बदलना बहुत कठिन हो।</p>","ateji-sound-kanji":"<p>कांजी में लिखने पर जापानी शब्द <em>mucha</em>, “बेतुका” या “दुस्साहसी”, 無茶 बनता है, शाब्दिक अर्थ “बिना चाय का”। चाय से इसका कोई लेना-देना नहीं। पहले अक्षर का गो-ऑन पाठ <strong>mu</strong> है, और ये दोनों अक्षर अपनी ध्वनि के लिए चुने गए। ऐसी वर्तनियों को <em>ateji</em> कहते हैं, 当て字, “नियत किए गए अक्षर”: ऐसे कांजी जो अर्थ की ज़्यादा परवाह किए बिना किसी शब्द की जगह लिखे जाते हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"無\">🗺️ 無 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"茶\">🗺️ 茶 दिखाएँ</button></div><p>सुशी रोज़ का उदाहरण है। इसका आम आतेजी 寿司 है, और कोई भी हिस्सा खाने से जुड़ा नहीं। 寿 का अर्थ है स्वाभाविक जीवन-अवधि और 司 का प्रबंध करना। आतेजी ढूँढ़ने के लिए खाना वैसे भी अच्छी जगह है, क्योंकि ये पारंपरिक दुकानों के बोर्डों और मेन्यू पर ख़ास तौर से मिलते हैं। कॉफ़ी आम तौर पर コーヒー है, पर कॉफ़ी की दुकान के बोर्ड पर 珈琲 लिखा हो सकता है।</p><h3>इतिहास की परतें</h3><p>इतिहास ने परतें छोड़ीं। तला हुआ पकवान टेम्पुरा 天麩羅 लिखा जा सकता है, जिसमें 天 का पाठ <strong>ten</strong> है, और यह पुर्तगालियों के रास्ते लैटिन <em>tempora</em> तक जाता है। गाली <em>baka</em>, “मूर्ख”, 馬鹿 लिखी जाती है, यानी “घोड़ा हिरन”, और इसमें <strong>ba</strong> कान-ऑन पाठ है। पर ये अक्षर असली शब्द पर चढ़ाया गया भेस भर लगते हैं। यह शब्द शायद संस्कृत <em>moha</em>, “मूढ़ता”, का लिप्यंतरण था, जो भिक्षुओं की बोलचाल में चलता था। आतेजी मोटे तौर पर ऐतिहासिक क्रम से आए: बौद्ध धर्म के साथ संस्कृत शब्द, 16वीं और 17वीं सदी में पुर्तगाली शब्द, और 19वीं सदी तक डच शब्द।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"馬\">🗺️ 馬 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"天\">🗺️ 天 दिखाएँ</button></div><p>कुछ वर्तनियों का असर ख़ुद अक्षरों पर भी पड़ा। विदेशी स्थान-नाम कभी बड़े पैमाने पर इसी तरह लिखे जाते थे, एशिया 亜細亜 और अमेरिका 亜米利加। लंबे रूप अब पुराने पड़ गए, पर निशान छोड़ गए। 亜 ने 東亜, <strong>tō</strong>-a, “पूर्वी एशिया”, जैसे समासों में “एशिया” का अर्थ पा लिया, जबकि उसका मूल अर्थ “दोयम दर्जे का” था और आज भी है। इसी तरह अमेरिका के शब्द के बीच के हिस्से से 米国 बना, शाब्दिक अर्थ “चावल का देश”।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"東\">🗺️ 東 दिखाएँ</button></div><h3>ध्वनि और अर्थ साथ-साथ</h3><p>सबसे अच्छे वे हैं जो दोनों साध लेते हैं, ऐसे कांजी जो ध्वनि में बैठें और अर्थ का इशारा भी करें। क्लब 倶楽部 है, <em>kurabu</em>, जिसे ढीले ढंग से “साथ”, “मज़ा” और “जगह” पढ़ा जा सकता है। <em>Kappa</em>, पुर्तगाली बरसाती जिसे <em>capa</em> कहते थे, 合羽 है, “जुड़ते हुए पंख”, क्योंकि नुकीला लबादा पंख समेटे पक्षी जैसा लगता है। कुछ में तो निरी ध्वनि है, और वह भी पूरी गंभीरता से: बधाई वाला <em>medetai</em> 目出度い के रूप में आता है, जिसमें 目 अपने देशी शब्द <strong>me</strong>, “आँख”, से पढ़ा जाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"目\">🗺️ 目 दिखाएँ</button></div><h3>काना से भी पुराना</h3><p>यह आदत जापान में चीनी अक्षरों के आगमन जितनी ही पुरानी है। कवि <em>man’yōgana</em> नाम की प्रणाली में कांजी को केवल ध्वनि के लिए इस्तेमाल करते थे, और आज के काना उन्हीं अक्षरों के सरल रूपों से विकसित हुए। इस तरह आतेजी हिरागाना और काताकाना के बड़े भाई-बहन हैं। विदेशी शब्दों के लिए आतेजी का लगभग सारा काम अब काताकाना ने ले लिया है, और गैस कंपनियाँ यह बँटवारा बख़ूबी दिखाती हैं: कंपनी के नाम में 瓦斯, ट्रेड नाम में ガス।</p><p>ऐसी वर्तनियाँ आज भी मिल जाती हैं। जापान के एक कूड़ेदान पर 護美入れ लिखा है। जो शब्द बनता है वह साधारण <em>gomi</em> है, “कूड़ा”, पर अक्षर कहते हैं “सौंदर्य की रक्षा”।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.76\" data-zoom=\"6\">📍 तोक्यो पर जाएँ</button></div>","bi-sheng-movable-type":"<p>चल टाइप के आविष्कारक के बारे में लगभग सब कुछ एक ही गद्यांश से मिलता है। बी शंग एक आम आदमी थे, बिना किसी पद के, और आविष्कार के अलावा उनके जीवन के बारे में बहुत कम ज्ञात है। क़रीब 1041 से 1048 के बीच उन्होंने मिट्टी से छपाई के टाइप बनाए, हर टुकड़े पर एक अक्षर। विद्वान शेन कुओ ने, जो उस समय बच्चे थे, अपने <em>Dream Pool Essays</em> में विधि का विस्तार से वर्णन किया।</p><h3>मिट्टी, आग और लोहा</h3><p>शेन कुओ के वर्णन में तीन सामग्रियाँ ज़्यादातर काम करती हैं। अक्षर चिपचिपी मिट्टी, 土, <strong>tǔ</strong>, में सिक्के की धार जितने पतले काटे जाते थे, फिर आग, 火, <strong>huǒ</strong>, में पकाकर सख़्त किए जाते थे। टाइप लोहे की प्लेट, 鐵, <strong>tiě</strong>, पर एक फ़्रेम में जमाए जाते थे, जिस पर चीड़ की राल, मोम और काग़ज़ की राख का लेप होता था। प्लेट गरम करने से लेप नरम पड़ता, और चिकने तख़्ते से दबाने पर पूरा खंड सान के पत्थर जैसा समतल हो जाता।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"土\">🗺️ 土 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"火\">🗺️ 火 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"鐵\">🗺️ 鐵 दिखाएँ</button></div><p>वर्णन व्यावहारिक है। शेन कुओ कहते हैं कि दो-तीन प्रतियों के लिए यह विधि आसान नहीं थी, पर सैकड़ों या हज़ारों के लिए अद्भुत रूप से तेज़ थी। बी शंग दो फ़्रेम चलाते थे, एक छपता रहता और दूसरा जमता रहता। आम अक्षरों के बीस या उससे ज़्यादा टाइप होते थे, क्योंकि एक ही शब्द पन्ने पर बार-बार आ सकता था। काम में न होने पर टाइप तुक-समूहों के अनुसार, काग़ज़ के लेबलों के साथ, लकड़ी के ख़ानों में रखे जाते थे। इतने टुकड़े सँभालने थे, तो ध्वनि ही उनकी सूची का आधार बन गई।</p><h3>लकड़ी और काँसा</h3><p>लकड़ी, 木, <strong>mù</strong>, स्वाभाविक विकल्प थी। बी शंग ने उसे आज़माया और छोड़ दिया, रेशे के कारण और इसलिए कि स्याही में भीगने पर टाइप ऊबड़-खाबड़ हो जाते थे। बाद के मुद्रक उस पर लौटे। 1290 के दशक में जिंगदे के ज़िला मजिस्ट्रेट वांग जन लकड़ी के टाइप के अग्रदूत थे, और 1313 में छपी उनकी एक किताब में घूमता टाइप-केस दिखता है। काँसे के टाइप 1490 तक धनी मुद्रक हुआ सुई के साथ आ गए। मिट्टी के भी अनुयायी रहे होंगे: गांसू के वूवेई में मिला तंगुत राज्य का एक बौद्ध ग्रंथ वे खोखली और टूटी रेखाएँ दिखाता है जो मिट्टी के टाइप से जुड़ी मानी जाती हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"木\">🗺️ 木 दिखाएँ</button></div><p>फिर भी चल टाइप चीन में काठ-ठप्पा छपाई की जगह कभी नहीं ले सका। लकड़ी के टाइप छिंग राजवंश में ही आम हुए, और तब भी ठप्पा आगे रहा, क्योंकि इतने अलग-अलग अक्षर छापने में वह सस्ता पड़ता था। हज़ारों अक्षरों वाली लिपि का हिसाब उस हिसाब से अलग है जो यूरोप में चला, जहाँ क़रीब 1450 में गुटेनबर्ग की प्रेस को अक्षरों का छोटा सा सेट ही चाहिए था।</p><h3>सबसे पुरानी बची किताब</h3><p>चल धातु टाइप से छपी सबसे पुरानी बची किताब कोरियाई है। बौद्ध उपदेशों का संग्रह <em>Jikji</em> छोंगजू के बाहर हंगदक मंदिर में 1377 में छपा, गुटेनबर्ग बाइबिल से 78 साल पहले, और उसका बचा हुआ खंड फ़्रांस के राष्ट्रीय पुस्तकालय में है। ख़ुद बी शंग का स्मारक देर से आया। उनकी समाधि का पत्थर 1990 में हूबेई में मिला, और अप्रैल 2023 में वहाँ एक उद्यान और संग्रहालय खुला। चंद्रमा के दूर वाले हिस्से का एक क्रेटर उनके नाम पर है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"36.64\" data-lng=\"127.49\" data-zoom=\"7\">📍 छोंगजू पर जाएँ</button></div>","biang-noodles":"<p>शीआन में आप ऐसा नूडल मँगा सकते हैं जिसे लिखना मुश्किल है। बियांगबियांग नूडल्स मोटे और बेल्ट जैसे होते हैं, आम तौर पर हाथ से बने, और अपने अधिकांश इतिहास में ये एक अनजाना स्थानीय पकवान थे, जिन्हें वे मज़दूर खाते थे जिनके पास पतले नूडल बनाने का समय नहीं था। इनकी गिनती शान्शी के आठ अजूबों में होती है। पूरे चीन में इन्हें प्रसिद्ध करने वाली चीज़ खाना कम और बोर्ड का अक्षर ज़्यादा थी: 𰻞। इसके मानक पारंपरिक रूप में 58 रेखाएँ हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"34.26\" data-lng=\"108.94\" data-zoom=\"7\">📍 शीआन पर जाएँ</button></div><h3>खोलकर देखना</h3><p>शब्द कहाँ से आया, किसी को पक्का नहीं पता। <em>China Daily</em> के एक लेख के अनुसार <em>biang</em> एक ध्वनि की नक़ल है, वह आवाज़ जो आटा खींचकर मेज़ पर पटकने से आती है। अक्षर की एक किंवदंती भी है, जो कहती है कि छिन के प्रधानमंत्री ली सी ने इसे गढ़ा। यह बात असंभव लगती है, क्योंकि यह अक्षर कांगशी शब्दकोश में नहीं है और आधुनिक शब्दकोशों में भी नहीं। तो यह शायद ली सी के ज़माने से बहुत नया है।</p><p>इसे खोलकर देखने से मदद मिलती है, क्योंकि भीतर लगभग सब कुछ आम अक्षर है। बीच में 言, “वाणी”, के दोनों ओर दो 幺, “नन्हा”, हैं। उसके नीचे 馬, “घोड़ा”, दो 長, “लंबा”, के बीच खड़ा है। ये दोनों हान्ज़ी मानचित्र पर हैं, और शीआन में ये <strong>ma⁵³</strong> और <strong>chang²⁴</strong> हैं जहाँ मंदारिन में <strong>mǎ</strong> और <strong>cháng</strong> हैं। इस खंड के चारों ओर बाईं तरफ़ 月, “चंद्रमा”, दाईं तरफ़ 刂, “चाकू”, और नीचे 心, “हृदय”, हैं। ऊपर 穴, “गुफा”, है, और 辶, “चलना”, बाएँ और नीचे से घूमता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"馬\">🗺️ 馬 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"長:1\">🗺️ 長 दिखाएँ</button></div><h3>तुकबंदी</h3><p>शान्शी के लोग इसे रेखाएँ गिनकर नहीं सीखते। वे एक तुकबंदी इस्तेमाल करते हैं। एक रूप की शुरुआत आकाश की ओर उठते बिंदु (丶) और पीली नदी के किनारे दो मोड़ों (冖) से होती है। फिर वह आठ, वाणी और एक-दूसरे को जवाब देते दो घुमावों से गुज़रती है, भीतर घोड़े (馬) का राजा बैठाती है, और नीचे हृदय (心) और बग़ल में चंद्रमा (月) रखती है। अंत सड़क पर होता है: गाड़ी पर सवार होकर श्येनयांग की सैर। वह आख़िरी पंक्ति 辶 के लिए है, चलने का मूलांश, जो पूरे अक्षर को लपेट लेता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"心\">🗺️ 心 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"月\">🗺️ 月 दिखाएँ</button></div><p>कोई एक सही रूप भी नहीं है। पारंपरिक अक्षर के बीस से ज़्यादा भेद ज्ञात हैं, 56 से 71 रेखाओं तक, और एक सरलीकृत रूप है, 𰻝, जिसमें 馬 और 長 बदलकर 马 और 长 हो जाते हैं। हृदय और चंद्रमा दोनों रूपों में वही रहते हैं, और नक्शे की शीआन पंक्ति में वे <strong>xin²¹</strong> और <strong>yue²¹</strong> हैं।</p><h3>कंप्यूटर तक पहुँचना</h3><p>बरसों तक समस्या व्यावहारिक थी। कंप्यूटर में यह अक्षर डालने का कोई मानक तरीक़ा नहीं था। 2006 में जॉन जेंकिन्स ने ली कॉलिन्स से ईमेल चर्चा के बाद एक रूप यूनिकोड को सौंपा, पर उसका वर्णन नियमों के हिसाब से बहुत लंबा था और उसमें हृदय छूट गया था। फिर मिंग फ़ैन ने अपना आवेदन दिया, और मार्च 2020 में दोनों रूप Unicode 13.0 में कूटबद्ध हुए, पारंपरिक U+30EDE पर और सरलीकृत U+30EDD पर। तब तक लोग चित्र, पिनयिन या 彪彪面 और 冰冰面 जैसे विकल्प इस्तेमाल करते थे। कई फ़ॉन्ट में यह आज भी नहीं है, तो कुछ स्क्रीनों पर इस पन्ने में नूडल की जगह ख़ाली डिब्बा दिख सकता है।</p>","country-names-mei-bei":"<p>चीन संयुक्त राज्य को 美国 कहता है, और पहले अक्षर का अर्थ है “सुंदर”। जापान उसे 米国 कहता है, और पहले अक्षर का अर्थ है “चावल”। दोनों अमेरिका पर टिप्पणी जैसे लगते हैं, पर हैं नहीं। दोनों चीनी अक्षरों से एक विदेशी ध्वनि लिखने की कोशिश के टुकड़े हैं, और जो अर्थ झलकता है वह संयोग है। विक्शनरी चीनी नाम की “सुंदर” वाली व्याख्या को एक झूठी व्युत्पत्ति का स्रोत बताती है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.9\" data-lng=\"116.4\" data-zoom=\"5\">📍 बीजिंग पर जाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"35.68\" data-lng=\"139.76\" data-zoom=\"5\">📍 तोक्यो पर जाएँ</button></div><p>चीनी नाम 1854 से प्रमाणित है। शायद यह 亞美理駕洲大合眾國 का छोटा रूप है, “United States of America” की लंबी वर्तनी, जो 1844 की वांगश्या संधि में मिलती है। दूसरी वर्तनियाँ भी दौड़ में थीं: <em>American</em> शब्द के रूपांतर 美利堅 के पहले के प्रतिद्वंद्वी 米利堅 और 彌利堅 थे। तो इस काम में 米, चावल, का चीन में भी अपना इतिहास था। चीन ने 美 रखा, और पूरा आधिकारिक रूप आज भी 美利堅 पर बना है।</p><h3>चावल का देश</h3><p>जापान दूसरे रास्ते गया। उसने महाद्वीप को 亜米利加 लिखा, दूसरा अक्षर लिया और “देश” जोड़ दिया। नतीजा, <em>Beikoku</em>, पहले से मौजूद एक शब्द था जिसका काम कुछ और था। यह 1603 के जापानी-पुर्तगाली शब्दकोश में मिलता है, जहाँ इसका अर्थ था चावल से समृद्ध कोई भी देश, और 1819 तक यह चावल के बड़े निर्यातकों के लिए चलता था। “अमेरिका” वाला अर्थ पहली बार 1869 में मिलता है। रोज़मर्रा की जापानी आज भी アメリカ पसंद करती है, और 米国 अर्ध-औपचारिक बना हुआ है।</p><h3>स्पेन का दाँत</h3><p>स्पेन दिखाता है कि अक्षरों का अर्थ कितना कम हो सकता है। चीनी 西班牙 की शुरुआत 西, “पश्चिम”, से होती है, पाठ <strong>xī</strong>, और अंत 牙, “दाँत”, पर, पाठ <strong>yá</strong>। यह ध्वनि की वर्तनी है, 1835 से प्रमाणित, किसी चीज़ का वर्णन नहीं। 1730 की पहले की वर्तनी, 是班呀, दिखाती है कि वही ध्वनियाँ बिल्कुल अलग ढंग से लिखी जा सकती थीं। 牙 के चुनाव में शायद पड़ोसी 葡萄牙, पुर्तगाल, ने मदद की, तो इबेरिया के दोनों देश एक ही दाँत लिए चलते हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"西\">🗺️ 西 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"牙\">🗺️ 牙 दिखाएँ</button></div><p>तुर्की 土耳其 है, 土, “मिट्टी”, के साथ, पाठ <strong>tǔ</strong>, पहली बार 1820 में प्रमाणित। फ़्रांस 法国 है, जहाँ 法 法蘭西 का संक्षेप है, और अक्षर के अर्थ “क़ानून” की कोई भूमिका नहीं। जर्मनी में दो परंपराएँ अलग होती दिखती हैं। मंदारिन 德国 जर्मन शब्द <em>deutsch</em> के क़रीब है। जापानी कभी इस नाम के डच रूप के लिए 獨逸 इस्तेमाल करती थी, और कोरियाई 독일 इन्हीं जापानी अक्षरों का कोरियाई पाठ है, इसीलिए यहाँ कोरियाई और चीनी मेल नहीं खाते। यूनान की भी यही कहानी है: 希臘 <em>Hellas</em> की चीनी वर्तनी थी, और जापानी ये अक्षर लिखकर <em>Girisha</em> बोलती थी।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"土\">🗺️ 土 दिखाएँ</button></div><h3>एक अक्षर</h3><p>नाम को एक अक्षर तक काटने की आदत ज़िंदा है। कोरियाई अख़बारों की सुर्ख़ियाँ आज भी चीन के लिए 中, कोरिया के लिए 韓, संयुक्त राज्य के लिए 美 और जापान के लिए 日 इस्तेमाल करती हैं, यानी सियोल अमेरिका को जापानी नहीं, चीनी ढंग से लिखता है। चीन और जापान के अपने नाम अलग ढंग से काम करते हैं। 中, “मध्य”, पाठ <strong>zhōng</strong>, और 日, “सूर्य”, मंदारिन में पाठ <strong>rì</strong> और कोरियाई में <strong>il</strong>, अपने अर्थ के कारण चुने गए हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"日\">🗺️ 日 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"中:1\">🗺️ 中 दिखाएँ</button></div>","dragon-simplified":"<p>ताइपे में ड्रैगन की सोलह रेखाएँ हैं, तोक्यो में दस और बीजिंग में पाँच। ये हैं 龍, 竜 और 龙, और ये सब एक ही अक्षर हैं, हालाँकि हर रूप अलग रास्ते से अपनी जगह पहुँचा। 龍 ख़ुद उत्तर शांग के काँसे के अभिलेखों तक जाता है, और कांगशी शब्दकोश के 214 मूलांशों में 212वाँ है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"龍\">🗺️ 龍 दिखाएँ</button></div><p>मुख्यभूमि का 龙 काट-छाँट की एक शृंखला का अंत है। विक्शनरी इसे 龍 के एक रूप 𢅛 तक ले जाती है। उसमें से 帝 हटाने पर 尨 बचा, फिर 彡 की तीन में से दो रेखाएँ गिरा दी गईं। टुकड़ा तय हो गया तो वह पूरी व्यवस्था में फैल गया। 咙, 拢, 珑, 胧 और 陇 सब इसे लिए हैं, यानी एक अक्षर के सरलीकरण ने कई और बदल दिए। ताइवान ने पूरा रूप रखा। आकृति बदलने से पाठ नहीं बदला: नक्शे की दोनों मंदारिन पंक्तियों में <strong>lóng</strong> है।</p><h3>जापान का पुराना नया रूप</h3><p>जापान ने फिर कुछ और किया। 竜 आधुनिक शॉर्टकट जैसा लगता है, पर है नहीं। 1716 का कांगशी शब्दकोश इसे 龍 का प्राचीन रूप दर्ज करता है, और 997 के <em>Longkan Shoujian</em> और 1037 के <em>Jiyun</em> शब्दकोशों में इस आकृति के रूप मिलते हैं। यह 1946 में युद्धोत्तर सुधार के तहत तोयो कांजी सूची में आधिकारिक रूप बना। 龍 इसके पुराने रूप के तौर पर दर्ज है। ड्रैगन ऐसी जगहों पर भी मिलता है जहाँ आपको उम्मीद न हो। 土竜, “मिट्टी का ड्रैगन”, छछूँदर है, और 石竜子, “पत्थर के ड्रैगन का बच्चा”, छिपकली।</p><h3>पाठ</h3><p>पाठों ने आकृतियों से ज़्यादा यात्रा की है। जापानी में उधार की दो लहरों से <strong>ryū</strong> और <strong>ryō</strong> हैं, और देशी शब्द <strong>tatsu</strong>। कैंटोनीज़ में <strong>lung4</strong> है। वियतनामी में <strong>long</strong>, इसीलिए हनोई का शाही दुर्ग Thăng Long है, और शहर आज भी उड़ते ड्रैगन का शहर कहलाता है। दक्षिण कोरियाई में <strong>yong</strong> है, उत्तर कोरियाई में <strong>ryong</strong>। कोरियाई एक देशी शब्द भी रखती है जिसे नक्शा दर्ज करता है, <strong>mireu</strong>, 미르। और पीछे जाएँ तो नक्शे की पुरानी चीनी में <strong>*[mə]-roŋ</strong> है, और आदि-तिब्बती-बर्मी में <strong>*m-bru(ŋ/k)</strong>।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"21.03\" data-lng=\"105.85\" data-zoom=\"6\">📍 हनोई पर जाएँ</button></div><h3>और ड्रैगन</h3><p>ड्रैगन ढेर लगाने के लिए भी पसंदीदा रहा है। दो से 龖 बनता है, तीन से 龘, और चार से 𪚥, जिसकी 64 रेखाएँ हैं, 龍 की सोलह की चार प्रतियों का जोड़। पर रिकॉर्ड इसके नाम भी नहीं है। <em>Taito</em>, जापान में गढ़ा गया एक अक्षर, 84 रेखाओं से लिखा जाता है, और उसे सभी CJK अक्षरों में सबसे जटिल कहा जाता है। यह दुर्लभ अक्षर है: तीन ड्रैगनों के ऊपर तीन बादल।</p><p>तो बीजिंग का लेखक पाँच रेखाएँ इस्तेमाल करता है और ताइपे का सोलह। यूनिकोड में दोनों रूप अलग अक्षर हैं, और फ़ॉन्ट एक को दूसरे में नहीं बदलता। हांगकांग के बोर्ड का ड्रैगन और शंघाई के बोर्ड का ड्रैगन एक ही शब्द हैं, और दोनों में फ़र्क़ बस ग्यारह रेखाओं का है।</p>","fanqie-spelling":"<p>जब लिपि में अक्षर-ध्वनियाँ न हों तो उच्चारण कैसे लिखें? सदियों तक जवाब था समध्वनि शब्द: <em>Shuowen Jiezi</em> जैसा शब्दकोश बस कोई और अक्षर बता देता जो वैसा ही सुनाई देता था। अगर पाठक दूसरा अक्षर न जाने, या अच्छा मेल न हो, तो यह बेकार था। तीसरी सदी तक एक बेहतर विचार आ चुका था। दो अक्षर लो, पहले की शुरुआत और दूसरे का बाक़ी हिस्सा रखो, और जोड़ दो। यही <em>fanqie</em> है।</p><h3>पूरब बराबर 德 और 紅</h3><p>601 के तुक-शब्दकोश <em>Qieyun</em> की पहली प्रविष्टि दिखाती है कि यह कैसे चलता है। अक्षर 東, “पूरब”, की वर्तनी 德紅反 है। आख़िरी अक्षर बस सूत्र का निशान है। 德 से आप शुरुआती <em>t</em> रखते हैं, और 紅, “लाल”, से अंतिम <em>-uŋ</em> और टोन। हान्ज़ी मानचित्र की मध्यकालीन चीनी पंक्ति यह मेल सीधे दिखाती है: 東 <strong>tuɪŋ¹²³</strong> है और 紅 <strong>ɦuɪŋ¹²³</strong>, वही तुक और वही टोन-चिह्न।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"東\">🗺️ 東 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"紅\">🗺️ 紅 दिखाएँ</button></div><p>यह कहाँ से आया, यह कुछ हद तक अनुमान है। छठी सदी के विद्वान यान ज़ीथुई ने इसका श्रेय वेई राज्य के सुन यान को दिया, हालाँकि पहले के उदाहरण दूसरी सदी के अंत में मिलते हैं। बौद्ध धर्म पहली सदी के आसपास चीन पहुँचा था और भारतीय ध्वनि-ज्ञान लाया था, और शायद इसी से प्रेरणा मिली। लेबल की भी एक कहानी है। निशान 反, “लौटना”, बाद के <em>Guangyun</em> जैसे शब्दकोशों में 切 से बदल गया। छिंग विद्वान गू यानवू का सुझाव था कि 反 का एक अर्थ “तख़्तापलट” भी था, इसलिए मध्य थांग के विद्रोहों के बाद उससे बचा गया।</p><h3>हज़ार साल का उपयोग</h3><p>यह विधि टिकी रही। यह 1716 के कांगशी शब्दकोश से होकर 1930 के दशक के <em>Ciyuan</em> और <em>Cihai</em> तक चली। 18वीं सदी के मध्य के एक चीनी-मांचू शब्दकोश ने तो इसे उलटा भी इस्तेमाल किया, मांचू शब्द फ़ानछिए से और चीनी शब्द मांचू लिपि में लिखकर।</p><h3>जब सूत्र टूटता है</h3><p>आधुनिक मंदारिन पर सूत्र आज़माइए और वह टूट जाता है। 德 <em>dé</em> है, और 紅 <strong>hóng</strong>, तो नतीजा कुछ <em>dóng</em> जैसा होना चाहिए। पर 東 <strong>dōng</strong> है। कारण यह है कि 紅 कभी घोष ध्वनि से शुरू होता था। घोष आरंभ वाले अक्षरों का सुर नीचा होने लगा, और थांग के अंत तक हर टोन आरंभ के अनुसार दो में बँट चुकी थी। 601 में जो टोन साझा थी वह दो अलग टोन बन गई, और फिर ख़ुद घोषत्व चीन के अधिकांश हिस्से में मिट गया। वह वू और शियांग में बचा है। इसीलिए शंघाई की बोली नक्शे पर आज भी पुराना भेद दिखाती है: 東 <strong>ton1</strong> है और 紅 <strong>ghon6</strong>, घोष शुरुआत के साथ।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"31.23\" data-lng=\"121.47\" data-zoom=\"6\">📍 शंघाई पर जाएँ</button></div><p>तो फ़ानछिए एक रिकॉर्डिंग निकला। इन सूत्रों को लिखने वाले किसी का इरादा सबूत छोड़ने का नहीं था, फिर भी 1842 में कैंटोनीज़ विद्वान छन ली ने देखा कि इसे कैसे इस्तेमाल किया जाए। अगर 東 की वर्तनी 德 से है, 德 की 多 से और 多 की 德 से, तो तीनों का आरंभ एक ही रहा होगा। ऐसी कड़ियाँ पकड़ने से आरंभों और अंतों की श्रेणियाँ मिलती हैं। बर्नहार्ड कार्लग्रेन ने, छन के काम से अनजान, 1910 के दशक में यह विश्लेषण दोहराया, और नतीजों की तुलना आधुनिक बोलियों और चीनी-विदेशी पाठों से करके मध्यकालीन चीनी की ध्वनियों का पुनर्निर्माण किया।</p>","hanja-korea-today":"<p>कोरियाई में 一, “एक”, और 日, “सूर्य, दिन”, बिल्कुल एक जैसे सुनाई देते हैं: <strong>il</strong>। चीनी में वे अलग हैं, और हांजा में, यानी कोरियाई के लिए इस्तेमाल होने वाले चीनी अक्षरों में, फ़र्क़ फ़ौरन दिखता है। हांगुल में नहीं दिखता। एक ही शब्दांश में सिमटी हांजा की पूरी बहस यही है। कोरियाई शब्दावली का बहुत बड़ा हिस्सा चीनी से आया है, और वर्णमाला में लिखने पर ऐसे कई शब्द एक-दूसरे में घुल जाते हैं। फिर भी आज ज़्यादातर कोरियाई ये अक्षर लगभग न पढ़ते हैं न लिखते हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"一\">🗺️ 一 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"日\">🗺️ 日 दिखाएँ</button></div><h3>साहित्यिक चीनी से प्रतिबंध तक</h3><p>लंबे समय तक बात उलटी थी। कोरियाई दस्तावेज़, इतिहास और साहित्य मुख्यतः साहित्यिक चीनी में लिखे जाते थे। राजा सेजोंग ने 1446 में हांगुल जारी की, पर उसका व्यापक आधिकारिक उपयोग 19वीं सदी के अंत और 20वीं की शुरुआत तक नहीं हुआ। मिश्रित लेखन, चीनी मूल के शब्दों के लिए हांजा और उनके चारों ओर हांगुल, 20वीं सदी में बहुत आगे तक सामान्य था।</p><p>दक्षिण में मोड़ 1968 में आया, जब हांजा को सरकारी स्कूलों और सेना से हटा दिया गया, इस लक्ष्य के साथ कि 1972 तक उन्हें लेखन से मिटा दिया जाए। जनता में विरोध हुआ, और 1972 में पार्क चुंग ही की सरकार ने हांजा को एक विषय के रूप में पढ़ाने की अनुमति दी, पर उन्हें पाठ्यपुस्तकों और दूसरी कक्षा-सामग्री से बाहर रखा। टाइपराइटर और बाद में कीबोर्ड भी इन अक्षरों के ख़िलाफ़ गए, क्योंकि हांजा लिखना और छापना धीमा कर देते थे। 1970 के दशक तक सरकारी दस्तावेज़ मिश्रित लिपि ज़्यादातर छोड़ चुके थे।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"37.57\" data-lng=\"126.98\" data-zoom=\"6\">📍 सियोल पर जाएँ</button></div><h3>पलटाव</h3><p>फिर नीति उलटी दिशा में चली, बिना ख़ास असर के। प्रतिबंध औपचारिक रूप से 1992 में जाकर उठा। 1999 में सरकार ने सड़क के संकेतों, बस अड्डों और सबवे पर हांजा लगाए, और उसी साल शास्त्रीय चीनी स्कूलों में वैकल्पिक विषय बनकर लौटी। 2001 में हांजा दक्षता परीक्षा आई। 2005 में हांगुल विशिष्टता संबंधी पुराना क़ानून रद्द हुआ, और 2013 में सियोल के सभी प्राथमिक स्कूलों ने हांजा पढ़ाना शुरू किया। आज कुल 1,800 अक्षर पढ़ाए जाते हैं, 900 जूनियर हाई में और 900 सीनियर हाई में। ये 1972 में तय एक सूची से आते हैं, जिसके 44 अक्षर 2000 के अंत में बदले गए। पर तब तक एक पीढ़ी उनके बिना बड़ी हो चुकी थी, और उपयोग घटता रहा।</p><p>उत्तर कोरिया चौंकाता है। उसने आज़ादी के तुरंत बाद हांजा का आम उपयोग छोड़ दिया, और चीनी मूल के कई शब्दों की जगह देशी शब्द रखे। किम इल सुंग ने धीरे-धीरे ख़त्म करने की बात की थी, फिर 1960 के दशक तक पलट गए। 1966 में उनका यह कथन छपा कि छात्रों को ज़रूरी चीनी अक्षरों से परिचित कराया जाए और उन्हें लिखना सिखाया जाए। एक पाठ्यपुस्तक बनी जो कक्षा 5 से 9 में 1,500 अक्षर और हाई स्कूल में 500 और सिखाती थी। तो जिस देश ने हांजा को छपाई से निकाला, वह दक्षिण से ज़्यादा सिखाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.04\" data-lng=\"125.76\" data-zoom=\"6\">📍 प्योंगयांग पर जाएँ</button></div><h3>जो बचा है</h3><p>दक्षिण में जो बचा है वह छोटा और सटीक है। अख़बारों की सुर्ख़ियाँ एक-एक अक्षर संक्षेप के रूप में इस्तेमाल करती हैं: चीन के लिए 中, संयुक्त राज्य के लिए 美, जापान के लिए 日। औपचारिक प्रकाशन अक्सर लोगों के नामों के साथ हांजा देते हैं। अक्षर समध्वनि शब्दों का भेद करते हैं, जैसे 이 사장, 李 社長, “अध्यक्ष ली”, और 이사장, 理事長, “निदेशक मंडल के प्रमुख”। वे सामान भी बेचते हैं: 辛, <em>sin</em>, “तीखा”, शिन राम्यन के पैकेटों पर बड़ा छपा होता है। और पाठों में पुरानी परतें अब भी दिखती हैं। नक्शा 茶 के दो कोरियाई पाठ देता है, 綠茶, हरी चाय, में <strong>cha</strong> और 茶道, चाय समारोह, में <strong>da</strong>, और 水, <strong>su</strong>, के साथ देशी शब्द <strong>mul</strong> भी देता है, ठीक वैसे ही जैसे कक्षा में इस अक्षर का नाम लिया जाता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"茶\">🗺️ 茶 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"水\">🗺️ 水 दिखाएँ</button></div>","naming-taboo-bihui":"<p>थांग राजवंश में चैंबर पॉट को बाघ नहीं कहा जा सकता था। संस्थापक के दादा का नाम ली हू था, और 虎, “बाघ”, मंदारिन में उच्चारण <strong>hǔ</strong>, इस्तेमाल करने लायक़ नहीं रहा। हान राजवंश से पॉट 虎子 कहलाता था, “बाघ का बच्चा”। वह 馬子 बन गया, “घोड़े का बच्चा”, <strong>hǔ</strong> की जगह <strong>mǎ</strong> के साथ। यही नाम-वर्जना थी, 避諱, ऊँचे लोगों के निजी नाम बोलने या लिखने के ख़िलाफ़ नियम, जो शाही चीन में क़ानून से लागू था।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"虎\">🗺️ 虎 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"馬\">🗺️ 馬 दिखाएँ</button></div><h3>बचने के तीन रास्ते</h3><p>वर्जित अक्षर से बचने के तीन रास्ते थे। उसे किसी पर्याय या मिलती-जुलती ध्वनि से बदल दें, जगह ख़ाली छोड़ दें, या एक रेखा छोड़ दें, आम तौर पर आख़िरी। कांगशी सम्राट का नाम श्वानये था, 玄燁, इसलिए निषिद्ध नगर का काला योद्धा द्वार, 玄武門, दिव्य शक्ति द्वार, 神武門, बन गया। वह नाम आज भी है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.92\" data-lng=\"116.39\" data-zoom=\"7\">📍 बीजिंग पर जाएँ</button></div><p>नियम क्लासिक ग्रंथों तक पहुँचा। प्रथम सम्राट का निजी नाम झंग था, 政, इसलिए साल के पहले महीने, 正月, का उच्चारण बदला गया और फिर उसका नाम 端月 रखा गया। हान काल में लिउ बांग के नाम 邦 ने <em>Daodejing</em> के वाक्यांश 邦家 को 國家 कर दिया। सम्राट वेन के नाम 恆 ने उसी ग्रंथ में 恆 को 常 कर दिया, उसकी शुरुआती पंक्ति समेत, और हंग पर्वत का नाम बदलवाया। चंद्र-देवी 姮娥 मिलती-जुलती ध्वनि वाले अक्षर से 嫦娥 बन गईं, वह नाम जो आज उनका है।</p><h3>सम्राट जिन्होंने मदद चाही</h3><p>थांग के सम्राट थाइज़ोंग का नाम शिमिन था, 世民, दो बहुत आम अक्षर, और उन्होंने नियम नरम करने की कोशिश की कि बचना तभी ज़रूरी हो जब जोड़ा साथ आए। उनके बेटे ने यह रद्द कर दिया। 世 को आम तौर पर 代 से बदला गया और 民 को 人 से, उच्चारण <strong>rén</strong>, और सेनापति ली शिजी ली जी बन गए। लिउ ज़ोंगयुआन की एक पंक्ति में 人風, “लोगों की चाल”, इसी कारण ऐसा लिखा गया: उनका आशय 民風 से था।</p><p>कुछ सम्राटों ने लिहाज़ करने की कोशिश की। हान के सम्राट श्वान ने प्रजा का जीवन आसान करने के लिए अपना नाम बिंगयी, 病已, से बदलकर ज़्यादा दुर्लभ शुन, 詢, कर लिया, और बाद के राजवंशों ने इसी कारण राजकुमारों को असामान्य नाम दिए। एक बुनियादी समस्या बनी रही: नाम से बचने के लिए नाम जानना ज़रूरी था। 435 में गोगुरियो के राजदूतों ने उत्तरी वेई दरबार से औपचारिक रूप से सम्राटों के नामों की सूची वाला दस्तावेज़ माँगा ताकि कोई अपमान न हो, और सम्राट मान गए।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🗺️ 人 दिखाएँ</button></div><h3>क़ीमत</h3><p>पूरे-पूरे शहर इसकी चपेट में आए। च्येनये, आज का नानजिंग, एक सम्राट के नाम की ध्वनि के कारण च्येनकांग कर दिया गया। कुलनाम भी बदले: कुलनाम श्वाई, 帥, शी, 師, से एक रेखा छोड़कर बना, सिमा शी की ख़ातिर। और दंड सचमुच मिलते थे। 1777 में वांग शीहोउ ने अपने बनाए एक शब्दकोश में कांगशी शब्दकोश की आलोचना की। उसी में उन्होंने छ्येनलोंग सम्राट का वर्जित नाम पूरा लिख दिया, और उन्हें मृत्युदंड मिला। इतिहासकारों के लिए इन वर्जनाओं का एक उपयोग है। बदला हुआ अक्षर बता सकता है कि कोई ग्रंथ किसके शासन में नक़ल हुआ।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"32.06\" data-lng=\"118.8\" data-zoom=\"7\">📍 नानजिंग पर जाएँ</button></div>","shuowen-540":"<p>मूलांशों के अनुसार बने पहले चीनी शब्दकोश की पहली प्रविष्टि 一 है, “एक”, आज का उच्चारण <strong>yī</strong>। आख़िरी खंड 亥 पर ख़त्म होता है, अंतिम पार्थिव शाखा। इन दोनों के बीच शू शन ने 9,353 अक्षर 540 खंडों में बाँटे, और ये संख्याएँ वे अपने उपसंहार में ख़ुद देते हैं, साथ में 1,163 लिखित रूपभेद और कुल लंबाई 1,33,441 अक्षर। आधुनिक संस्करणों में, सदियों की नक़ल और सुधार के बाद, 9,831 अक्षर और 1,279 रूपभेद हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"一\">🗺️ 一 दिखाएँ</button></div><h3>शब्दों को रखने का नया ढंग</h3><p>शू ने <em>Shuowen Jiezi</em> वर्ष 100 में पूर्वी हान के समय पूरा किया। विद्या के प्रति दरबार के प्रतिकूल रुख़ ने उन्हें 121 तक रोके रखा, जब उनके बेटे शू छोंग ने इसे सम्राट आन को भेंट किया। यह तटस्थ परियोजना नहीं थी। शू ऐसी दुनिया में काम कर रहे थे जो मानती थी कि सही नाम अच्छे शासन की बुनियाद हैं, और उनका उपसंहार लेखन को क्लासिक ग्रंथों की जड़ और राजशासन का स्रोत कहता है।</p><p><em>Erya</em> जैसे पहले के संदर्भ ग्रंथ शब्दों को अर्थ के अनुसार ढीले ढंग से समूहित करते और पर्याय गिनाते थे। शू का नया विचार था अक्षरों को एक साझा लिखित हिस्से के आधार पर रखना, उस खंड-शीर्षक से जिसे हम अब मूलांश कहते हैं। इस किताब के आधुनिक विद्वान बोल्ट्ज़ इसे एक बड़ा वैचारिक नवाचार कहते हैं। पर शू के शीर्षक आधुनिक सूची जैसे बिल्कुल नहीं दिखते। वे ऐसा अटूट क्रम चाहते थे जिसमें हर शीर्षक स्वाभाविक रूप से अगले तक ले जाए, और वह ब्रह्मांड को दर्शाए। इसलिए 炎, “लपट”, और 熊, “भालू”, को अपने शीर्षक मिलते हैं, जबकि आधुनिक शब्दकोश दोनों को 火, <strong>huǒ</strong>, के नीचे रखता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"火\">🗺️ 火 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"心\">🗺️ 心 दिखाएँ</button></div><h3>ख़ाली दराज़ें</h3><p>इस ढाँचे के कुछ अजीब नतीजे हैं। सभी दस आकाशीय तने और बारह पार्थिव शाखाएँ खंड-शीर्षक हैं। चौंतीस शीर्षकों में एक भी अक्षर नहीं, और 159 में केवल एक है। दुर्लभ 惢 ऐसा शीर्षक है जिसके नीचे सिर्फ़ 繠, “पुंकेसर”, है, जबकि आधुनिक संकलक उसे बस 心, <strong>xīn</strong>, “हृदय”, के नीचे रख देगा।</p><p>एक आम प्रविष्टि मुहर-लिपि का रूप, छोटी परिभाषा, अक्सर एक पर्याय, फिर ध्वनि और हिस्सों का विश्लेषण देती है। ध्वनि समध्वनि शब्द से दी जाती थी, 讀若, “जैसे पढ़ें”, के सूत्र में, क्योंकि तब तक इससे बेहतर तरीक़ा नहीं था। वह कमी बाद में फ़ानछिए ने भरी। शू ने अक्षरों के वर्गीकरण के “छह सिद्धांतों” की पहली परिभाषाएँ और उदाहरण भी दिए, और उनकी प्रविष्टियाँ अक्सर पुराने “प्राचीन लिपि” और झोउ लिपि के रूप जोड़ती हैं।</p><h3>ओरेकल हड्डियों के बाद</h3><p>उनके ध्वनि-नोट पुरानी चीनी के काल के हैं, इसीलिए नक्शे पर 一 का रूप <strong>*ʔi[t]</strong> <em>yī</em> से इतना दूर है। उनका विश्लेषण भी पुराना पड़ चुका है। शू मुहर-लिपि से काम करते थे, और उन्होंने कहीं पुरानी ओरेकल हड्डियाँ कभी नहीं देखीं, जो 19वीं सदी के अंत में ही सामने आईं। आज यह किताब परिभाषाओं या अक्षरों की बनावट पर प्रमाण नहीं मानी जाती। पर अक्षरों को उनके हिस्सों के आधार पर रखने वाली यह पहली किताब थी, और शब्दकोश आज भी यही करते हैं।</p>","wu-zetian-characters":"<p>दिसंबर 689 में जोंग छिन्के नाम के एक अधिकारी ने, जो वू ज़ेतियान के एक चचेरे भाई के बेटे थे, नए चीनी अक्षरों का एक समूह प्रस्तावित किया। वू ने, जो जल्द ही चीनी इतिहास की अकेली शासक साम्राज्ञी बनने वाली थीं, उन्हें अपना लिया, और प्रजा को उन्हें इस्तेमाल करने पर मजबूर किया गया। वे कितने थे, इस पर कोई सहमति नहीं। गिनती 12, 17, 19 और 30 के बीच बदलती है। वे शून्य से नहीं गढ़े गए। हर एक ने पुराने अक्षरों के तत्व उधार लिए, नए क्रम में, ताकि लेखन ख़ुद उनके शासन के बारे में कुछ कहे।</p><h3>आकाश के ऊपर सूर्य और चंद्र</h3><p>पहला उनका अपना नाम था। उनका नाम 照 था, “चमकना”, और उसकी जगह आया 曌, जो आकाश के ऊपर सूर्य और चंद्र से बना है। पूरे कार्यक्रम का यह सबसे साफ़ उदाहरण है, क्योंकि 日, मंदारिन में उच्चारण <strong>rì</strong>, और 月, उच्चारण <strong>yuè</strong>, 空, “आकाश”, के ऊपर बैठे हैं, यिन और यांग के सामंजस्य के दावे के तौर पर। शब्दकोशों में एक रूपभेद भी दर्ज है, 瞾, जिसमें सूर्य और चंद्र की जगह दो आँखें हैं, और कांगशी शब्दकोश में यही रूप मिलता है। पुराने रूप में नाम लिखना भी ख़तरनाक हो गया: उनके पोते ली छोंगझाओ को इससे बचने के लिए नाम बदलना पड़ा।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"日\">🗺️ 日 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"月\">🗺️ 月 दिखाएँ</button></div><p>प्रकृति का भी नया चित्र बना। धरती का नया अक्षर 埊 पहाड़, पानी और मिट्टी को ऊपर-नीचे रखता था, तीन शब्द जिन्हें हान्ज़ी मानचित्र मंदारिन में <strong>shān</strong>, <strong>shuǐ</strong> और <strong>tǔ</strong> देता है। नया सूर्य चीनी मिथक का तीन पैरों वाला कौआ दिखाता बताया गया, और नया चंद्र ख़रगोश या मेंढक। तारा ख़ाली घेरा बन गया, 〇। नए रूपों वाला एक शिलालेख वू की अपनी लिखावट में बचा है, 升仙太子碑।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"山\">🗺️ 山 दिखाएँ</button></div><h3>वादे के रूप में पंचांग</h3><p>दूसरे अक्षर नारों जैसे लगते हैं। मंत्री का नया शब्द 𢘑 “एक” और “वफ़ादारी” को जोड़ता था, प्रजा का कर्तव्य। शासक के नए शब्द में 天大吉 था, यानी उनके कारण दुनिया बड़े सौभाग्य में है। नया 年, “वर्ष”, उच्चारण <strong>nián</strong>, 千千万万 से बना था, हज़ारों पर हज़ार, ताकि पंचांग ख़ुद लंबे शासन का वादा करे। नया 人, “व्यक्ति”, उच्चारण <strong>rén</strong>, “जीवन” के ऊपर “एक” था, जिसका अर्थ बताया गया कि हर कोई एक ही बार जीता है। “मिटाना” का नया शब्द 𠀺 天, “स्वर्ग”, को “उठना” से जोड़ता था: स्वर्ग ने साम्राज्ञी को उठने दिया ताकि वे पुरानी दुनिया बुहार दें।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"人\">🗺️ 人 दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setchar\" data-char=\"年\">🗺️ 年 दिखाएँ</button></div><h3>जो बच गया</h3><p>रोज़ के इस्तेमाल में इनमें से कुछ भी उनके बाद नहीं टिका। उनकी मृत्यु के तुरंत बाद अक्षर चलन से बाहर हो गए, और इसी से आज उनका एक अजीब उपयोग है: वे छपी सामग्री की तिथि तय करने में मदद करते हैं, क्योंकि जिस पाठ में वे मिलें, वह एक छोटे दौर का ही हो सकता है। कुछ अक्षर शब्दकोशों में बच निकले, और एक ने तो दूर की यात्रा की। “देश” का नया अक्षर 圀 八方, आठ दिशाओं, को एक सीमा के भीतर रखता था। सदियों बाद वह जापानी सामंत तोकुगावा मित्सुकुनी के नाम में मिलता है, 徳川光圀, जापानी शब्द <em>kuni</em> से पढ़ा गया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"36.37\" data-lng=\"140.47\" data-zoom=\"6\">📍 जापान पर जाएँ</button></div><p>सबसे अच्छा नसीब घेरे का रहा। वह तारे के लिए बना था, और आधुनिक चीनी में वही चिह्न, 〇, शून्य का अंक है।</p>"};
